/**
 * Decoder for {@link EncodedGraph encoded graphs} produced by {@link GraphEncoder}. Support for
 * loop explosion during decoding is built into this class, because it requires many interactions
 * with the decoding process. Subclasses can provide canonicalization and simplification of nodes
 * during decoding, as well as method inlining during decoding.
 */
public class GraphDecoder {

    /** Decoding state maintained for each encoded graph. */
    protected class MethodScope {
        /** The loop that contains the call. Only non-null during method inlining. */
        public final LoopScope callerLoopScope;
        /**
         * Mark for nodes that were present before the decoding of this method started. Note that
         * nodes that were decoded after the mark can still be part of an outer method, since
         * floating nodes of outer methods are decoded lazily.
         */
        public final Graph.Mark methodStartMark;
        /** The encode graph that is decoded. */
        public final EncodedGraph encodedGraph;
        /** The highest node order id that a fixed node has in the EncodedGraph. */
        public final int maxFixedNodeOrderId;
        /**
         * Number of bytes needed to encode an order id (order ids have a per-encoded-graph fixed
         * size).
         */
        public final int orderIdWidth;
        /** Access to the encoded graph. */
        public final TypeReader reader;
        /** The kind of loop explosion to be performed during decoding. */
        public final LoopExplosionPlugin.LoopExplosionKind loopExplosion;

        /** All return nodes encountered during decoding. */
        public final List<ControlSinkNode> returnAndUnwindNodes;

        /** All merges created during loop explosion. */
        public final EconomicSet<Node> loopExplosionMerges;

        /**
         * The start of explosion, and the merge point for when irreducible loops are detected. Only
         * used when {@link MethodScope#loopExplosion} is
         * {@link jdk.graal.compiler.nodes.graphbuilderconf.LoopExplosionPlugin.LoopExplosionKind#MERGE_EXPLODE}.
         */
        public MergeNode loopExplosionHead;

        /**
         * The decoded inlining log. If this is the root method scope, it
         * {@link StructuredGraph#setInliningLog replaces} the inlining log of the graph. Otherwise,
         * the inlining log is {@link InliningLog#inlineByTransfer transferred} to the caller.
         */
        public InliningLog inliningLog;

        /**
         * The decoded optimization log. If this is the root method scope, it
         * {@link StructuredGraph#setOptimizationLog replaces} the optimization log of the graph.
         * Otherwise, the optimization log is {@link OptimizationLog#inline inlined} in the caller.
         */
        public OptimizationLog optimizationLog;

        /**
         * The stateful decoder for the {@link #inliningLog}, which is needed to map order IDs back
         * to decoded graph nodes. The decoder is also responsible for tracking new callsites in the
         * inlining log. {@code null} if the inlining log is not being decoded.
         */
        public InliningLogCodec.InliningLogDecoder inliningLogDecoder;

        @SuppressWarnings("unchecked")
        protected MethodScope(LoopScope callerLoopScope, StructuredGraph graph, EncodedGraph encodedGraph, LoopExplosionPlugin.LoopExplosionKind loopExplosion) {
            this.callerLoopScope = callerLoopScope;
            this.methodStartMark = graph.getMark();
            this.encodedGraph = encodedGraph;
            this.loopExplosion = loopExplosion;
            this.returnAndUnwindNodes = new ArrayList<>(2);

            if (encodedGraph != null) {
                reader = UnsafeArrayTypeReader.create(encodedGraph.getEncoding(), encodedGraph.getStartOffset(), architecture.supportsUnalignedMemoryAccess());
                maxFixedNodeOrderId = reader.getUVInt();
                GraphState.GuardsStage guardsStage = (GraphState.GuardsStage) readObject(this);
                EnumSet<GraphState.StageFlag> stageFlags = (EnumSet<GraphState.StageFlag>) readObject(this);
                if (callerLoopScope == null) {
                    /**
                     * Only propagate stage flags in non-inlining scenarios. If the caller scope has
                     * not been guard lowered yet (or is a runtime compilation) while we inline
                     * something that has been guard lowered already (or is an encoded hosted graph
                     * like a snippet) do not advance stage flags or guards stage.
                     */
                    graph.getGraphState().setGuardsStage(guardsStage);
                    graph.getGraphState().getStageFlags().addAll(stageFlags);
                }

                var decoderPair = InliningLogCodec.maybeDecode(graph, readObject(this));
                if (decoderPair != null) {
                    inliningLogDecoder = decoderPair.getLeft();
                    inliningLog = decoderPair.getRight();
                }
                optimizationLog = OptimizationLogCodec.maybeDecode(graph, readObject(this));

                int nodeCount = reader.getUVInt();
                if (encodedGraph.nodeStartOffsets == null) {
                    int[] nodeStartOffsets = new int[nodeCount];
                    for (int i = 0; i < nodeCount; i++) {
                        nodeStartOffsets[i] = encodedGraph.getStartOffset() - reader.getUVInt();
                    }
                    encodedGraph.nodeStartOffsets = nodeStartOffsets;
                }

                if (nodeCount <= GraphEncoder.MAX_INDEX_1_BYTE) {
                    orderIdWidth = 1;
                } else if (nodeCount <= GraphEncoder.MAX_INDEX_2_BYTES) {
                    orderIdWidth = 2;
                } else {
                    orderIdWidth = 4;
                }
            } else {
                reader = null;
                maxFixedNodeOrderId = 0;
                orderIdWidth = 0;
            }

            if (loopExplosion.useExplosion()) {
                loopExplosionMerges = EconomicSet.create(Equivalence.IDENTITY);
            } else {
                loopExplosionMerges = null;
            }
        }

        public boolean isInlinedMethod() {
            return false;
        }

        public NodeSourcePosition getCallerNodeSourcePosition() {
            return null;
        }

        public NodeSourcePosition getNodeSourcePosition(NodeSourcePosition position) {
            return position;
        }

        /**
         * Sets the {@link #inliningLog} and {@link #optimizationLog} as the logs of the
         * {@link #graph} if they are non-null.
         */
        public void replaceLogsForDecodedGraph() {
            if (inliningLog != null) {
                graph.setInliningLog(inliningLog);
            }
            if (optimizationLog != null) {
                graph.setOptimizationLog(optimizationLog);
            }
        }
    }

    /**
     * Marker to distinguish the reasons for the creation of a loop scope during partial evaluation.
     */
    public enum LoopScopeTrigger {
        /**
         * Start loop scope: creation triggered manually at the beginning of partial evaluation.
         */
        START,

        /**
         * Loop scope created for the next iteration of a loop if unrolling is enabled in the loop
         * explosion mode. See
         * {@link jdk.graal.compiler.nodes.graphbuilderconf.LoopExplosionPlugin.LoopExplosionKind#unrollLoops()}
         * for details. Loop unrolling will merge loop end nodes for each iteration of the original
         * loop.
         */
        LOOP_BEGIN_UNROLLING,

        /**
         * Loop scope created for the next iteration of a loop along a particular loop end node if
         * {@link jdk.graal.compiler.nodes.graphbuilderconf.LoopExplosionPlugin.LoopExplosionKind#duplicateLoopEnds()}
         * is enabled and loops are exploded. This means for every loop end we duplicate the next
         * loop iteration of the original loop.
         */
        LOOP_END_DUPLICATION,

        /**
         * Loop scope created for a loop exit node if
         * {@link jdk.graal.compiler.nodes.graphbuilderconf.LoopExplosionPlugin.LoopExplosionKind#duplicateLoopExits()}
         * is enabled, i.e., code after a loop exit is duplicated per loop exit node.
         *
         * Special case nested loops: For compilation units with nested loops where inner loops
         * continue loops at a level n -1 the partial evaluation algorithm will merge outer loops to
         * avoid loop explosion along loop end nodes (which would be the same as
         * {@link #LOOP_END_DUPLICATION}.
         */
        LOOP_EXIT_DUPLICATION
    }

    /** Decoding state maintained for each loop in the encoded graph. */
    protected static class LoopScope {
        public final MethodScope methodScope;
        public final LoopScope outer;
        public final int loopDepth;
        public final int loopIteration;

        /**
         * Creation trigger of this particular loop scope, i.e., the reason it was created.
         */
        final LoopScopeTrigger trigger;
        /**
         * Upcoming, not yet processed, loop iterations created in the context of code duplication
         * along loop exits. Only used when {@link MethodScope#loopExplosion} has
         * {@link jdk.graal.compiler.nodes.graphbuilderconf.LoopExplosionPlugin.LoopExplosionKind#duplicateLoopExits()}
         * enabled.
         */
        public Deque<LoopScope> nextIterationFromLoopExitDuplication;
        /**
         * Same as {@link #nextIterationFromLoopExitDuplication} except that upcoming iterations
         * have been created because the duplication of loop ends
         * {@link jdk.graal.compiler.nodes.graphbuilderconf.LoopExplosionPlugin.LoopExplosionKind#duplicateLoopEnds()}
         * is enabled.
         */
        public Deque<LoopScope> nextIterationFromLoopEndDuplication;
        /**
         * Same as {@link #nextIterationFromLoopExitDuplication} except that upcoming iterations
         * have been created because the unrolling of a loop with constant iteration count
         * {@link jdk.graal.compiler.nodes.graphbuilderconf.LoopExplosionPlugin.LoopExplosionKind#unrollLoops()}
         * is enabled.
         */
        public Deque<LoopScope> nextIterationsFromUnrolling;
        /**
         * Information about already processed loop iterations for state merging during loop
         * explosion. Only used when {@link MethodScope#loopExplosion} is
         * {@link jdk.graal.compiler.nodes.graphbuilderconf.LoopExplosionPlugin.LoopExplosionKind#MERGE_EXPLODE}.
         */
        public final EconomicMap<LoopExplosionState, LoopExplosionState> iterationStates;
        public final int loopBeginOrderId;
        /**
         * The worklist of fixed nodes to process. Since we already the correct processing order
         * from the orderId, we just set the orderId bit in the bitset when a node is ready for
         * processing. The lowest set bit is the next node to process.
         */
        public final BitSet nodesToProcess;
        /** Nodes that have been created, indexed by the orderId. */
        public final Node[] createdNodes;
        /**
         * Nodes that have been created in outer loop scopes and existed before starting to process
         * this loop, indexed by the orderId. Only used when {@link MethodScope#loopExplosion} is
         * not
         * {@link jdk.graal.compiler.nodes.graphbuilderconf.LoopExplosionPlugin.LoopExplosionKind#NONE}.
         */
        public final Node[] initialCreatedNodes;

        protected LoopScope(MethodScope methodScope) {
            this.methodScope = methodScope;
            this.outer = null;
            this.nextIterationFromLoopExitDuplication = methodScope.loopExplosion.duplicateLoopExits() || methodScope.loopExplosion.mergeLoops() ? new ArrayDeque<>(2) : null;
            this.nextIterationFromLoopEndDuplication = methodScope.loopExplosion.duplicateLoopEnds() ? new ArrayDeque<>(2) : null;
            this.nextIterationsFromUnrolling = methodScope.loopExplosion.unrollLoops() ? new ArrayDeque<>(2) : null;
            this.loopDepth = 0;
            this.loopIteration = 0;
            this.iterationStates = null;
            this.loopBeginOrderId = -1;
            int nodeCount = methodScope.encodedGraph.nodeStartOffsets.length;
            this.nodesToProcess = new BitSet(methodScope.maxFixedNodeOrderId);
            this.createdNodes = new Node[nodeCount];
            this.initialCreatedNodes = null;
            this.trigger = LoopScopeTrigger.START;
        }

        protected LoopScope(MethodScope methodScope, LoopScope outer, int loopDepth, int loopIteration, int loopBeginOrderId, LoopScopeTrigger trigger, Node[] initialCreatedNodes, Node[] createdNodes,
                        Deque<LoopScope> nextIterationFromLoopExitDuplication,
                        Deque<LoopScope> nextIterationFromLoopEndDuplication,
                        Deque<LoopScope> nextIterationsFromUnrolling, EconomicMap<LoopExplosionState, LoopExplosionState> iterationStates) {
            this.methodScope = methodScope;
            this.outer = outer;
            this.loopDepth = loopDepth;
            this.loopIteration = loopIteration;
            this.trigger = trigger;
            this.nextIterationFromLoopExitDuplication = nextIterationFromLoopExitDuplication;
            this.nextIterationFromLoopEndDuplication = nextIterationFromLoopEndDuplication;
            this.nextIterationsFromUnrolling = nextIterationsFromUnrolling;
            this.iterationStates = iterationStates;
            this.loopBeginOrderId = loopBeginOrderId;
            this.nodesToProcess = new BitSet(methodScope.maxFixedNodeOrderId);
            this.initialCreatedNodes = initialCreatedNodes;
            this.createdNodes = createdNodes;
        }

        @Override
        public String toString() {
            return loopDepth + "," + loopIteration + (loopBeginOrderId == -1 ? "" : "#" + loopBeginOrderId) + " triggered by " + trigger;
        }

        /**
         * Determines if iterations generated when decoding this loop have yet to be processed.
         *
         * @return {@code true} if there are iterations to be decoded, {@code false} else
         */
        public boolean hasIterationsToProcess() {
            return nextIterationFromLoopEndDuplication != null && !nextIterationFromLoopEndDuplication.isEmpty() ||
                            nextIterationFromLoopExitDuplication != null && !nextIterationFromLoopExitDuplication.isEmpty() ||
                            nextIterationsFromUnrolling != null && !nextIterationsFromUnrolling.isEmpty();
        }

        /**
         * Return the next iteration yet to be processed that has been created in the context of
         * decoding this loop scope.
         *
         * @param remove determines if the query of the next iteration should remove it from the
         *            list of iterations to be processed
         * @return the next {@link LoopScope} to be processed that has been created in the context
         *         of decoding this loop scope. Note that the order is not necessarily reflecting
         *         the number of loop iterations.
         */
        public LoopScope getNextIterationToProcess(boolean remove) {
            if (nextIterationFromLoopEndDuplication != null && !nextIterationFromLoopEndDuplication.isEmpty()) {
                return remove ? nextIterationFromLoopEndDuplication.removeFirst() : nextIterationFromLoopEndDuplication.peekFirst();
            }
            if (nextIterationFromLoopExitDuplication != null && !nextIterationFromLoopExitDuplication.isEmpty()) {
                return remove ? nextIterationFromLoopExitDuplication.removeFirst() : nextIterationFromLoopExitDuplication.peekFirst();
            }
            if (nextIterationsFromUnrolling != null && !nextIterationsFromUnrolling.isEmpty()) {
                return remove ? nextIterationsFromUnrolling.removeFirst() : nextIterationsFromUnrolling.peekFirst();
            }
            return null;
        }
    }

    protected static class LoopExplosionState {
        public final FrameState state;
        public final MergeNode merge;
        public final int hashCode;

        protected LoopExplosionState(FrameState state, MergeNode merge) {
            this.state = state;
            this.merge = merge;

            int h = 0;
            for (ValueNode value : state.values()) {
                if (value == null) {
                    h = h * 31 + 1234;
                } else {
                    h = h * 31 + ProxyPlaceholder.unwrap(value).hashCode();
                }
            }
            this.hashCode = h;
        }

        @Override
        public boolean equals(Object obj) {
            if (!(obj instanceof LoopExplosionState)) {
                return false;
            }

            FrameState otherState = ((LoopExplosionState) obj).state;
            FrameState thisState = state;
            assert thisState.outerFrameState() == otherState.outerFrameState() : Assertions.errorMessage(thisState, thisState.outerFrameState(), otherState, otherState.outerFrameState());

            Iterator<ValueNode> thisIter = thisState.values().iterator();
            Iterator<ValueNode> otherIter = otherState.values().iterator();
            while (thisIter.hasNext() && otherIter.hasNext()) {
                ValueNode thisValue = ProxyPlaceholder.unwrap(thisIter.next());
                ValueNode otherValue = ProxyPlaceholder.unwrap(otherIter.next());
                if (thisValue != otherValue) {
                    return false;
                }
            }
            return thisIter.hasNext() == otherIter.hasNext();
        }

        @Override
        public int hashCode() {
            return hashCode;
        }
    }

    protected static class InvokableData<T extends Invokable> {
        public final T invoke;
        public final ResolvedJavaType contextType;
        public final int orderId;
        public final int stateAfterOrderId;
        public final int nextOrderId;
        public final int exceptionOrderId;
        public final int exceptionStateOrderId;
        public final int exceptionNextOrderId;

        protected InvokableData(T invoke, ResolvedJavaType contextType, int orderId, int stateAfterOrderId, int nextOrderId,
                        int exceptionOrderId, int exceptionStateOrderId, int exceptionNextOrderId) {
            this.invoke = invoke;
            this.contextType = contextType;
            this.orderId = orderId;
            this.stateAfterOrderId = stateAfterOrderId;
            this.nextOrderId = nextOrderId;
            this.exceptionOrderId = exceptionOrderId;
            this.exceptionStateOrderId = exceptionStateOrderId;
            this.exceptionNextOrderId = exceptionNextOrderId;
        }
    }

    /**
     * Additional information encoded for {@link Invoke} nodes to allow method inlining without
     * decoding the frame state and successors beforehand.
     */
    protected static class InvokeData extends InvokableData<Invoke> {
        static InvokeData createFrom(InvokableData<? extends Invoke> from, int callTargetOrderId, boolean intrinsifiedMethodHandle) {
            return new InvokeData(from.invoke, from.contextType, from.orderId, callTargetOrderId, intrinsifiedMethodHandle,
                            from.stateAfterOrderId, from.nextOrderId, from.exceptionOrderId, from.exceptionStateOrderId, from.exceptionNextOrderId);
        }

        public final int callTargetOrderId;
        public final boolean intrinsifiedMethodHandle;

        public JavaConstant constantReceiver;
        public CallTargetNode callTarget;
        public FixedWithNextNode invokePredecessor;

        public InvokeData(Invoke invoke, ResolvedJavaType contextType, int invokeOrderId, int callTargetOrderId, boolean intrinsifiedMethodHandle,
                        int stateAfterOrderId, int nextOrderId, int exceptionOrderId, int exceptionStateOrderId, int exceptionNextOrderId) {
            super(invoke, contextType, invokeOrderId, stateAfterOrderId, nextOrderId, exceptionOrderId, exceptionStateOrderId, exceptionNextOrderId);
            this.callTargetOrderId = callTargetOrderId;
            this.intrinsifiedMethodHandle = intrinsifiedMethodHandle;
        }
    }

    /**
     * A node that is created during
     * {@link jdk.graal.compiler.nodes.graphbuilderconf.LoopExplosionPlugin.LoopExplosionKind#MERGE_EXPLODE
     * loop explosion} that can later be replaced by a ProxyNode if {@link LoopDetector loop
     * detection} finds out that the value is defined in the loop, but used outside the loop.
     */
    @NodeInfo(cycles = CYCLES_IGNORED, size = SIZE_IGNORED)
    protected static final class ProxyPlaceholder extends FloatingNode implements Canonicalizable {
        public static final NodeClass<ProxyPlaceholder> TYPE = NodeClass.create(ProxyPlaceholder.class);

        @Input ValueNode value;
        @Input(InputType.Association) Node proxyPoint;

        public ProxyPlaceholder(ValueNode value, MergeNode proxyPoint) {
            super(TYPE, value.stamp(NodeView.DEFAULT));
            this.value = value;
            this.proxyPoint = proxyPoint;
        }

        void setValue(ValueNode value) {
            updateUsages(this.value, value);
            this.value = value;
        }

        @Override
        public Node canonical(CanonicalizerTool tool) {
            if (tool.allUsagesAvailable()) {
                /* The node is always unnecessary after graph decoding. */
                return value;
            } else {
                return this;
            }
        }

        public static ValueNode unwrap(ValueNode value) {
            ValueNode result = value;
            while (result instanceof ProxyPlaceholder) {
                result = ((ProxyPlaceholder) result).value;
            }
            return result;
        }
    }

    private static final TimerKey MakeSuccessorStubsTimer = DebugContext.timer("PartialEvaluation-MakeSuccessorStubs").doc("Time spent in making successor stubs for the PE.");
    private static final TimerKey ReadPropertiesTimer = DebugContext.timer("PartialEvaluation-ReadProperties").doc("Time spent in reading node properties in the PE.");

    protected final Architecture architecture;
    /** The target graph where decoded nodes are added to. */
    protected final StructuredGraph graph;
    protected final OptionValues options;
    protected final DebugContext debug;

    private final EconomicMap<NodeClass<?>, ArrayDeque<Node>> reusableFloatingNodes;

    public GraphDecoder(Architecture architecture, StructuredGraph graph) {
        this.architecture = architecture;
        this.graph = graph;
        this.options = graph.getOptions();
        this.debug = graph.getDebug();
        reusableFloatingNodes = EconomicMap.create(Equivalence.IDENTITY);
    }

    public final void decode(EncodedGraph encodedGraph) {
        decode(encodedGraph, null);
    }

    @SuppressWarnings("try")
    public final void decode(EncodedGraph encodedGraph, Iterable<EncodedGraph.EncodedNodeReference> nodeReferences) {
        try (DebugContext.Scope scope = debug.scope("GraphDecoder", graph)) {
            recordGraphElements(encodedGraph);
            MethodScope methodScope = new MethodScope(null, graph, encodedGraph, LoopExplosionPlugin.LoopExplosionKind.NONE);
            LoopScope loopScope = createInitialLoopScope(methodScope, null);
            decode(loopScope);
            cleanupGraph(methodScope);
            assert graph.verify();

            if (nodeReferences != null) {
                for (var nodeReference : nodeReferences) {
                    if (nodeReference.orderId < 0) {
                        throw GraalError.shouldNotReachHere("EncodeNodeReference is not in 'encoded' state"); // ExcludeFromJacocoGeneratedReport
                    }
                    nodeReference.node = loopScope.createdNodes[nodeReference.orderId];
                    if (nodeReference.node == null || !nodeReference.node.isAlive()) {
                        throw GraalError.shouldNotReachHere("Could not decode the EncodedNodeReference"); // ExcludeFromJacocoGeneratedReport
                    }
                    nodeReference.orderId = EncodedGraph.EncodedNodeReference.DECODED;
                }
            }

            maybeMarkUnsafeAccess(encodedGraph);
        } catch (Throwable ex) {
            debug.handle(ex);
        }
    }

    private void maybeMarkUnsafeAccess(EncodedGraph encodedGraph) {
        if (encodedGraph.hasUnsafeAccess()) {
            graph.markUnsafeAccess();
        }
    }

    protected void recordGraphElements(EncodedGraph encodedGraph) {
        List<ResolvedJavaMethod> inlinedMethods = encodedGraph.getInlinedMethods();
        if (inlinedMethods != null) {
            for (ResolvedJavaMethod other : inlinedMethods) {
                graph.recordMethod(other);
            }
        }
        Assumptions assumptions = graph.getAssumptions();
        Assumptions inlinedAssumptions = encodedGraph.getAssumptions();
        if (assumptions != null) {
            if (inlinedAssumptions != null) {
                assumptions.record(inlinedAssumptions);
            }
        } else {
            assert inlinedAssumptions == null : String.format("cannot inline graph (%s) which makes assumptions into a graph (%s) that doesn't", encodedGraph, graph);
        }
        if (encodedGraph.hasUnsafeAccess()) {
            graph.markUnsafeAccess();
        }
    }

    protected final LoopScope createInitialLoopScope(MethodScope methodScope, FixedWithNextNode startNode) {
        LoopScope loopScope = new LoopScope(methodScope);
        FixedNode firstNode;
        if (startNode != null) {
            /*
             * The start node of a graph can be referenced as the guard for a GuardedNode. We
             * register the previous block node, so that such guards are correctly anchored when
             * doing inlining during graph decoding.
             */
            registerNode(loopScope, GraphEncoder.START_NODE_ORDER_ID, AbstractBeginNode.prevBegin(startNode), false, false);

            firstNode = makeStubNode(methodScope, loopScope, GraphEncoder.FIRST_NODE_ORDER_ID);
            startNode.setNext(firstNode);
            loopScope.nodesToProcess.set(GraphEncoder.FIRST_NODE_ORDER_ID);
        } else {
            firstNode = graph.start();
            registerNode(loopScope, GraphEncoder.START_NODE_ORDER_ID, firstNode, false, false);
            loopScope.nodesToProcess.set(GraphEncoder.START_NODE_ORDER_ID);
        }
        return loopScope;
    }

    @SuppressWarnings("try")
    protected final void decode(LoopScope initialLoopScope) {
        initialLoopScope.methodScope.replaceLogsForDecodedGraph();
        try (InliningLog.UpdateScope updateScope = InliningLog.openDefaultUpdateScope(graph.getInliningLog())) {
            LoopScope loopScope = initialLoopScope;
            /* Process (inlined) methods. */
            while (loopScope != null) {
                MethodScope methodScope = loopScope.methodScope;

                /* Process loops of method. */
                while (loopScope != null) {
                    /* Process nodes of loop. */
                    while (!loopScope.nodesToProcess.isEmpty()) {
                        loopScope = processNextNode(methodScope, loopScope);
                        methodScope = loopScope.methodScope;
                        /*
                         * We can have entered a new loop, and we can have entered a new inlined
                         * method.
                         */
                    }

                    /* Finished with a loop. */
                    if (loopScope.hasIterationsToProcess()) {
                        loopScope = loopScope.getNextIterationToProcess(true);
                    } else {
                        propagateCreatedNodes(loopScope);
                        loopScope = loopScope.outer;

                        if (loopScope == null) {
                            // finished all loops of a method
                            afterMethodScope(methodScope);
                        }
                    }
                }

                /*
                 * Finished with an inlined method. Perform end-of-method cleanup tasks.
                 */
                if (methodScope.loopExplosion.mergeLoops()) {
                    LoopDetector loopDetector = new LoopDetector(graph, methodScope);
                    loopDetector.run();
                }
                if (methodScope.isInlinedMethod()) {
                    finishInlining(methodScope);
                }

                /* continue with the caller */
                loopScope = methodScope.callerLoopScope;
            }
        }
    }

    protected void afterMethodScope(@SuppressWarnings("unused") MethodScope methodScope) {
    }

    protected void finishInlining(@SuppressWarnings("unused") MethodScope inlineScope) {
    }

    private static void propagateCreatedNodes(LoopScope loopScope) {
        if (loopScope.outer == null || loopScope.createdNodes != loopScope.outer.createdNodes) {
            return;
        }

        /* Register nodes that were created while decoding the loop to the outside scope. */
        for (int i = 0; i < loopScope.createdNodes.length; i++) {
            if (loopScope.outer.createdNodes[i] == null) {
                loopScope.outer.createdNodes[i] = loopScope.createdNodes[i];
            }
        }
    }

    public static final boolean DUMP_DURING_FIXED_NODE_PROCESSING = false;

    protected LoopScope processNextNode(MethodScope methodScope, LoopScope loopScope) {
        int nodeOrderId = loopScope.nodesToProcess.nextSetBit(0);
        loopScope.nodesToProcess.clear(nodeOrderId);

        FixedNode node = (FixedNode) lookupNode(loopScope, nodeOrderId);

        if (node.isDeleted()) {
            return loopScope;
        }
        graph.beforeDecodingFields(node);
        try {
            if (DUMP_DURING_FIXED_NODE_PROCESSING) {
                if (node != null) {
                    try {
                        debug.dump(DebugContext.DETAILED_LEVEL, graph, "Before processing node %s", node);
                    } catch (Throwable t) {
                        // swallow here, dumping uninitialized nodes can cause problems
                    }
                }
            }
            if ((node instanceof MergeNode ||
                            (node instanceof LoopBeginNode && (methodScope.loopExplosion.unrollLoops() &&
                                            !methodScope.loopExplosion.mergeLoops()))) &&
                            ((AbstractMergeNode) node).forwardEndCount() == 1) {
                /*
                 * In case node is a loop begin and we are unrolling loops we remove the loop begin
                 * since the loop will be gone after PE.
                 */
                AbstractMergeNode merge = (AbstractMergeNode) node;
                EndNode singleEnd = merge.forwardEndAt(0);

                /* Nodes that would use this merge as the guard need to use the previous block. */
                registerNode(loopScope, nodeOrderId, AbstractBeginNode.prevBegin(singleEnd), true, false);

                FixedNode next = makeStubNode(methodScope, loopScope, nodeOrderId + GraphEncoder.BEGIN_NEXT_ORDER_ID_OFFSET);
                singleEnd.replaceAtPredecessor(next);

                merge.safeDelete();
                singleEnd.safeDelete();
                return loopScope;
            }

            LoopScope successorAddScope = loopScope;
            boolean updatePredecessors = true;
            if (node instanceof LoopExitNode) {
                if (methodScope.loopExplosion.duplicateLoopExits() || (methodScope.loopExplosion.mergeLoops() && loopScope.loopDepth > 1)) {
                    /*
                     * We do not want to merge loop exits of inner loops. Instead, we want to keep
                     * exploding the outer loop separately for every loop exit and then merge the
                     * outer loop. Therefore, we create a new LoopScope of the outer loop for every
                     * loop exit of the inner loop.
                     */
                    LoopScope outerScope = loopScope.outer;
                    int nextIterationNumber = outerScope.nextIterationFromLoopExitDuplication.isEmpty() ? outerScope.loopIteration + 1
                                    : outerScope.nextIterationFromLoopExitDuplication.getLast().loopIteration + 1;
                    Node[] initialCreatedNodes = outerScope.initialCreatedNodes == null ? null
                                    : (methodScope.loopExplosion.mergeLoops()
                                                    ? Arrays.copyOf(outerScope.initialCreatedNodes, outerScope.initialCreatedNodes.length)
                                                    : outerScope.initialCreatedNodes);
                    successorAddScope = new LoopScope(methodScope, outerScope.outer, outerScope.loopDepth, nextIterationNumber, outerScope.loopBeginOrderId, LoopScopeTrigger.LOOP_EXIT_DUPLICATION,
                                    initialCreatedNodes,
                                    Arrays.copyOf(loopScope.initialCreatedNodes, loopScope.initialCreatedNodes.length),
                                    outerScope.nextIterationFromLoopExitDuplication,
                                    outerScope.nextIterationFromLoopEndDuplication,
                                    outerScope.nextIterationsFromUnrolling,
                                    outerScope.iterationStates);
                    checkLoopExplosionIteration(methodScope, successorAddScope);

                    /*
                     * Nodes that are still unprocessed in the outer scope might be merge nodes that
                     * are also reachable from the new exploded scope. Clearing them ensures that we
                     * do not merge, but instead keep exploding.
                     */
                    for (int id = outerScope.nodesToProcess.nextSetBit(0); id >= 0; id = outerScope.nodesToProcess.nextSetBit(id + 1)) {
                        successorAddScope.createdNodes[id] = null;
                    }

                    outerScope.nextIterationFromLoopExitDuplication.addLast(successorAddScope);
                } else {
                    successorAddScope = loopScope.outer;
                }
                updatePredecessors = methodScope.loopExplosion.isNoExplosion();
            }

            methodScope.reader.setByteIndex(methodScope.encodedGraph.nodeStartOffsets[nodeOrderId]);
            int typeId = methodScope.reader.getUVInt();
            assert node.getNodeClass() == methodScope.encodedGraph.getNodeClasses()[typeId] : Assertions.errorMessage(node, methodScope.encodedGraph.getNodeClasses()[typeId]);
            makeFixedNodeInputs(methodScope, loopScope, node);
            readProperties(methodScope, node);

            if ((node instanceof IfNode || node instanceof SwitchNode) &&
                            earlyCanonicalization(methodScope, successorAddScope, nodeOrderId, node)) {
                return loopScope;
            }

            makeSuccessorStubs(methodScope, successorAddScope, node, updatePredecessors);

            LoopScope resultScope = loopScope;
            if (node instanceof LoopBeginNode) {
                if (methodScope.loopExplosion.useExplosion()) {
                    handleLoopExplosionBegin(methodScope, loopScope, (LoopBeginNode) node);
                }

            } else if (node instanceof LoopExitNode) {
                if (methodScope.loopExplosion.useExplosion()) {
                    handleLoopExplosionProxyNodes(methodScope, loopScope, successorAddScope, (LoopExitNode) node, nodeOrderId);
                } else {
                    handleProxyNodes(methodScope, loopScope, (LoopExitNode) node);
                }

            } else if (node instanceof MergeNode) {
                handleMergeNode(((MergeNode) node));
            } else if (node instanceof AbstractEndNode) {
                LoopScope phiInputScope = loopScope;
                LoopScope phiNodeScope = loopScope;
                int mergeOrderId = readOrderId(methodScope);

                boolean requiresMergeOfOuterLoop = methodScope.loopExplosion.unrollLoops() &&
                                methodScope.loopExplosion.duplicateLoopExits() &&
                                (!methodScope.loopExplosion.duplicateLoopEnds()) &&
                                (!methodScope.loopExplosion.mergeLoops()) &&
                                node instanceof LoopEndNode &&
                                loopScope.trigger == LoopScopeTrigger.LOOP_EXIT_DUPLICATION;

                if (requiresMergeOfOuterLoop) {
                    EndNode replacementNode = graph.add(new EndNode());
                    node.replaceAtPredecessor(replacementNode);
                    node.safeDelete();
                    node = replacementNode;
                    /*
                     * We are in a loop exit duplicated loop scope and see a loop end node, this can
                     * only happen if we have a loop end to an outer loop. When duplicating over
                     * loop exits we have to merge outer loops for nested inner loops.
                     *
                     * Therefore, we create a correct outer loop iteration and check if there is
                     * already one, if not we create it else we re-use it.
                     */
                    if (loopScope.nextIterationsFromUnrolling.isEmpty()) {
                        // create it
                        int nextIterationNumber = loopScope.nextIterationsFromUnrolling.isEmpty() ? loopScope.loopIteration + 1 : loopScope.nextIterationsFromUnrolling.getLast().loopIteration + 1;
                        LoopScope outerLoopMergeScope = new LoopScope(methodScope, loopScope.outer, loopScope.loopDepth, nextIterationNumber, loopScope.loopBeginOrderId,
                                        LoopScopeTrigger.LOOP_BEGIN_UNROLLING,
                                        methodScope.loopExplosion.mergeLoops() ? Arrays.copyOf(loopScope.initialCreatedNodes, loopScope.initialCreatedNodes.length) : loopScope.initialCreatedNodes,
                                        Arrays.copyOf(loopScope.initialCreatedNodes, loopScope.initialCreatedNodes.length),
                                        loopScope.nextIterationFromLoopExitDuplication,
                                        loopScope.nextIterationFromLoopEndDuplication,
                                        loopScope.nextIterationsFromUnrolling,
                                        loopScope.iterationStates);
                        checkLoopExplosionIteration(methodScope, outerLoopMergeScope);
                        loopScope.nextIterationsFromUnrolling.addLast(outerLoopMergeScope);
                        registerNode(outerLoopMergeScope, loopScope.loopBeginOrderId, null, true, true);
                        makeStubNode(methodScope, outerLoopMergeScope, loopScope.loopBeginOrderId);
                        phiNodeScope = outerLoopMergeScope;
                    } else {
                        // re-use it
                        phiNodeScope = loopScope.nextIterationsFromUnrolling.getLast();
                    }

                } else if (methodScope.loopExplosion.useExplosion() && node instanceof LoopEndNode) {
                    EndNode replacementNode = graph.add(new EndNode());
                    node.replaceAtPredecessor(replacementNode);
                    node.safeDelete();
                    node = replacementNode;
                    LoopScopeTrigger trigger = handleLoopExplosionEnd(methodScope, loopScope);
                    Deque<LoopScope> phiScope = loopScope.nextIterationsFromUnrolling;
                    if (trigger == LoopScopeTrigger.LOOP_END_DUPLICATION) {
                        phiScope = loopScope.nextIterationFromLoopEndDuplication;
                    }
                    phiNodeScope = phiScope.getLast();
                }
                AbstractMergeNode merge = (AbstractMergeNode) lookupNode(phiNodeScope, mergeOrderId);
                if (merge == null) {
                    merge = (AbstractMergeNode) makeStubNode(methodScope, phiNodeScope, mergeOrderId);
                    if (merge instanceof LoopBeginNode) {
                        /*
                         * In contrast to the LoopScopeTrigger.START created at the beginning of
                         * every PE, we see a real loop here and create the first real loop scope
                         * associated with a loop.
                         *
                         * Creation of a loop scope if we reach a loop begin node. We process a loop
                         * begin node (always before encountering a loop end associated with the
                         * loop begin) and simply create a normal loop scope. This does not imply an
                         * advanced unrolling strategy (however it can later if we see duplicate
                         * over loop end or exits). Therefore, we still use the start marker here,
                         * we could also use the unrolling marker.
                         *
                         * If we unroll loops we will later remove the loop begin node and replace
                         * it with its forward end (since we do not need to create a loop begin node
                         * if we unroll the entire loop and it has a constant trip count).
                         */
                        assert phiNodeScope == phiInputScope : phiInputScope + "!=" + phiInputScope;
                        assert phiNodeScope == loopScope : phiNodeScope + "!=" + loopScope;
                        resultScope = new LoopScope(methodScope, loopScope, loopScope.loopDepth + 1, 0, mergeOrderId, LoopScopeTrigger.START,
                                        methodScope.loopExplosion.useExplosion() ? Arrays.copyOf(loopScope.createdNodes, loopScope.createdNodes.length) : null,
                                        methodScope.loopExplosion.useExplosion() ? Arrays.copyOf(loopScope.createdNodes, loopScope.createdNodes.length) : loopScope.createdNodes, //
                                        methodScope.loopExplosion.duplicateLoopExits() || methodScope.loopExplosion.mergeLoops() ? new ArrayDeque<>(2) : null,
                                        methodScope.loopExplosion.duplicateLoopEnds() ? new ArrayDeque<>(2) : null,
                                        methodScope.loopExplosion.unrollLoops() ? new ArrayDeque<>(2) : null, //
                                        methodScope.loopExplosion.mergeLoops() ? EconomicMap.create(Equivalence.DEFAULT) : null);
                        phiInputScope = resultScope;
                        phiNodeScope = resultScope;

                        if (methodScope.loopExplosion.useExplosion()) {
                            registerNode(loopScope, mergeOrderId, null, true, true);
                        }
                        loopScope.nodesToProcess.clear(mergeOrderId);
                        resultScope.nodesToProcess.set(mergeOrderId);
                    }
                }
                handlePhiFunctions(methodScope, phiInputScope, phiNodeScope, (AbstractEndNode) node, merge);
            } else if (node instanceof Invoke) {
                InvokeData invokeData = readInvokeData(methodScope, nodeOrderId, (Invoke) node);
                resultScope = handleInvoke(methodScope, loopScope, invokeData);
            } else if (node instanceof MethodHandleWithExceptionNode methodHandle) {
                InvokableData<MethodHandleWithExceptionNode> invokableData = readInvokableData(methodScope, nodeOrderId, methodHandle);
                resultScope = handleMethodHandle(methodScope, loopScope, invokableData);
            } else if (node instanceof ReturnNode || node instanceof UnwindNode) {
                methodScope.returnAndUnwindNodes.add((ControlSinkNode) node);
            } else {
                handleFixedNode(methodScope, loopScope, nodeOrderId, node);
            }
            if (DUMP_DURING_FIXED_NODE_PROCESSING) {
                if (node != null) {
                    try {
                        debug.dump(DebugContext.DETAILED_LEVEL, graph, "After processing node %s", node);
                    } catch (Throwable t) {
                        // swallow here, dumping uninitialized nodes can cause problems
                    }
                }
            }
            return resultScope;
        } finally {
            graph.afterDecodingFields(node);
        }
    }

    protected LoopScope handleMethodHandle(MethodScope methodScope, LoopScope loopScope, InvokableData<MethodHandleWithExceptionNode> invokableData) {
        appendInvokable(methodScope, loopScope, invokableData);
        return loopScope;
    }

    protected <T extends Invokable> InvokableData<T> readInvokableData(MethodScope methodScope, int orderId, T node) {
        ResolvedJavaType contextType = (ResolvedJavaType) readObject(methodScope);
        int stateAfterOrderId = readOrderId(methodScope);
        int nextOrderId = readOrderId(methodScope);

        if (node instanceof WithExceptionNode) {
            int exceptionOrderId = readOrderId(methodScope);
            int exceptionStateOrderId = readOrderId(methodScope);
            int exceptionNextOrderId = readOrderId(methodScope);
            return new InvokableData<>(node, contextType, orderId, stateAfterOrderId, nextOrderId, exceptionOrderId, exceptionStateOrderId, exceptionNextOrderId);
        } else {
            return new InvokableData<>(node, contextType, orderId, stateAfterOrderId, nextOrderId, -1, -1, -1);
        }
    }

    protected InvokeData readInvokeData(MethodScope methodScope, int invokeOrderId, Invoke invoke) {
        int callTargetOrderId = readOrderId(methodScope);
        InvokableData<Invoke> invokableData = readInvokableData(methodScope, invokeOrderId, invoke);
        return InvokeData.createFrom(invokableData, callTargetOrderId, false);
    }

    /**
     * {@link Invoke} nodes do not have the {@link CallTargetNode}, {@link FrameState}, and
     * successors encoded. Instead, this information is provided separately to allow method inlining
     * without decoding and adding them to the graph upfront. For non-inlined methods, this method
     * restores the normal state. Subclasses can override it to perform method inlining.
     *
     * The return value is the loop scope where decoding should continue. When method inlining
     * should be performed, the returned loop scope must be a new loop scope for the inlined method.
     * Without inlining, the original loop scope must be returned.
     */
    protected LoopScope handleInvoke(MethodScope methodScope, LoopScope loopScope, InvokeData invokeData) {
        assert invokeData.invoke.callTarget() == null : "callTarget edge is ignored during decoding of Invoke";
        CallTargetNode callTarget = (CallTargetNode) ensureNodeCreated(methodScope, loopScope, invokeData.callTargetOrderId);
        appendInvoke(methodScope, loopScope, invokeData, callTarget);
        return loopScope;
    }

    protected void appendInvoke(MethodScope methodScope, LoopScope loopScope, InvokeData invokeData, CallTargetNode callTarget) {
        if (invokeData.invoke instanceof InvokeWithExceptionNode) {
            ((InvokeWithExceptionNode) invokeData.invoke).setCallTarget(callTarget);
        } else {
            ((InvokeNode) invokeData.invoke).setCallTarget(callTarget);
        }
        appendInvokable(methodScope, loopScope, invokeData);
    }

    private <T extends Invokable & StateSplit> void appendInvokable(MethodScope methodScope, LoopScope loopScope, InvokableData<T> invokeData) {
        if (invokeData.invoke.stateAfter() == null) {
            invokeData.invoke.setStateAfter((FrameState) ensureNodeCreated(methodScope, loopScope, invokeData.stateAfterOrderId));
        }
        assert !(invokeData.invoke instanceof Invoke inv && inv.stateDuring() != null) : "stateDuring is not used in high tier graphs";

        FixedNode next = makeStubNode(methodScope, loopScope, invokeData.nextOrderId);
        if (invokeData.invoke instanceof WithExceptionNode withException) {
            withException.setNext((AbstractBeginNode) next);
            withException.setExceptionEdge((AbstractBeginNode) makeStubNode(methodScope, loopScope, invokeData.exceptionOrderId));
        } else {
            ((FixedWithNextNode) invokeData.invoke).setNext(next);
        }
    }

    /**
     * Hook for subclasses to perform simplifications for a non-loop-header control flow merge.
     *
     * @param merge The control flow merge.
     */
    protected void handleMergeNode(MergeNode merge) {
    }

    protected void handleLoopExplosionBegin(MethodScope methodScope, LoopScope loopScope, LoopBeginNode loopBegin) {
        checkLoopExplosionIteration(methodScope, loopScope);

        List<EndNode> predecessors = loopBegin.forwardEnds().snapshot();
        FixedNode successor = loopBegin.next();
        FrameState frameState = loopBegin.stateAfter();

        if (methodScope.loopExplosion.mergeLoops()) {
            LoopExplosionState queryState = new LoopExplosionState(frameState, null);
            LoopExplosionState existingState = loopScope.iterationStates.get(queryState);
            if (existingState != null) {
                loopBegin.replaceAtUsagesAndDelete(existingState.merge);
                successor.safeDelete();
                for (EndNode predecessor : predecessors) {
                    existingState.merge.addForwardEnd(predecessor);
                }
                return;
            }
        }

        MergeNode merge = graph.add(new MergeNode());
        methodScope.loopExplosionMerges.add(merge);

        if (methodScope.loopExplosion.mergeLoops()) {
            if (loopScope.iterationStates.size() == 0 && loopScope.loopDepth == 1) {
                if (methodScope.loopExplosionHead != null) {
                    throw new PermanentBailoutException("Graal implementation restriction: Method with %s loop explosion must not have more than one top-level loop",
                                    LoopExplosionPlugin.LoopExplosionKind.MERGE_EXPLODE);
                }
                methodScope.loopExplosionHead = merge;
            }

            /*
             * Proxy generation and merge explosion: When doing merge-explode PE loops are detected
             * after partial evaluation in a dedicated steps. Therefore, we create merge nodes
             * instead of loop begins and loop exits and later replace them with the detected loop
             * begin and loop exit nodes.
             *
             * However, in order to create the correct loop proxies, all values alive at a merge
             * created for a loop begin/loop exit replacement merge, we create so called proxy
             * placeholder nodes. These nodes are attached to a merge and proxy the corresponding
             * node. Later, when we replace a merge with a loop exit, we visit all live nodes at
             * that loop exit and replace the proxy placeholders with real value proxy nodes.
             *
             * Since we cannot (this would explode immediately) proxy all nodes for every merge
             * during explosion, we only create nodes at the loop explosion begins for nodes that
             * are alive at the framestate of the respective loop begin. This is fine as long as all
             * values proxied out of a loop are alive at the loop header. However, this is not true
             * for all values (imagine do-while loops). Thus, we may create, in very specific
             * patterns, unschedulable graphs since we miss the creation of proxy nodes.
             *
             * There is currently no straight forward solution to this problem, thus we shift the
             * work to the implementor side where such patterns can typically be easily fixed by
             * creating loop phis and assigning them correctly.
             */
            FrameState.ValueFunction valueFunction = new FrameState.ValueFunction() {

                @Override
                public ValueNode apply(int index, ValueNode frameStateValue) {
                    if (frameStateValue == null || frameStateValue.isConstant() || !graph.isNew(methodScope.methodStartMark, frameStateValue)) {
                        return frameStateValue;

                    } else {
                        ProxyPlaceholder newFrameStateValue = graph.unique(new ProxyPlaceholder(frameStateValue, merge));

                        /*
                         * We do not have the orderID of the value anymore, so we need to search
                         * through the complete list of nodes to find a match.
                         */
                        for (int i = 0; i < loopScope.createdNodes.length; i++) {
                            if (loopScope.createdNodes[i] == frameStateValue) {
                                loopScope.createdNodes[i] = newFrameStateValue;
                            }
                        }

                        if (loopScope.initialCreatedNodes != null) {
                            for (int i = 0; i < loopScope.initialCreatedNodes.length; i++) {
                                if (loopScope.initialCreatedNodes[i] == frameStateValue) {
                                    loopScope.initialCreatedNodes[i] = newFrameStateValue;
                                }
                            }
                        }
                        return newFrameStateValue;
                    }
                }
            };
            FrameState newFrameState = graph.add(frameState.duplicate(valueFunction));

            frameState.replaceAtUsagesAndDelete(newFrameState);
            frameState = newFrameState;
        }

        loopBegin.replaceAtUsagesAndDelete(merge);
        merge.setStateAfter(frameState);
        merge.setNext(successor);
        for (EndNode predecessor : predecessors) {
            merge.addForwardEnd(predecessor);
        }

        if (methodScope.loopExplosion.mergeLoops()) {
            LoopExplosionState explosionState = new LoopExplosionState(frameState, merge);
            loopScope.iterationStates.put(explosionState, explosionState);
        }
    }

    /**
     * Hook for subclasses.
     *
     * @param methodScope The current method.
     * @param loopScope The current loop.
     */
    protected void checkLoopExplosionIteration(MethodScope methodScope, LoopScope loopScope) {
        throw shouldNotReachHere("when subclass uses loop explosion, it needs to implement this method"); // ExcludeFromJacocoGeneratedReport
    }

    protected LoopScopeTrigger handleLoopExplosionEnd(MethodScope methodScope, LoopScope loopScope) {
        /*
         * This method is only called if we reach a loop end and we use some kind of loop explosion,
         * i.e., we unroll loops or explode along loop ends.
         */
        LoopScopeTrigger trigger = null;
        Deque<LoopScope> nextIterations = null;
        if (methodScope.loopExplosion.duplicateLoopEnds()) {
            /*
             * Loop explosion along loop ends: We see a loop end, however we do not merge all loop
             * ends at a common merge node but rather duplicate the rest of the loop for every loop
             * end.
             */
            trigger = LoopScopeTrigger.LOOP_END_DUPLICATION;
            nextIterations = loopScope.nextIterationFromLoopEndDuplication;
        } else if (loopScope.nextIterationsFromUnrolling.isEmpty()) {
            /*
             * Regular loop unrolling, i.e., we reach a loop end node of a loop that should be
             * unrolled: We create a new successor scope.
             */
            trigger = LoopScopeTrigger.LOOP_BEGIN_UNROLLING;
            nextIterations = loopScope.nextIterationsFromUnrolling;
        }
        if (trigger != null) {
            int nextIterationNumber = nextIterations.isEmpty() ? loopScope.loopIteration + 1 : nextIterations.getLast().loopIteration + 1;
            LoopScope nextIterationScope = new LoopScope(methodScope, loopScope.outer, loopScope.loopDepth, nextIterationNumber, loopScope.loopBeginOrderId, trigger,
                            methodScope.loopExplosion.mergeLoops() ? Arrays.copyOf(loopScope.initialCreatedNodes, loopScope.initialCreatedNodes.length) : loopScope.initialCreatedNodes,
                            Arrays.copyOf(loopScope.initialCreatedNodes, loopScope.initialCreatedNodes.length),
                            loopScope.nextIterationFromLoopExitDuplication,
                            loopScope.nextIterationFromLoopEndDuplication,
                            loopScope.nextIterationsFromUnrolling,
                            loopScope.iterationStates);
            checkLoopExplosionIteration(methodScope, nextIterationScope);
            nextIterations.addLast(nextIterationScope);
            registerNode(nextIterationScope, loopScope.loopBeginOrderId, null, true, true);
            makeStubNode(methodScope, nextIterationScope, loopScope.loopBeginOrderId);
        }
        return trigger;
    }

    /**
     * Hook for subclasses.
     *
     * @param methodScope The current method.
     * @param loopScope The current loop.
     * @param nodeOrderId The orderId of the node.
     * @param node The node to be simplified.
     */
    protected void handleFixedNode(MethodScope methodScope, LoopScope loopScope, int nodeOrderId, FixedNode node) {
    }

    /**
     * Hook for subclasses for early canonicalization of IfNodes and IntegerSwitchNodes.
     *
     * "Early" means that this is called before successor stubs creation. Therefore, all successors
     * are null a this point, and calling any method using them without prior manual initialization
     * will fail.
     *
     * @param methodScope The current method.
     * @param loopScope The current loop.
     * @param nodeOrderId The orderId of the node.
     * @param node The node to be simplified.
     * @return true if canonicalization happened, false otherwise.
     */
    protected boolean earlyCanonicalization(MethodScope methodScope, LoopScope loopScope, int nodeOrderId, FixedNode node) {
        return false;
    }

    protected void handleProxyNodes(MethodScope methodScope, LoopScope loopScope, LoopExitNode loopExit) {
        assert loopExit.stateAfter() == null;
        int stateAfterOrderId = readOrderId(methodScope);
        loopExit.setStateAfter((FrameState) ensureNodeCreated(methodScope, loopScope, stateAfterOrderId));

        int numProxies = methodScope.reader.getUVInt();
        for (int i = 0; i < numProxies; i++) {
            int proxyOrderId = readOrderId(methodScope);
            ProxyNode proxy = (ProxyNode) ensureNodeCreated(methodScope, loopScope, proxyOrderId);
            /*
             * The ProxyNode transports a value from the loop to the outer scope. We therefore
             * register it in the outer scope.
             */
            if (loopScope.outer.createdNodes != loopScope.createdNodes) {
                registerNode(loopScope.outer, proxyOrderId, proxy, false, false);
            }
        }
    }

    protected void handleLoopExplosionProxyNodes(MethodScope methodScope, LoopScope loopScope, LoopScope outerScope, LoopExitNode loopExit, int loopExitOrderId) {
        assert loopExit.stateAfter() == null;
        int stateAfterOrderId = readOrderId(methodScope);

        FixedNode loopExitSuccessor = loopExit.next();

        BeginNode begin;
        if (loopExit.predecessor() instanceof BeginNode) {
            // Optimization: Reuse an existing BeginNode rather than creating a new one.
            begin = (BeginNode) loopExit.predecessor();
            loopExit.replaceAtPredecessor(null);
        } else {
            begin = graph.add(new BeginNode());
            loopExit.replaceAtPredecessor(begin);
        }

        MergeNode loopExitPlaceholder = null;
        if (methodScope.loopExplosion.mergeLoops() && loopScope.loopDepth == 1) {
            /*
             * This exit might end up as a loop exit of a loop detected after partial evaluation. We
             * need to be able to create a FrameState and the necessary proxy nodes in this case.
             */
            loopExitPlaceholder = graph.add(new MergeNode());
            methodScope.loopExplosionMerges.add(loopExitPlaceholder);

            EndNode end = graph.add(new EndNode());
            begin.setNext(end);
            loopExitPlaceholder.addForwardEnd(end);

            begin = graph.add(new BeginNode());
            loopExitPlaceholder.setNext(begin);
        }

        /*
         * In the original graph, the loop exit is not a merge node. Multiple exploded loop
         * iterations now take the same loop exit, so we have to introduce a new merge node to
         * handle the merge.
         */
        MergeNode merge = null;
        Node existingExit = lookupNode(outerScope, loopExitOrderId);
        if (existingExit == null) {
            /* First loop iteration that exits. No merge necessary yet. */
            registerNode(outerScope, loopExitOrderId, begin, false, false);
            begin.setNext(loopExitSuccessor);

        } else if (existingExit instanceof BeginNode) {
            /* Second loop iteration that exits. Create the merge. */
            merge = graph.add(new MergeNode());
            registerNode(outerScope, loopExitOrderId, merge, true, false);
            /* Add the first iteration. */
            EndNode firstEnd = graph.add(new EndNode());
            ((BeginNode) existingExit).setNext(firstEnd);
            merge.addForwardEnd(firstEnd);
            merge.setNext(loopExitSuccessor);

        } else {
            /* Subsequent loop iteration. Merge already created. */
            merge = (MergeNode) existingExit;
        }

        if (merge != null) {
            EndNode end = graph.add(new EndNode());
            begin.setNext(end);
            merge.addForwardEnd(end);
        }

        /*
         * Possibly create phi nodes for the original proxy nodes that flow out of the loop. Note
         * that we definitely do not need a proxy node itself anymore, since the loop was exploded
         * and is no longer present.
         */
        int numProxies = methodScope.reader.getUVInt();
        boolean phiCreated = false;
        for (int i = 0; i < numProxies; i++) {
            int proxyOrderId = readOrderId(methodScope);
            ProxyNode proxy = (ProxyNode) ensureNodeCreated(methodScope, loopScope, proxyOrderId);
            ValueNode phiInput = proxy.value();

            if (loopExitPlaceholder != null) {
                if (!phiInput.isConstant()) {
                    phiInput = graph.unique(new ProxyPlaceholder(phiInput, loopExitPlaceholder));
                }
                registerNode(loopScope, proxyOrderId, phiInput, true, false);
            }

            ValueNode replacement;
            ValueNode existing = (ValueNode) outerScope.createdNodes[proxyOrderId];
            if (existing == null || existing == phiInput) {
                /*
                 * We are at the first loop exit, or the proxy carries the same value for all exits.
                 * We do not need a phi node yet.
                 */
                registerNode(outerScope, proxyOrderId, phiInput, true, false);
                replacement = phiInput;

            } else {
                // Fortify: Suppress Null Dereference false positive
                assert merge != null;

                if (!merge.isPhiAtMerge(existing)) {
                    /* Now we have two different values, so we need to create a phi node. */
                    PhiNode phi = proxy.createPhi(merge);
                    /* Add the inputs from all previous exits. */
                    for (int j = 0; j < merge.phiPredecessorCount() - 1; j++) {
                        phi.addInput(existing);
                    }
                    /* Add the input from this exit. */
                    phi.addInput(phiInput);
                    registerNode(outerScope, proxyOrderId, phi, true, false);
                    replacement = phi;
                    phiCreated = true;

                } else {
                    /* Phi node has been created before, so just add the new input. */
                    PhiNode phi = (PhiNode) existing;
                    phi.addInput(phiInput);
                    replacement = phi;
                }
            }
            proxy.replaceAtUsagesAndDelete(replacement);
        }

        if (loopExitPlaceholder != null) {
            registerNode(loopScope, stateAfterOrderId, null, true, true);
            loopExitPlaceholder.setStateAfter((FrameState) ensureNodeCreated(methodScope, loopScope, stateAfterOrderId));
        }

        if (merge != null && (merge.stateAfter() == null || phiCreated)) {
            FrameState oldStateAfter = merge.stateAfter();
            registerNode(outerScope, stateAfterOrderId, null, true, true);
            merge.setStateAfter((FrameState) ensureNodeCreated(methodScope, outerScope, stateAfterOrderId));
            if (oldStateAfter != null) {
                oldStateAfter.safeDelete();
            }
        }
        loopExit.safeDelete();
        assert loopExitSuccessor.predecessor() == null;
        if (merge != null) {
            merge.getNodeClass().getSuccessorEdges().update(merge, null, loopExitSuccessor);
        } else {
            begin.getNodeClass().getSuccessorEdges().update(begin, null, loopExitSuccessor);
        }
    }

    protected void handlePhiFunctions(MethodScope methodScope, LoopScope phiInputScope, LoopScope phiNodeScope, AbstractEndNode end, AbstractMergeNode merge) {

        if (end instanceof LoopEndNode) {
            /*
             * Fix the loop end index and the number of loop ends. When we do canonicalization
             * during decoding, we can end up with fewer ends than the encoded graph had. And the
             * order of loop ends can be different.
             */
            int numEnds = ((LoopBeginNode) merge).loopEnds().count();
            ((LoopBeginNode) merge).nextEndIndex = numEnds;
            ((LoopEndNode) end).endIndex = numEnds - 1;

        } else {
            if (merge.ends == null) {
                merge.ends = new NodeInputList<>(merge);
            }
            merge.addForwardEnd((EndNode) end);
        }

        /*
         * We create most phi functions lazily. Canonicalization and simplification during decoding
         * can lead to dead branches that are not decoded, so we might not need all phi functions
         * that the original graph contained. Since we process all predecessors before actually
         * processing the merge node, we have the final phi function when processing the merge node.
         * The only exception are loop headers of non-exploded loops: since backward branches are
         * not processed yet when processing the loop body, we need to create all phi functions
         * upfront.
         */
        boolean lazyPhi = allowLazyPhis() && (!(merge instanceof LoopBeginNode) || methodScope.loopExplosion.useExplosion());
        int numPhis = methodScope.reader.getUVInt();
        for (int i = 0; i < numPhis; i++) {
            int phiInputOrderId = readOrderId(methodScope);
            int phiNodeOrderId = readOrderId(methodScope);

            ValueNode phiInput = (ValueNode) ensureNodeCreated(methodScope, phiInputScope, phiInputOrderId);
            ValueNode existing = (ValueNode) lookupNode(phiNodeScope, phiNodeOrderId);

            if (existing != null && merge.phiPredecessorCount() == 1) {
                /*
                 * When exploding loops and the code after the loop (FULL_EXPLODE_UNTIL_RETURN),
                 * then an existing value can already be registered: Parsing of the code before the
                 * loop registers it when preparing for the later merge. The code after the loop,
                 * which starts with a clone of the values that were created before the loop, sees
                 * the stale value when processing the merge the first time. We can safely ignore
                 * the stale value because it will never be needed to be merged (we are exploding
                 * until we hit a return).
                 */
                assert methodScope.loopExplosion.duplicateLoopExits();
                assert phiNodeScope.loopIteration > 0 : Assertions.errorMessageContext("phiNodeScope.loopIteration", phiNodeScope.loopIteration);
                existing = null;
            }

            if (lazyPhi && (existing == null || existing == phiInput)) {
                /* Phi function not yet necessary. */
                registerNode(phiNodeScope, phiNodeOrderId, phiInput, true, false);

            } else if (!merge.isPhiAtMerge(existing)) {
                /*
                 * Phi function is necessary. Create it and fill it with existing inputs as well as
                 * the new input.
                 */
                registerNode(phiNodeScope, phiNodeOrderId, null, true, true);
                PhiNode phi = (PhiNode) ensureNodeCreated(methodScope, phiNodeScope, phiNodeOrderId);

                phi.setMerge(merge);
                for (int j = 0; j < merge.phiPredecessorCount() - 1; j++) {
                    phi.addInput(existing);
                }
                phi.addInput(phiInput);

            } else {
                /* Phi node has been created before, so just add the new input. */
                PhiNode phi = (PhiNode) existing;
                phi.addInput(phiInput);
            }
        }
    }

    protected boolean allowLazyPhis() {
        /* We need to exactly reproduce the encoded graph, including unnecessary phi functions. */
        return false;
    }

    @SuppressWarnings("try")
    protected void readProperties(MethodScope methodScope, Node node) {
        try (DebugCloseable a = ReadPropertiesTimer.start(debug)) {
            NodeSourcePosition position = (NodeSourcePosition) readObject(methodScope);
            Fields fields = node.getNodeClass().getData();
            for (int pos = 0; pos < fields.getCount(); pos++) {
                if (fields.getType(pos).isPrimitive()) {
                    long primitive = methodScope.reader.getSV();
                    fields.setRawPrimitive(node, pos, primitive);
                } else {
                    Object value = readObject(methodScope);
                    fields.putObject(node, pos, value);
                }
            }
            if (graph.trackNodeSourcePosition() && position != null) {
                NodeSourcePosition newPosition = methodScope.getNodeSourcePosition(position);
                node.setNodeSourcePosition(newPosition);
                if (node instanceof DeoptimizingGuard deoptGuard && !newPosition.equals(position)) {
                    deoptGuard.addCallerToNoDeoptSuccessorPosition(newPosition.getCaller());
                }
            }
        }
    }

    /**
     * Process the input edges of a node. Input nodes that have not yet been created must be
     * non-fixed nodes (because fixed nodes are processed in reverse postorder. Such non-fixed nodes
     * are created on demand (recursively since they can themselves reference not yet created
     * nodes).
     */
    protected void makeFixedNodeInputs(MethodScope methodScope, LoopScope loopScope, Node node) {
        Edges edges = node.getNodeClass().getInputEdges();
        for (int index = 0; index < edges.getDirectCount(); index++) {
            if (skipDirectEdge(node, edges, index)) {
                continue;
            }
            int orderId = readOrderId(methodScope);
            Node value = ensureNodeCreated(methodScope, loopScope, orderId);
            edges.initializeNode(node, index, value);
            if (value != null && !value.isDeleted()) {
                edges.update(node, null, value);

            }
        }

        if (node instanceof AbstractMergeNode) {
            /* The ends of merge nodes are filled manually when the ends are processed. */
            assert edges.getCount() - edges.getDirectCount() == 1 : "MergeNode has one variable size input (the ends)";
            assert Edges.getNodeList(node, edges.getOffsets(), edges.getDirectCount()) != null : "Input list must have been already created";
        } else {
            for (int index = edges.getDirectCount(); index < edges.getCount(); index++) {
                int size = methodScope.reader.getSVInt();
                if (size != -1) {
                    NodeList<Node> nodeList = new NodeInputList<>(node, size);
                    edges.initializeList(node, index, nodeList);
                    for (int idx = 0; idx < size; idx++) {
                        int orderId = readOrderId(methodScope);
                        Node value = ensureNodeCreated(methodScope, loopScope, orderId);
                        nodeList.initialize(idx, value);
                        if (value != null && !value.isDeleted()) {
                            edges.update(node, null, value);
                        }
                    }
                }
            }
        }
    }

    protected void makeFloatingNodeInputs(MethodScope methodScope, LoopScope loopScope, Node node) {
        Edges edges = node.getNodeClass().getInputEdges();
        if (node instanceof PhiNode) {
            /*
             * The inputs of phi functions are filled manually when the end nodes are processed.
             * However, the values must not be null, so initialize them with an empty list.
             */
            assert edges.getDirectCount() == 1 : "PhiNode has one direct input (the MergeNode)";
            assert edges.getCount() - edges.getDirectCount() == 1 : "PhiNode has one variable size input (the values)";
            edges.initializeList(node, edges.getDirectCount(), new NodeInputList<>(node));
        } else {
            for (int index = 0; index < edges.getDirectCount(); index++) {
                int orderId = readOrderId(methodScope);
                Node value = ensureNodeCreated(methodScope, loopScope, orderId);
                edges.initializeNode(node, index, value);
            }
            for (int index = edges.getDirectCount(); index < edges.getCount(); index++) {
                int size = methodScope.reader.getSVInt();
                if (size != -1) {
                    NodeList<Node> nodeList = new NodeInputList<>(node, size);
                    edges.initializeList(node, index, nodeList);
                    for (int idx = 0; idx < size; idx++) {
                        int orderId = readOrderId(methodScope);
                        Node value = ensureNodeCreated(methodScope, loopScope, orderId);
                        nodeList.initialize(idx, value);
                    }
                }
            }
        }
    }

    protected Node ensureNodeCreated(MethodScope methodScope, LoopScope loopScope, int nodeOrderId) {
        if (nodeOrderId == GraphEncoder.NULL_ORDER_ID) {
            return null;
        }
        Node node = lookupNode(loopScope, nodeOrderId);
        if (node != null) {
            return node;
        }

        node = decodeFloatingNode(methodScope, loopScope, nodeOrderId);
        if (node instanceof ProxyNode || node instanceof PhiNode) {
            /*
             * We need these nodes as they were in the original graph, without any canonicalization
             * or value numbering.
             */
            node = graph.addWithoutUnique(node);
        } else {
            /* Allow subclasses to canonicalize and intercept nodes. */
            Node newNode = handleFloatingNodeBeforeAdd(methodScope, loopScope, node);
            if (newNode != node) {
                releaseFloatingNode(node);
            }

            if (!newNode.isAlive()) {
                newNode = addFloatingNode(methodScope, loopScope, newNode);
            }
            node = handleFloatingNodeAfterAdd(methodScope, loopScope, newNode);
        }
        registerNode(loopScope, nodeOrderId, node, false, false);
        return node;
    }

    protected Node addFloatingNode(@SuppressWarnings("unused") MethodScope methodScope, @SuppressWarnings("unused") LoopScope loopScope, Node node) {
        /*
         * We want to exactly reproduce the encoded graph. Even though nodes should be unique in the
         * encoded graph, this is not always guaranteed.
         */
        return graph.addWithoutUnique(node);
    }

    /**
     * Decodes a non-fixed node, but does not do any post-processing and does not register it.
     */
    protected Node decodeFloatingNode(MethodScope methodScope, LoopScope loopScope, int nodeOrderId) {
        long readerByteIndex = methodScope.reader.getByteIndex();

        methodScope.reader.setByteIndex(methodScope.encodedGraph.nodeStartOffsets[nodeOrderId]);
        NodeClass<?> nodeClass = methodScope.encodedGraph.getNodeClasses()[methodScope.reader.getUVInt()];
        Node node = allocateFloatingNode(nodeClass);
        if (node instanceof FixedNode) {
            /*
             * This is a severe error that will lead to a corrupted graph, so it is better not to
             * continue decoding at all.
             */
            throw shouldNotReachHere("Not a floating node: " + node.getClass().getName()); // ExcludeFromJacocoGeneratedReport
        }

        /* Read the inputs of the node, possibly creating them recursively. */
        makeFloatingNodeInputs(methodScope, loopScope, node);

        /* Read the properties of the node. */
        readProperties(methodScope, node);
        /* There must not be any successors to read, since it is a non-fixed node. */
        assert node.getNodeClass().getEdges(Edges.Type.Successors).getCount() == 0 : Assertions.errorMessage(node);

        methodScope.reader.setByteIndex(readerByteIndex);
        return node;
    }

    private Node allocateFloatingNode(NodeClass<?> nodeClass) {
        ArrayDeque<? extends Node> cachedNodes = reusableFloatingNodes.get(nodeClass);
        if (cachedNodes != null) {
            Node node = cachedNodes.poll();
            if (node != null) {
                return node;
            }
        }
        return nodeClass.allocateInstance();
    }

    private void releaseFloatingNode(Node node) {
        ArrayDeque<Node> cachedNodes = reusableFloatingNodes.get(node.getNodeClass());
        if (cachedNodes == null) {
            cachedNodes = new ArrayDeque<>(2);
            reusableFloatingNodes.put(node.getNodeClass(), cachedNodes);
        }
        cachedNodes.push(node);
    }

    /**
     * Hook for subclasses to process a non-fixed node before it is added to the graph.
     *
     * @param methodScope The current method.
     * @param loopScope The current loop.
     * @param node The node to be canonicalized.
     * @return The replacement for the node, or the node itself.
     */
    protected Node handleFloatingNodeBeforeAdd(MethodScope methodScope, LoopScope loopScope, Node node) {
        return node;
    }

    /**
     * Hook for subclasses to process a non-fixed node after it is added to the graph.
     *
     * If this method replaces a node with another node, it must update its source position if the
     * original node has the source position set.
     *
     * @param methodScope The current method.
     * @param loopScope The current loop.
     * @param node The node to be canonicalized.
     * @return The replacement for the node, or the node itself.
     */
    protected Node handleFloatingNodeAfterAdd(MethodScope methodScope, LoopScope loopScope, Node node) {
        return node;
    }

    /**
     * Process successor edges of a node. We create the successor nodes so that we can fill the
     * successor list, but no properties or edges are loaded yet. That is done when the successor is
     * on top of the worklist in {@link #processNextNode}.
     */
    @SuppressWarnings("try")
    protected void makeSuccessorStubs(MethodScope methodScope, LoopScope loopScope, Node node, boolean updatePredecessors) {
        try (DebugCloseable a = MakeSuccessorStubsTimer.start(debug)) {
            Edges edges = node.getNodeClass().getSuccessorEdges();
            for (int index = 0; index < edges.getDirectCount(); index++) {
                if (skipDirectEdge(node, edges, index)) {
                    continue;
                }
                int orderId = readOrderId(methodScope);
                Node value = makeStubNode(methodScope, loopScope, orderId);
                edges.initializeNode(node, index, value);
                if (updatePredecessors && value != null) {
                    edges.update(node, null, value);
                }
            }
            for (int index = edges.getDirectCount(); index < edges.getCount(); index++) {
                int size = methodScope.reader.getSVInt();
                if (size != -1) {
                    NodeList<Node> nodeList = new NodeSuccessorList<>(node, size);
                    edges.initializeList(node, index, nodeList);
                    for (int idx = 0; idx < size; idx++) {
                        int orderId = readOrderId(methodScope);
                        Node value = makeStubNode(methodScope, loopScope, orderId);
                        nodeList.initialize(idx, value);
                        if (updatePredecessors && value != null) {
                            edges.update(node, null, value);
                        }
                    }
                }
            }
        }
    }

    protected NodeClass<?> getNodeClass(MethodScope methodScope, LoopScope loopScope, int nodeOrderId) {
        if (nodeOrderId == GraphEncoder.NULL_ORDER_ID) {
            return null;
        }
        FixedNode node = (FixedNode) lookupNode(loopScope, nodeOrderId);
        if (node != null) {
            return node.getNodeClass();
        }

        long readerByteIndex = methodScope.reader.getByteIndex();
        methodScope.reader.setByteIndex(methodScope.encodedGraph.nodeStartOffsets[nodeOrderId]);
        NodeClass<?> nodeClass = methodScope.encodedGraph.getNodeClasses()[methodScope.reader.getUVInt()];
        methodScope.reader.setByteIndex(readerByteIndex);
        return nodeClass;
    }

    protected FixedNode makeStubNode(MethodScope methodScope, LoopScope loopScope, int nodeOrderId) {
        if (nodeOrderId == GraphEncoder.NULL_ORDER_ID) {
            return null;
        }
        FixedNode node = (FixedNode) lookupNode(loopScope, nodeOrderId);
        if (node != null) {
            return node;
        }

        long readerByteIndex = methodScope.reader.getByteIndex();
        methodScope.reader.setByteIndex(methodScope.encodedGraph.nodeStartOffsets[nodeOrderId]);
        NodeClass<?> nodeClass = methodScope.encodedGraph.getNodeClasses()[methodScope.reader.getUVInt()];
        Node stubNode = nodeClass.allocateInstance();
        if (graph.trackNodeSourcePosition()) {
            stubNode.setNodeSourcePosition(NodeSourcePosition.placeholder(graph.method()));
        }
        node = (FixedNode) graph.add(stubNode);
        /* Properties and edges are not filled yet, the node remains uninitialized. */
        methodScope.reader.setByteIndex(readerByteIndex);

        registerNode(loopScope, nodeOrderId, node, false, false);
        loopScope.nodesToProcess.set(nodeOrderId);
        return node;
    }

    protected static boolean skipDirectEdge(Node node, Edges edges, int index) {
        if (node instanceof Invoke || node instanceof MethodHandleWithExceptionNode) {
            assert node instanceof InvokeNode || node instanceof InvokeWithExceptionNode || node instanceof MethodHandleWithExceptionNode : "The only supported node classes. Got " + node.getClass();
            if (edges.type() == Edges.Type.Successors) {
                assert edges.getCount() == (node instanceof WithExceptionNode ? 2 : 1) : "Base Invokable has one successor (next); WithExceptionNode has two successors (next, exceptionEdge)";
                return true;
            } else {
                assert edges.type() == Edges.Type.Inputs : edges.type();
                if (edges.getType(index) == CallTargetNode.class) {
                    return true;
                } else if (edges.getType(index) == FrameState.class) {
                    assert edges.get(node, index) == null || edges.get(node, index) == ((StateSplit) node).stateAfter() : "Only stateAfter can be a FrameState during encoding";
                    return true;
                }
            }
        } else if (node instanceof LoopExitNode && edges.type() == Edges.Type.Inputs && edges.getType(index) == FrameState.class) {
            /* The stateAfter of the loop exit is filled manually. */
            return true;

        }
        return false;
    }

    protected Node lookupNode(LoopScope loopScope, int nodeOrderId) {
        return loopScope.createdNodes[nodeOrderId];
    }

    protected void registerNode(LoopScope loopScope, int nodeOrderId, Node node, boolean allowOverwrite, boolean allowNull) {
        assert node == null || node.isAlive();
        assert allowNull || node != null;
        assert allowOverwrite || lookupNode(loopScope, nodeOrderId) == null;
        loopScope.createdNodes[nodeOrderId] = node;
        if (loopScope.methodScope.inliningLogDecoder != null) {
            loopScope.methodScope.inliningLogDecoder.registerNode(loopScope.methodScope.inliningLog, node, nodeOrderId);
        }
    }

    protected int readOrderId(MethodScope methodScope) {
        switch (methodScope.orderIdWidth) {
            case 1:
                return methodScope.reader.getU1();
            case 2:
                return methodScope.reader.getU2();
            case 4:
                return methodScope.reader.getS4();
        }
        throw GraalError.shouldNotReachHere("Invalid orderIdWidth: " + methodScope.orderIdWidth); // ExcludeFromJacocoGeneratedReport
    }

    protected Object readObject(MethodScope methodScope) {
        return methodScope.encodedGraph.getObject(methodScope.reader.getUVInt());
    }

    /**
     * Removes unnecessary nodes from the graph after decoding.
     *
     * @param methodScope The current method.
     */
    protected void cleanupGraph(MethodScope methodScope) {
        for (MergeNode merge : graph.getNodes(MergeNode.TYPE)) {
            for (ProxyPlaceholder placeholder : merge.usages().filter(ProxyPlaceholder.class).snapshot()) {
                placeholder.replaceAndDelete(placeholder.value);
            }
        }
        assert verifyEdges();
    }

    protected boolean verifyEdges() {
        for (Node node : graph.getNodes()) {
            assert node.isAlive();
            for (Node i : node.inputs()) {
                assert i.isAlive();
                assert i.usages().contains(node);
            }
            for (Node s : node.successors()) {
                assert s.isAlive();
                assert s.predecessor() == node : Assertions.errorMessage(s.predecessor(), node);
            }

            for (Node usage : node.usages()) {
                assert usage.isAlive();
                assert usage.inputs().contains(node) : node + " / " + usage + " / " + usage.inputs().count();
            }
            if (node.predecessor() != null) {
                assert node.predecessor().isAlive();
                assert node.predecessor().successors().contains(node);
            }
        }
        return true;
    }
}

/**
 * Parses query result described in {@link QueryResultFormat}.
 */
public final class QueryResultParser extends NativeInfoTreeVisitor {

    private final Map<String, String> idToResult;

    private QueryResultParser(NativeLibraries nativeLibs) {
        super(nativeLibs);
        this.idToResult = new HashMap<>();
    }

    public static List<String> parse(NativeLibraries nativeLibs, NativeCodeInfo nativeCodeInfo, InputStream source) {
        QueryResultParser parser = new QueryResultParser(nativeLibs);
        List<String> lines = FileUtils.readAllLines(source);
        for (String line : lines) {
            String[] keyValuePair = line.split(QueryResultFormat.DELIMINATOR);
            assert keyValuePair.length == 2;
            parser.idToResult.put(keyValuePair[0], keyValuePair[1]);
        }

        nativeCodeInfo.accept(parser);
        return lines;
    }

    @Override
    protected void visitConstantInfo(ConstantInfo constantInfo) {
        switch (constantInfo.getKind()) {
            case INTEGER:
                parseIntegerProperty(constantInfo.getSizeInfo());
                parseSignedness(constantInfo.getSignednessInfo());
                parseIntegerConstantValue(constantInfo.getValueInfo());

                /*
                 * From the point of view of the C compiler, plain #define constants have the type
                 * int and therefore size 4. But sometimes we want to access such values as short or
                 * byte to avoid casts. Check the actual value of the constant, and if it fits the
                 * declared type of the constant, then change the actual size to the declared size.
                 */
                JavaKind returnKind = AccessorInfo.getReturnType(constantInfo.getAnnotatedElement()).getJavaKind();
                if (returnKind == JavaKind.Object) {
                    returnKind = nativeLibs.getTarget().wordJavaKind;
                }
                int declaredSize = getSizeInBytes(returnKind);
                int actualSize = getSizeInBytes(constantInfo);
                if (declaredSize != actualSize) {
                    long value = (long) constantInfo.getValueInfo().getProperty();
                    if (value >= returnKind.getMinValue() && value <= returnKind.getMaxValue()) {
                        constantInfo.getSizeInfo().setProperty(declaredSize);
                    }
                }

                break;
            case POINTER:
                parseIntegerProperty(constantInfo.getSizeInfo());
                parseIntegerConstantValue(constantInfo.getValueInfo());
                break;
            case FLOAT:
                parseIntegerProperty(constantInfo.getSizeInfo());
                parseFloatValue(constantInfo.getValueInfo());
                break;
            case STRING:
                parseStringValue(constantInfo.getValueInfo());
                break;
            case BYTEARRAY:
                parseByteArrayValue(constantInfo.getValueInfo());
                break;
            default:
                throw shouldNotReachHereUnexpectedInput(constantInfo.getKind()); // ExcludeFromJacocoGeneratedReport
        }
    }

    @Override
    public void visitStructInfo(StructInfo structInfo) {
        if (!structInfo.isIncomplete()) {
            parseIntegerProperty(structInfo.getSizeInfo());
        }
        processChildren(structInfo);
    }

    @Override
    protected void visitRawStructureInfo(RawStructureInfo info) {
        /* Nothing to do, do not visit children. */
    }

    @Override
    public void visitStructFieldInfo(StructFieldInfo fieldInfo) {
        parseIntegerProperty(fieldInfo.getSizeInfo());
        parseIntegerProperty(fieldInfo.getOffsetInfo());

        if (fieldInfo.getKind() == ElementKind.INTEGER) {
            parseSignedness(fieldInfo.getSignednessInfo());
        }
    }

    @Override
    public void visitStructBitfieldInfo(StructBitfieldInfo bitfieldInfo) {
        parseIntegerProperty(bitfieldInfo.getByteOffsetInfo());
        parseIntegerProperty(bitfieldInfo.getStartBitInfo());
        parseIntegerProperty(bitfieldInfo.getEndBitInfo());
        parseSignedness(bitfieldInfo.getSignednessInfo());
    }

    @Override
    public void visitPointerToInfo(PointerToInfo pointerToInfo) {
        parseIntegerProperty(pointerToInfo.getSizeInfo());

        if (pointerToInfo.getKind() == ElementKind.INTEGER) {
            parseSignedness(pointerToInfo.getSignednessInfo());
        }
    }

    @Override
    public void visitRawPointerToInfo(RawPointerToInfo pointerToInfo) {
        /* Nothing to do, do not visit children. */
    }

    @Override
    protected void visitEnumConstantInfo(EnumConstantInfo constantInfo) {
        assert constantInfo.getKind() == ElementKind.INTEGER;
        parseIntegerProperty(constantInfo.getSizeInfo());
        parseSignedness(constantInfo.getSignednessInfo());
        parseIntegerConstantValue(constantInfo.getValueInfo());
    }

    private void parseSignedness(PropertyInfo<SignednessValue> info) {
        info.setProperty(SignednessValue.valueOf(stringLiteral(info)));
    }

    private void parseIntegerConstantValue(PropertyInfo<Object> info) {
        boolean isUnsigned = ((SizableInfo) info.getParent()).isUnsigned();
        int size = getSizeInBytes((SizableInfo) info.getParent());
        String hex = idToResult.get(info.getUniqueID());
        int hexSize = hex.length() / 2;

        if (hexSize < size) {
            hex = unsignedExtendToSize(size, hex);
        }

        if (isUnsigned) {
            parseHexToLong(info, hex);
        } else {
            parseSigned(info, hex);
        }
    }

    private int getSizeInBytes(SizableInfo parent) {
        int size = parent.getSizeInfo().getProperty();
        return size;
    }

    private void parseFloatValue(PropertyInfo<Object> info) {
        String str = idToResult.get(info.getUniqueID());
        double value = Double.parseDouble(str);
        info.setProperty(value);
    }

    private void parseStringValue(PropertyInfo<Object> info) {
        info.setProperty(stringLiteral(info));
    }

    private String stringLiteral(ElementInfo info) {
        String str = idToResult.get(info.getUniqueID());
        if (str.startsWith(QueryResultFormat.STRING_MARKER) && str.endsWith(QueryResultFormat.STRING_MARKER)) {
            return str.substring(QueryResultFormat.STRING_MARKER.length(), str.length() - QueryResultFormat.STRING_MARKER.length());
        } else {
            addError("String constant not deliminated correctly", info);
            return "";
        }
    }

    private void parseByteArrayValue(PropertyInfo<Object> info) {
        info.setProperty(byteArrayLiteral(info));
    }

    private byte[] byteArrayLiteral(ElementInfo info) {
        String str = stringLiteral(info);
        if (!str.isEmpty()) {
            return str.getBytes(Charset.forName("UTF-8"));
        } else {
            return new byte[0];
        }
    }

    private void parseIntegerProperty(PropertyInfo<Integer> info) {
        int value = Integer.parseInt(idToResult.get(info.getUniqueID()));
        info.setProperty(value);
    }
}

public final class ReentrantBlockIterator {

    public static class LoopInfo<StateT> {

        public final List<StateT> endStates;
        public final List<StateT> exitStates;

        public LoopInfo(int endCount, int exitCount) {
            endStates = new ArrayList<>(endCount);
            exitStates = new ArrayList<>(exitCount);
        }
    }

    /**
     * Abstract base class for reverse post order iteration over the {@link ControlFlowGraph}.
     */
    public abstract static class BlockIteratorClosure<StateT> {

        /**
         * Create the initial state for the reverse post order iteration over the
         * {@link ControlFlowGraph}.
         */
        protected abstract StateT getInitialState();

        /**
         * Process the current block with the current state during reverse post order iteration.
         */
        protected abstract StateT processBlock(HIRBlock block, StateT currentState);

        /**
         * Merge multiple states when processing {@link HIRBlock} starting with a
         * {@link AbstractMergeNode}.
         */
        protected abstract StateT merge(HIRBlock merge, List<StateT> states);

        /**
         * Clone a state for a successor invocation of
         * {@link BlockIteratorClosure#processBlock(HIRBlock, Object)}.
         */
        protected abstract StateT cloneState(StateT oldState);

        /**
         * Hook for subclasses to apply additional operations after
         * {@link BlockIteratorClosure#cloneState(Object)} for successor blocks.
         */
        protected StateT afterSplit(@SuppressWarnings("unused") HIRBlock successor, StateT oldState) {
            return oldState;
        }

        protected List<StateT> processLoop(Loop<HIRBlock> loop, StateT initialState) {
            return ReentrantBlockIterator.processLoop(this, loop, initialState).exitStates;
        }
    }

    private ReentrantBlockIterator() {
        // no instances allowed
    }

    public static <StateT> LoopInfo<StateT> processLoop(BlockIteratorClosure<StateT> closure, Loop<HIRBlock> loop, StateT initialState) {
        EconomicMap<FixedNode, StateT> blockEndStates = apply(closure, loop.getHeader(), initialState, block -> !(block.getLoop() == loop || block.isLoopHeader()));

        HIRBlock lh = loop.getHeader();
        final int predCount = lh.getPredecessorCount();
        LoopInfo<StateT> info = new LoopInfo<>(predCount - 1, loop.getLoopExits().size());
        for (int i = 1; i < predCount; i++) {
            StateT endState = blockEndStates.get(lh.getPredecessorAt(i).getEndNode());
            // make sure all end states are unique objects
            info.endStates.add(closure.cloneState(endState));
        }
        for (HIRBlock loopExit : loop.getLoopExits()) {
            assert loopExit.getPredecessorCount() == 1 : Assertions.errorMessage(loop, loopExit);
            assert blockEndStates.containsKey(loopExit.getBeginNode()) : loopExit.getBeginNode() + " " + blockEndStates;
            StateT exitState = blockEndStates.get(loopExit.getBeginNode());
            // make sure all exit states are unique objects
            info.exitStates.add(closure.cloneState(exitState));
        }
        return info;
    }

    public static <StateT> void apply(BlockIteratorClosure<StateT> closure, HIRBlock start) {
        apply(closure, start, closure.getInitialState(), null);
    }

    public static <StateT> EconomicMap<FixedNode, StateT> apply(BlockIteratorClosure<StateT> closure, HIRBlock start, StateT initialState, Predicate<HIRBlock> stopAtBlock) {
        Deque<HIRBlock> blockQueue = new ArrayDeque<>();
        /*
         * States are stored on EndNodes before merges, and on BeginNodes after ControlSplitNodes.
         */
        EconomicMap<FixedNode, StateT> states = EconomicMap.create(Equivalence.IDENTITY);

        StateT state = initialState;
        HIRBlock current = start;

        StructuredGraph graph = start.getBeginNode().graph();
        CompilationAlarm compilationAlarm = CompilationAlarm.current();

        while (true) { // TERMINATION ARGUMENT: processing all blocks reverse post order until end
                       // of cfg or until a bailout is triggered because of a long compile
            CompilationAlarm.checkProgress(start.getCfg().graph);
            if (compilationAlarm.hasExpired()) {
                double period = CompilationAlarm.Options.CompilationExpirationPeriod.getValue(graph.getOptions());
                throw new PermanentBailoutException("Compilation exceeded %f seconds during CFG traversal", period);
            }
            HIRBlock next = null;
            if (stopAtBlock != null && stopAtBlock.test(current)) {
                states.put(current.getBeginNode(), state);
            } else {
                state = closure.processBlock(current, state);

                if (current.getSuccessorCount() == 0) {
                    // nothing to do...
                } else if (current.getSuccessorCount() == 1) {
                    HIRBlock successor = current.getSuccessorAt(0);
                    if (successor.isLoopHeader()) {
                        if (current.isLoopEnd()) {
                            // nothing to do... loop ends only lead to loop begins we've already
                            // visited
                            states.put(current.getEndNode(), state);
                        } else {
                            recurseIntoLoop(closure, blockQueue, states, state, successor);
                        }
                    } else if (current.getEndNode() instanceof AbstractEndNode) {
                        AbstractEndNode end = (AbstractEndNode) current.getEndNode();

                        // add the end node and see if the merge is ready for processing
                        AbstractMergeNode merge = end.merge();
                        if (allEndsVisited(states, current, merge)) {
                            ArrayList<StateT> mergedStates = mergeStates(states, state, current, successor, merge);
                            state = closure.merge(successor, mergedStates);
                            next = successor;
                        } else {
                            assert !states.containsKey(end);
                            states.put(end, state);
                        }
                    } else {
                        next = successor;
                    }
                } else {
                    next = processMultipleSuccessors(closure, blockQueue, states, state, current);
                }
            }

            // get next queued block
            if (next != null) {
                current = next;
            } else if (blockQueue.isEmpty()) {
                return states;
            } else {
                current = blockQueue.removeFirst();
                assert current.getPredecessorCount() == 1 : Assertions.errorMessage(current);
                assert states.containsKey(current.getBeginNode());
                state = states.removeKey(current.getBeginNode());
            }
        }
    }

    private void checkExpiration(CompilationAlarm compilationAlarm, StructuredGraph graph) {
        if (compilationAlarm.hasExpired()) {
            double period = CompilationAlarm.Options.CompilationExpirationPeriod.getValue(graph.getOptions());
            throw new PermanentBailoutException("Compilation exceeded %f seconds during CFG traversal", period);
        }
    }

    private static <StateT> boolean allEndsVisited(EconomicMap<FixedNode, StateT> states, HIRBlock current, AbstractMergeNode merge) {
        for (AbstractEndNode forwardEnd : merge.forwardEnds()) {
            if (forwardEnd != current.getEndNode() && !states.containsKey(forwardEnd)) {
                return false;
            }
        }
        return true;
    }

    private static <StateT> HIRBlock processMultipleSuccessors(BlockIteratorClosure<StateT> closure, Deque<HIRBlock> blockQueue, EconomicMap<FixedNode, StateT> states, StateT state,
                    HIRBlock current) {
        assert current.getSuccessorCount() > 1 : Assertions.errorMessageContext("current", current);
        for (int i = 1; i < current.getSuccessorCount(); i++) {
            HIRBlock successor = current.getSuccessorAt(i);
            blockQueue.addFirst(successor);
            states.put(successor.getBeginNode(), closure.afterSplit(successor, closure.cloneState(state)));
        }
        return current.getSuccessorAt(0);
    }

    private static <StateT> ArrayList<StateT> mergeStates(EconomicMap<FixedNode, StateT> states, StateT state, HIRBlock current, HIRBlock successor, AbstractMergeNode merge) {
        ArrayList<StateT> mergedStates = new ArrayList<>(merge.forwardEndCount());
        for (int i = 0; i < successor.getPredecessorCount(); i++) {
            HIRBlock predecessor = successor.getPredecessorAt(i);
            assert predecessor == current || states.containsKey(predecessor.getEndNode());
            StateT endState = predecessor == current ? state : states.removeKey(predecessor.getEndNode());
            mergedStates.add(endState);
        }
        return mergedStates;
    }

    private static <StateT> void recurseIntoLoop(BlockIteratorClosure<StateT> closure, Deque<HIRBlock> blockQueue, EconomicMap<FixedNode, StateT> states, StateT state, HIRBlock successor) {
        // recurse into the loop
        Loop<HIRBlock> loop = successor.getLoop();
        LoopBeginNode loopBegin = (LoopBeginNode) loop.getHeader().getBeginNode();
        assert successor.getBeginNode() == loopBegin : Assertions.errorMessage(successor, successor.getBeginNode(), loopBegin);

        List<StateT> exitStates = closure.processLoop(loop, state);

        int i = 0;
        assert loop.getLoopExits().size() == exitStates.size() : Assertions.errorMessage(loop, loop.getLoopExits(), exitStates);
        for (HIRBlock exit : loop.getLoopExits()) {
            states.put(exit.getBeginNode(), exitStates.get(i++));
            blockQueue.addFirst(exit);
        }
    }
}

/**
 * Garbage collector (incremental or complete) for {@link HeapImpl}.
 */
public final class GCImpl implements GC {
    private static final long K = 1024;
    static final long M = K * K;

    private final GreyToBlackObjRefVisitor greyToBlackObjRefVisitor = new GreyToBlackObjRefVisitor();
    private final GreyToBlackObjectVisitor greyToBlackObjectVisitor = new GreyToBlackObjectVisitor(greyToBlackObjRefVisitor);
    private final RuntimeCodeCacheWalker runtimeCodeCacheWalker = new RuntimeCodeCacheWalker(greyToBlackObjRefVisitor);
    private final RuntimeCodeCacheCleaner runtimeCodeCacheCleaner = new RuntimeCodeCacheCleaner();

    private final GCAccounting accounting = new GCAccounting();
    private final Timers timers = new Timers();

    private final CollectionVMOperation collectOperation = new CollectionVMOperation();
    private final ChunkReleaser chunkReleaser = new ChunkReleaser();

    private final MarkQueue markQueue = new MarkQueue();

    private final CollectionPolicy policy;
    private boolean completeCollection = false;
    private UnsignedWord collectionEpoch = WordFactory.zero();
    private long lastWholeHeapExaminedTimeMillis = -1;

    @Platforms(Platform.HOSTED_ONLY.class)
    GCImpl() {
        this.policy = CollectionPolicy.getInitialPolicy();
        RuntimeSupport.getRuntimeSupport().addShutdownHook(isFirstIsolate -> printGCSummary());
    }

    @Override
    public String getName() {
        if (SubstrateOptions.UseEpsilonGC.getValue()) {
            return "Epsilon GC";
        } else {
            return "Serial GC";
        }
    }

    @Override
    public String getDefaultMaxHeapSize() {
        return String.format("%s%% of RAM", SerialAndEpsilonGCOptions.MaximumHeapSizePercent.getValue());
    }

    @Override
    public void collect(GCCause cause) {
        collect(cause, false);
    }

    public void maybeCollectOnAllocation(UnsignedWord allocationSize) {
        boolean outOfMemory = false;
        if (hasNeverCollectPolicy()) {
            UnsignedWord edenUsed = HeapImpl.getAccounting().getEdenUsedBytes();
            outOfMemory = edenUsed.aboveThan(GCImpl.getPolicy().getMaximumHeapSize());
        } else if (getPolicy().shouldCollectOnAllocation()) {
            AllocationRequiringGCEvent.emit(getCollectionEpoch(), allocationSize);
            outOfMemory = collectWithoutAllocating(GenScavengeGCCause.OnAllocation, false);
        }
        if (outOfMemory) {
            throw OutOfMemoryUtil.heapSizeExceeded();
        }
    }

    @Override
    public void collectionHint(boolean fullGC) {
        if (policy.shouldCollectOnHint(fullGC)) {
            collect(GCCause.HintedGC, fullGC);
        }
    }

    private void collect(GCCause cause, boolean forceFullGC) {
        if (!hasNeverCollectPolicy()) {
            boolean outOfMemory = collectWithoutAllocating(cause, forceFullGC);
            if (outOfMemory) {
                throw OutOfMemoryUtil.heapSizeExceeded();
            }
        }
    }

    @Uninterruptible(reason = "Avoid races with other threads that also try to trigger a GC")
    @RestrictHeapAccess(access = RestrictHeapAccess.Access.NO_ALLOCATION, reason = "Must not allocate in the implementation of garbage collection.")
    boolean collectWithoutAllocating(GCCause cause, boolean forceFullGC) {
        VMError.guarantee(!hasNeverCollectPolicy());

        int size = SizeOf.get(CollectionVMOperationData.class);
        CollectionVMOperationData data = StackValue.get(size);
        UnmanagedMemoryUtil.fill((Pointer) data, WordFactory.unsigned(size), (byte) 0);
        data.setCauseId(cause.getId());
        data.setRequestingEpoch(getCollectionEpoch());
        data.setCompleteCollectionCount(GCImpl.getAccounting().getCompleteCollectionCount());
        data.setRequestingNanoTime(System.nanoTime());
        data.setForceFullGC(forceFullGC);
        enqueueCollectOperation(data);

        boolean outOfMemory = data.getOutOfMemory();
        if (outOfMemory && SerialGCOptions.IgnoreMaxHeapSizeWhileInVMOperation.getValue() && VMOperation.isInProgress()) {
            outOfMemory = false;
        }
        return outOfMemory;
    }

    @Uninterruptible(reason = "Used as a transition between uninterruptible and interruptible code", calleeMustBe = false)
    private void enqueueCollectOperation(CollectionVMOperationData data) {
        collectOperation.enqueue(data);
    }

    /** The body of the VMOperation to do the collection. */
    private void collectOperation(CollectionVMOperationData data) {
        assert VMOperation.isGCInProgress();
        assert getCollectionEpoch().equal(data.getRequestingEpoch()) ||
                        data.getForceFullGC() && GCImpl.getAccounting().getCompleteCollectionCount() == data.getCompleteCollectionCount() : "unnecessary GC?";

        timers.mutator.closeAt(data.getRequestingNanoTime());
        timers.resetAllExceptMutator();

        JfrGCHeapSummaryEvent.emit(JfrGCWhen.BEFORE_GC);
        GCCause cause = GCCause.fromId(data.getCauseId());
        printGCBefore(cause);

        ThreadLocalAllocation.disableAndFlushForAllThreads();
        GenScavengeMemoryPoolMXBeans.singleton().notifyBeforeCollection();
        HeapImpl.getAccounting().notifyBeforeCollection();

        boolean outOfMemory = collectImpl(cause, data.getRequestingNanoTime(), data.getForceFullGC());
        data.setOutOfMemory(outOfMemory);

        HeapImpl.getAccounting().notifyAfterCollection();
        GenScavengeMemoryPoolMXBeans.singleton().notifyAfterCollection();

        printGCAfter(cause);
        JfrGCHeapSummaryEvent.emit(JfrGCWhen.AFTER_GC);

        collectionEpoch = collectionEpoch.add(1);
        timers.mutator.open();
    }

    private boolean collectImpl(GCCause cause, long requestingNanoTime, boolean forceFullGC) {
        boolean outOfMemory;
        long startTicks = JfrTicks.elapsedTicks();
        try {
            outOfMemory = doCollectImpl(cause, requestingNanoTime, forceFullGC);
            if (outOfMemory) {
                // Avoid running out of memory with a full GC that reclaims softly reachable
                // objects
                ReferenceObjectProcessing.setSoftReferencesAreWeak(true);
                try {
                    outOfMemory = doCollectImpl(cause, requestingNanoTime, true);
                } finally {
                    ReferenceObjectProcessing.setSoftReferencesAreWeak(false);
                }
            }
        } finally {
            JfrGCEvents.emitGarbageCollectionEvent(getCollectionEpoch(), cause, startTicks);
        }
        return outOfMemory;
    }

    private boolean doCollectImpl(GCCause cause, long requestingNanoTime, boolean forceFullGC) {
        CommittedMemoryProvider.get().beforeGarbageCollection();

        boolean incremental = !forceFullGC && !policy.shouldCollectCompletely(false);
        boolean outOfMemory = false;

        if (incremental) {
            long startTicks = JfrGCEvents.startGCPhasePause();
            try {
                outOfMemory = doCollectOnce(cause, requestingNanoTime, false, false);
            } finally {
                JfrGCEvents.emitGCPhasePauseEvent(getCollectionEpoch(), "Incremental GC", startTicks);
            }
        }
        if (!incremental || outOfMemory || policy.shouldCollectCompletely(incremental)) {
            if (incremental) { // uncommit unaligned chunks
                CommittedMemoryProvider.get().afterGarbageCollection();
            }
            long startTicks = JfrGCEvents.startGCPhasePause();
            try {
                outOfMemory = doCollectOnce(cause, requestingNanoTime, true, incremental);
            } finally {
                JfrGCEvents.emitGCPhasePauseEvent(getCollectionEpoch(), "Full GC", startTicks);
            }
        }

        HeapImpl.getChunkProvider().freeExcessAlignedChunks();
        CommittedMemoryProvider.get().afterGarbageCollection();

        postcondition();
        return outOfMemory;
    }

    private boolean doCollectOnce(GCCause cause, long requestingNanoTime, boolean complete, boolean followsIncremental) {
        assert !followsIncremental || complete : "An incremental collection cannot be followed by another incremental collection";
        completeCollection = complete;

        accounting.beforeCollection(completeCollection);
        policy.onCollectionBegin(completeCollection, requestingNanoTime);

        Timer collectionTimer = timers.collection.open();
        try {
            if (!followsIncremental) { // we would have verified the heap after the incremental GC
                verifyBeforeGC();
            }
            scavenge(!complete);
            verifyAfterGC();
            if (complete) {
                lastWholeHeapExaminedTimeMillis = System.currentTimeMillis();
            }
        } finally {
            collectionTimer.close();
        }

        accounting.afterCollection(completeCollection, collectionTimer);
        policy.onCollectionEnd(completeCollection, cause);

        UnsignedWord usedBytes = getChunkBytes();
        UnsignedWord freeBytes = policy.getCurrentHeapCapacity().subtract(usedBytes);
        ReferenceObjectProcessing.afterCollection(freeBytes);

        return usedBytes.aboveThan(policy.getMaximumHeapSize()); // out of memory?
    }

    private void verifyBeforeGC() {
        if (SubstrateGCOptions.VerifyHeap.getValue() && SerialGCOptions.VerifyBeforeGC.getValue()) {
            Timer verifyBeforeTimer = timers.verifyBefore.open();
            try {
                boolean success = true;
                success &= HeapVerifier.singleton().verify(HeapVerifier.Occasion.BEFORE_COLLECTION);
                success &= StackVerifier.verifyAllThreads();

                if (!success) {
                    String kind = getGCKind();
                    Log.log().string("Heap verification failed before ").string(kind).string(" garbage collection.").newline();
                    VMError.shouldNotReachHere("Heap verification failed");
                }
            } finally {
                verifyBeforeTimer.close();
            }
        }
    }

    private void verifyAfterGC() {
        if (SubstrateGCOptions.VerifyHeap.getValue() && SerialGCOptions.VerifyAfterGC.getValue()) {
            Timer verifyAfterTime = timers.verifyAfter.open();
            try {
                boolean success = true;
                success &= HeapVerifier.singleton().verify(HeapVerifier.Occasion.AFTER_COLLECTION);
                success &= StackVerifier.verifyAllThreads();

                if (!success) {
                    String kind = getGCKind();
                    Log.log().string("Heap verification failed after ").string(kind).string(" garbage collection.").newline();
                    VMError.shouldNotReachHere("Heap verification failed");
                }
            } finally {
                verifyAfterTime.close();
            }
        }
    }

    private String getGCKind() {
        return isCompleteCollection() ? "complete" : "incremental";
    }

    /**
     * This value is only updated during a GC, so it may be outdated if called from outside the GC
     * VM operation. Also be careful when calling this method during a GC as it might wrongly
     * include chunks that will be freed at the end of the GC.
     */
    public static UnsignedWord getChunkBytes() {
        UnsignedWord youngBytes = HeapImpl.getHeapImpl().getYoungGeneration().getChunkBytes();
        UnsignedWord oldBytes = HeapImpl.getHeapImpl().getOldGeneration().getChunkBytes();
        return youngBytes.add(oldBytes);
    }

    private void printGCBefore(GCCause cause) {
        if (!SubstrateGCOptions.VerboseGC.getValue()) {
            return;
        }

        if (getCollectionEpoch().equal(0)) {
            printGCPrefixAndTime().string("Using ").string(getName()).newline();
            Log log = printGCPrefixAndTime().spaces(2).string("Memory: ");
            if (!PhysicalMemory.isInitialized()) {
                log.string("unknown").newline();
            } else {
                log.rational(PhysicalMemory.getCachedSize(), M, 0).string("M").newline();
            }
            printGCPrefixAndTime().spaces(2).string("Heap policy: ").string(getPolicy().getName()).newline();
            printGCPrefixAndTime().spaces(2).string("Maximum young generation size: ").rational(getPolicy().getMaximumYoungGenerationSize(), M, 0).string("M").newline();
            printGCPrefixAndTime().spaces(2).string("Maximum heap size: ").rational(getPolicy().getMaximumHeapSize(), M, 0).string("M").newline();
            printGCPrefixAndTime().spaces(2).string("Minimum heap size: ").rational(getPolicy().getMinimumHeapSize(), M, 0).string("M").newline();
            printGCPrefixAndTime().spaces(2).string("Aligned chunk size: ").rational(HeapParameters.getAlignedHeapChunkSize(), K, 0).string("K").newline();
            printGCPrefixAndTime().spaces(2).string("Large array threshold: ").rational(HeapParameters.getLargeArrayThreshold(), K, 0).string("K").newline();
        }

        printGCPrefixAndTime().string(cause.getName()).newline();
    }

    private void printGCAfter(GCCause cause) {
        HeapAccounting heapAccounting = HeapImpl.getAccounting();
        HeapSizes beforeGc = heapAccounting.getHeapSizesBeforeGc();

        if (SubstrateGCOptions.VerboseGC.getValue()) {
            printHeapSizeChange("Eden", beforeGc.eden, heapAccounting.getEdenUsedBytes());
            printHeapSizeChange("Survivor", beforeGc.survivor, heapAccounting.getSurvivorUsedBytes());
            printHeapSizeChange("Old", beforeGc.old, heapAccounting.getOldUsedBytes());
            printHeapSizeChange("Free", beforeGc.free, heapAccounting.getBytesInUnusedChunks());

            if (SerialGCOptions.PrintGCTimes.getValue()) {
                timers.logAfterCollection(Log.log());
            }

            if (SerialGCOptions.TraceHeapChunks.getValue()) {
                HeapImpl.getHeapImpl().logChunks(Log.log());
            }
        }

        if (SubstrateGCOptions.PrintGC.getValue() || SubstrateGCOptions.VerboseGC.getValue()) {
            String collectionType = completeCollection ? "Full GC" : "Incremental GC";
            printGCPrefixAndTime().string("Pause ").string(collectionType).string(" (").string(cause.getName()).string(") ")
                            .rational(beforeGc.totalUsed(), M, 2).string("M->").rational(heapAccounting.getUsedBytes(), M, 2).string("M ")
                            .rational(timers.collection.getMeasuredNanos(), TimeUtils.nanosPerMilli, 3).string("ms").newline();
        }
    }

    private void printHeapSizeChange(String text, UnsignedWord before, UnsignedWord after) {
        printGCPrefixAndTime().string("  ").string(text).string(": ").rational(before, M, 2).string("M->").rational(after, M, 2).string("M").newline();
    }

    private Log printGCPrefixAndTime() {
        long uptimeMs = Isolates.getCurrentUptimeMillis();
        return Log.log().string("[").rational(uptimeMs, TimeUtils.millisPerSecond, 3).string("s").string("] GC(").unsigned(collectionEpoch).string(") ");
    }

    private static void postcondition() {
        HeapImpl heap = HeapImpl.getHeapImpl();
        YoungGeneration youngGen = heap.getYoungGeneration();
        assert youngGen.getEden().isEmpty() : "youngGen.getEden() should be empty after a collection.";
    }

    private void checkSanityAfterCollection(YoungGeneration youngGen) {
        assert youngGen.getEden().isEmpty() : "youngGen.getEden() should be empty after a collection.";
    }

    @Fold
    static boolean runtimeAssertions() {
        return RuntimeAssertionsSupport.singleton().desiredAssertionStatus(GCImpl.class);
    }

    @Fold
    public static GCImpl getGCImpl() {
        GCImpl gcImpl = HeapImpl.getGCImpl();
        assert gcImpl != null;
        return gcImpl;
    }

    @Override
    public void collectCompletely(GCCause cause) {
        collect(cause, true);
    }

    @Uninterruptible(reason = "Called from uninterruptible code.", mayBeInlined = true)
    public boolean isCompleteCollection() {
        return completeCollection;
    }

    /** Scavenge, either from dirty roots or from all roots, and process discovered references. */
    private void scavenge(boolean incremental) {
        GreyToBlackObjRefVisitor.Counters counters = greyToBlackObjRefVisitor.openCounters();
        long startTicks;
        try {
            if (!incremental) {
                HeapImpl heap = HeapImpl.getHeapImpl();
                heap.getOldGeneration().absorb(heap.getYoungGeneration());
            }

            Timer rootScanTimer = timers.rootScan.open();
            try {
                startTicks = JfrGCEvents.startGCPhasePause();
                try {
                    cheneyScan(incremental);
                } finally {
                    JfrGCEvents.emitGCPhasePauseEvent(getCollectionEpoch(), incremental ? "Incremental Scan" : "Scan", startTicks);
                }
            } finally {
                rootScanTimer.close();
            }

            if (!incremental) {
                ReferenceObjectProcessing.updateForwardedRefs();

                Timer tenuredPlanningTimer = timers.tenuredPlanning.open();
                try {
                    startTicks = JfrGCEvents.startGCPhasePause();
                    try {
                        HeapImpl.getHeapImpl().getOldGeneration().planCompaction();
                    } finally {
                        JfrGCEvents.emitGCPhasePauseEvent(getCollectionEpoch(), "Tenured Planning", startTicks);
                    }
                } finally {
                    tenuredPlanningTimer.close();
                }

                Timer tenuredFixingTimer = timers.tenuredFixing.open();
                try {
                    HeapImpl.getHeapImpl().getOldGeneration().fixupReferencesBeforeCompaction(chunkReleaser, timers);
                } finally {
                    tenuredFixingTimer.close();
                }

                Timer tenuredCompactingTimer = timers.tenuredCompacting.open();
                try {
                    HeapImpl.getHeapImpl().getOldGeneration().compact(timers);
                } finally {
                    tenuredCompactingTimer.close();
                }
            }

            Timer referenceObjectsTimer = timers.referenceObjects.open();
            try {
                startTicks = JfrGCEvents.startGCPhasePause();
                try {
                    Reference<?> newlyPendingList = ReferenceObjectProcessing.processRememberedReferences();
                    HeapImpl.getHeapImpl().addToReferencePendingList(newlyPendingList);
                } finally {
                    JfrGCEvents.emitGCPhasePauseEvent(getCollectionEpoch(), "Process Remembered References", startTicks);
                }
            } finally {
                referenceObjectsTimer.close();
            }

            if (RuntimeCompilation.isEnabled()) {
                Timer cleanCodeCacheTimer = timers.cleanCodeCache.open();
                try {
                    /*
                     * Cleaning the code cache may invalidate code, which is a rather complex
                     * operation. To avoid side-effects between the code cache cleaning and the GC
                     * core, it is crucial that all the GC core work finished before.
                     */
                    startTicks = JfrGCEvents.startGCPhasePause();
                    try {
                        cleanRuntimeCodeCache();
                    } finally {
                        JfrGCEvents.emitGCPhasePauseEvent(getCollectionEpoch(), "Clean Runtime CodeCache", startTicks);
                    }
                } finally {
                    cleanCodeCacheTimer.close();
                }
            }

            Timer releaseSpacesTimer = timers.releaseSpaces.open();
            try {
                // assert chunkReleaser.isEmpty(); TODO: chunkReleaser is not empty as we already added unaligned chunks
                startTicks = JfrGCEvents.startGCPhasePause();
                try {
                    releaseSpaces();

                    /*
                     * Do not uncommit any aligned chunks yet if we just did an incremental GC so if
                     * we decide to do a full GC next, we can reuse the chunks for copying live old
                     * objects with fewer chunk allocations. In either case, excess chunks are
                     * released later.
                     */
                    boolean keepAllAlignedChunks = incremental;
                    chunkReleaser.release(keepAllAlignedChunks);
                } finally {
                    JfrGCEvents.emitGCPhasePauseEvent(getCollectionEpoch(), "Release Spaces", startTicks);
                }
            } finally {
                releaseSpacesTimer.close();
            }

            startTicks = JfrGCEvents.startGCPhasePause();
            try {
                swapSpaces();
            } finally {
                JfrGCEvents.emitGCPhasePauseEvent(getCollectionEpoch(), "Swap Spaces", startTicks);
            }
        } finally {
            counters.close();
        }
    }

    /**
     * Visit all the memory that is reserved for runtime compiled code. References from the runtime
     * compiled code to the Java heap must be consider as either strong or weak references,
     * depending on whether the code is currently on the execution stack.
     */
    @Uninterruptible(reason = "Called from uninterruptible code.", mayBeInlined = true)
    private void walkRuntimeCodeCache() {
        Timer walkRuntimeCodeCacheTimer = timers.walkRuntimeCodeCache.open();
        try {
            RuntimeCodeInfoMemory.singleton().walkRuntimeMethodsDuringGC(runtimeCodeCacheWalker);
        } finally {
            walkRuntimeCodeCacheTimer.close();
        }
    }

    private void cleanRuntimeCodeCache() {
        Timer cleanRuntimeCodeCacheTimer = timers.cleanRuntimeCodeCache.open();
        try {
            RuntimeCodeInfoMemory.singleton().walkRuntimeMethodsDuringGC(runtimeCodeCacheCleaner);
        } finally {
            cleanRuntimeCodeCacheTimer.close();
        }
    }

    @Uninterruptible(reason = "We don't want any safepoint checks in the core part of the GC.")
    private void cheneyScan(boolean incremental) {
        if (incremental) {
            cheneyScanFromDirtyRoots();
        } else {
            cheneyScanFromRoots();
        }
    }

    @Uninterruptible(reason = "Called from uninterruptible code.", mayBeInlined = true)
    private void cheneyScanFromRoots() {
        Timer cheneyScanFromRootsTimer = timers.cheneyScanFromRoots.open();
        try {
            long startTicks = JfrGCEvents.startGCPhasePause();
            try {
                /* Take a snapshot of the heap so that I can visit all the promoted Objects. */
                /*
                 * Debugging tip: I could move the taking of the snapshot and the scanning of grey
                 * Objects into each of the blackening methods, or even put them around individual
                 * Object reference visits.
                 */
                prepareForPromotion(false);
            } finally {
                JfrGCEvents.emitGCPhasePauseEvent(getCollectionEpoch(), "Snapshot Heap", startTicks);
            }

            startTicks = JfrGCEvents.startGCPhasePause();
            try {
                /*
                 * Make sure all chunks with pinned objects are in toSpace, and any formerly pinned
                 * objects are in fromSpace.
                 */
                promoteChunksWithPinnedObjects();
            } finally {
                JfrGCEvents.emitGCPhasePauseEvent(getCollectionEpoch(), "Promote Pinned Objects", startTicks);
            }

            startTicks = JfrGCEvents.startGCPhasePause();
            try {
                /*
                 * Stack references are grey at the beginning of a collection, so I need to blacken
                 * them.
                 */
                blackenStackRoots();

                /* Custom memory regions which contain object references. */
                walkThreadLocals();

                /*
                 * Native image Objects are grey at the beginning of a collection, so I need to
                 * blacken them.
                 */
                blackenImageHeapRoots();
            } finally {
                JfrGCEvents.emitGCPhasePauseEvent(getCollectionEpoch(), "Scan Roots", startTicks);
            }

            startTicks = JfrGCEvents.startGCPhasePause();
            try {
                /* Visit all the Objects promoted since the snapshot. */
                scanGreyObjects(false);

                if (RuntimeCompilation.isEnabled()) {
                    /*
                     * Visit the runtime compiled code, now that we know all the reachable objects.
                     */
                    walkRuntimeCodeCache();

                    /* Visit all objects that became reachable because of the compiled code. */
                    scanGreyObjects(false);
                }
            } finally {
                JfrGCEvents.emitGCPhasePauseEvent(getCollectionEpoch(), "Scan From Roots", startTicks);
            }
        } finally {
            cheneyScanFromRootsTimer.close();
        }
    }

    @Uninterruptible(reason = "Called from uninterruptible code.", mayBeInlined = true)
    private void cheneyScanFromDirtyRoots() {
        Timer cheneyScanFromDirtyRootsTimer = timers.cheneyScanFromDirtyRoots.open();
        try {
            /*
             * All Objects in the Old Generation are "promoted automatically". That does not make those chunks grey,
             * so I have to use the dirty cards marks to blacken them, but that's what card marks are for.
             */

            long startTicks = JfrGCEvents.startGCPhasePause();
            try {
                /* Take a snapshot of the heap so that I can visit all the promoted Objects. */
                /*
                 * Debugging tip: I could move the taking of the snapshot and the scanning of grey
                 * Objects into each of the blackening methods, or even put them around individual
                 * Object reference visits.
                 */
                prepareForPromotion(true);
            } finally {
                JfrGCEvents.emitGCPhasePauseEvent(getCollectionEpoch(), "Snapshot Heap", startTicks);
            }

            startTicks = JfrGCEvents.startGCPhasePause();
            try {
                /*
                 * Make sure any released objects are in toSpace (because this is an incremental
                 * collection). I do this before blackening any roots to make sure the chunks with
                 * pinned objects are moved entirely, as opposed to promoting the objects
                 * individually by roots. This makes the objects in those chunks grey.
                 */
                promoteChunksWithPinnedObjects();
            } finally {
                JfrGCEvents.emitGCPhasePauseEvent(getCollectionEpoch(), "Promote Pinned Objects", startTicks);
            }

            startTicks = JfrGCEvents.startGCPhasePause();
            try {
                /*
                 * Blacken Objects that are dirty roots. There are dirty cards in ToSpace. Do this
                 * early so I don't have to walk the cards of individually promoted objects, which
                 * will be visited by the grey object scanner.
                 */
                blackenDirtyCardRoots();

                /*
                 * Stack references are grey at the beginning of a collection, so I need to blacken
                 * them.
                 */
                blackenStackRoots();

                /* Custom memory regions which contain object references. */
                walkThreadLocals();

                /*
                 * Native image Objects are grey at the beginning of a collection, so I need to
                 * blacken them.
                 */
                blackenDirtyImageHeapRoots();
            } finally {
                JfrGCEvents.emitGCPhasePauseEvent(getCollectionEpoch(), "Scan Roots", startTicks);
            }

            startTicks = JfrGCEvents.startGCPhasePause();
            try {
                /* Visit all the Objects promoted since the snapshot, transitively. */
                scanGreyObjects(true);

                if (RuntimeCompilation.isEnabled()) {
                    /*
                     * Visit the runtime compiled code, now that we know all the reachable objects.
                     */
                    walkRuntimeCodeCache();

                    /* Visit all objects that became reachable because of the compiled code. */
                    scanGreyObjects(true);
                }
            } finally {
                JfrGCEvents.emitGCPhasePauseEvent(getCollectionEpoch(), "Scan From Roots", startTicks);
            }
        } finally {
            cheneyScanFromDirtyRootsTimer.close();
        }
    }

    @Uninterruptible(reason = "Called from uninterruptible code.", mayBeInlined = true)
    private void promoteChunksWithPinnedObjects() {
        Timer promotePinnedObjectsTimer = timers.promotePinnedObjects.open();
        try {
            // Remove closed pinned objects from the global list. This code needs to use write
            // barriers as the PinnedObjectImpls are a linked list and we don't know in which
            // generation each individual PinnedObjectImpl lives. So, the card table will be
            // modified.
            PinnedObjectImpl pinnedObjects = removeClosedPinnedObjects(PinnedObjectImpl.getPinnedObjects());
            PinnedObjectImpl.setPinnedObjects(pinnedObjects);

            // Promote all chunks that contain pinned objects. The card table of the promoted chunks
            // will be cleaned.
            PinnedObjectImpl cur = pinnedObjects;
            while (cur != null) {
                assert cur.isOpen();
                promotePinnedObject(cur);
                cur = cur.getNext();
            }
        } finally {
            promotePinnedObjectsTimer.close();
        }
    }

    @Uninterruptible(reason = "Called from uninterruptible code.", mayBeInlined = true)
    private static PinnedObjectImpl removeClosedPinnedObjects(PinnedObjectImpl list) {
        PinnedObjectImpl firstOpen = null;
        PinnedObjectImpl lastOpen = null;

        PinnedObjectImpl cur = list;
        while (cur != null) {
            if (cur.isOpen()) {
                if (firstOpen == null) {
                    assert lastOpen == null;
                    firstOpen = cur;
                    lastOpen = cur;
                } else {
                    lastOpen.setNext(cur);
                    lastOpen = cur;
                }
            }
            cur = cur.getNext();
        }

        if (lastOpen != null) {
            lastOpen.setNext(null);
        }
        return firstOpen;
    }

    @NeverInline("Starting a stack walk in the caller frame. " +
                    "Note that we could start the stack frame also further down the stack, because GC stack frames must not access any objects that are processed by the GC. " +
                    "But we don't store stack frame information for the first frame we would need to process.")
    @Uninterruptible(reason = "Required by called JavaStackWalker methods. We are at a safepoint during GC, so it does not change anything for this method.")
    private void blackenStackRoots() {
        Timer blackenStackRootsTimer = timers.blackenStackRoots.open();
        try {
            Pointer sp = readCallerStackPointer();
            CodePointer ip = readReturnAddress();

            walkStackRoots(greyToBlackObjRefVisitor, sp, ip, true);
        } finally {
            blackenStackRootsTimer.close();
        }
    }

    @AlwaysInline("GC performance")
    @Uninterruptible(reason = "Required by called JavaStackWalker methods. We are at a safepoint during GC, so it does not change anything for this method.", mayBeInlined = true)
    static void walkStackRoots(ObjectReferenceVisitor visitor, Pointer sp, CodePointer ip, boolean visitRuntimeCodeInfo) {
        JavaStackWalk walk = StackValue.get(JavaStackWalk.class);
        JavaStackWalker.initWalk(walk, sp, ip);
        walkStack(walk, visitor, visitRuntimeCodeInfo);

        /*
         * Scan the stacks of all the threads. Other threads will be blocked at a safepoint (or
         * in native code) so they will each have a JavaFrameAnchor in their VMThread.
         */
        for (IsolateThread vmThread = VMThreads.firstThread(); vmThread.isNonNull(); vmThread = VMThreads.nextThread(vmThread)) {
            if (vmThread == CurrentIsolate.getCurrentThread()) {
                /*
                 * The current thread is already scanned by code above, so we do not have to do
                 * anything for it here. It might have a JavaFrameAnchor from earlier Java-to-C
                 * transitions, but certainly not at the top of the stack since it is running
                 * this code, so just this scan would be incomplete.
                 */
                continue;
            }
            if (JavaStackWalker.initWalk(walk, vmThread)) {
                walkStack(walk, visitor, visitRuntimeCodeInfo);
            }
        }
    }

    /**
     * This method inlines {@link JavaStackWalker#continueWalk(JavaStackWalk, CodeInfo)} and
     * {@link CodeInfoTable#visitObjectReferences}. This avoids looking up the
     * {@link SimpleCodeInfoQueryResult} twice per frame, and also ensures that there are no virtual
     * calls to a stack frame visitor.
     */
    @AlwaysInline("GC performance")
    @Uninterruptible(reason = "Required by called JavaStackWalker methods. We are at a safepoint during GC, so it does not change anything for this method.", mayBeInlined = true)
    private static void walkStack(JavaStackWalk walk, ObjectReferenceVisitor visitor, boolean visitRuntimeCodeInfo) {
        assert VMOperation.isGCInProgress() : "This methods accesses a CodeInfo without a tether";

        while (true) {
            SimpleCodeInfoQueryResult queryResult = StackValue.get(SimpleCodeInfoQueryResult.class);
            Pointer sp = walk.getSP();
            CodePointer ip = walk.getPossiblyStaleIP();

            /* We are during a GC, so tethering of the CodeInfo is not necessary. */
            CodeInfo codeInfo = CodeInfoAccess.convert(walk.getIPCodeInfo());
            DeoptimizedFrame deoptFrame = Deoptimizer.checkDeoptimized(sp);
            if (deoptFrame == null) {
                if (codeInfo.isNull()) {
                    throw JavaStackWalker.reportUnknownFrameEncountered(sp, ip, deoptFrame);
                }

                CodeInfoAccess.lookupCodeInfo(codeInfo, CodeInfoAccess.relativeIP(codeInfo, ip), queryResult);
                assert Deoptimizer.checkDeoptimized(sp) == null : "We are at a safepoint, so no deoptimization can have happened";

                NonmovableArray<Byte> referenceMapEncoding = CodeInfoAccess.getStackReferenceMapEncoding(codeInfo);
                long referenceMapIndex = queryResult.getReferenceMapIndex();
                if (referenceMapIndex == ReferenceMapIndex.NO_REFERENCE_MAP) {
                    throw CodeInfoTable.reportNoReferenceMap(sp, ip, codeInfo);
                }
                CodeReferenceMapDecoder.walkOffsetsFromPointer(sp, referenceMapEncoding, referenceMapIndex, visitor, null);
            } else {
                /*
                 * This is a deoptimized frame. The DeoptimizedFrame object is stored in the frame,
                 * but it is pinned so we do not need to visit references of the frame.
                 */
            }

            if (RuntimeCompilation.isEnabled() && !CodeInfoAccess.isAOTImageCode(codeInfo) && visitRuntimeCodeInfo) {
                /*
                 * Runtime-compiled code that is currently on the stack must be kept alive. So, we
                 * mark the tether as strongly reachable. The RuntimeCodeCacheWalker will handle all
                 * other object references later on.
                 */
                RuntimeCodeInfoAccess.walkTether(codeInfo, visitor);
                assert RuntimeCodeCacheReachabilityAnalyzer.isReachable(
                        Word.objectToUntrackedPointer(UntetheredCodeInfoAccess.getTetherUnsafe(codeInfo))
                );
            }

            if (!JavaStackWalker.continueWalk(walk, queryResult, deoptFrame)) {
                /* No more caller frame found. */
                return;
            }
        }
    }

    @Uninterruptible(reason = "Called from uninterruptible code.", mayBeInlined = true)
    private void walkThreadLocals() {
        Timer walkThreadLocalsTimer = timers.walkThreadLocals.open();
        try {
            for (IsolateThread isolateThread = VMThreads.firstThread(); isolateThread.isNonNull(); isolateThread = VMThreads.nextThread(isolateThread)) {
                VMThreadLocalSupport.singleton().walk(isolateThread, greyToBlackObjRefVisitor);
            }
        } finally {
            walkThreadLocalsTimer.close();
        }
    }

    @Uninterruptible(reason = "Called from uninterruptible code.", mayBeInlined = true)
    private void blackenDirtyImageHeapRoots() {
        if (!HeapImpl.usesImageHeapCardMarking()) {
            blackenImageHeapRoots();
            return;
        }

        Timer blackenImageHeapRootsTimer = timers.blackenImageHeapRoots.open();
        try {
            for (ImageHeapInfo info = HeapImpl.getFirstImageHeapInfo(); info != null; info = info.next) {
                blackenDirtyImageHeapChunkRoots(info.getFirstWritableAlignedChunk(), info.getFirstWritableUnalignedChunk(), info.getLastWritableUnalignedChunk());
            }

            if (AuxiliaryImageHeap.isPresent()) {
                ImageHeapInfo auxInfo = AuxiliaryImageHeap.singleton().getImageHeapInfo();
                if (auxInfo != null) {
                    blackenDirtyImageHeapChunkRoots(auxInfo.getFirstWritableAlignedChunk(), auxInfo.getFirstWritableUnalignedChunk(), auxInfo.getLastWritableUnalignedChunk());
                }
            }
        } finally {
            blackenImageHeapRootsTimer.close();
        }
    }

    @Uninterruptible(reason = "Called from uninterruptible code.", mayBeInlined = true)
    private void blackenDirtyImageHeapChunkRoots(AlignedHeader firstAligned, UnalignedHeader firstUnaligned, UnalignedHeader lastUnaligned) {
        /*
         * We clean and remark cards of the image heap only during complete collections when we also
         * collect the old generation and can easily remark references into it. It also only makes a
         * difference after references to the runtime heap were nulled, which is assumed to be rare.
         */
        boolean clean = completeCollection;

        AlignedHeader aligned = firstAligned;
        while (aligned.isNonNull()) {
            RememberedSet.get().walkDirtyObjects(aligned, greyToBlackObjectVisitor, clean);
            aligned = HeapChunk.getNext(aligned);
        }

        UnalignedHeader unaligned = firstUnaligned;
        while (unaligned.isNonNull()) {
            RememberedSet.get().walkDirtyObjects(unaligned, greyToBlackObjectVisitor, clean);
            if (unaligned.equal(lastUnaligned)) {
                break;
            }
            unaligned = HeapChunk.getNext(unaligned);
        }
    }

    @Uninterruptible(reason = "Called from uninterruptible code.", mayBeInlined = true)
    private void blackenImageHeapRoots() {
        if (HeapImpl.usesImageHeapCardMarking()) {
            // Avoid scanning the entire image heap even for complete collections: its remembered
            // set contains references into both the runtime heap's old and young generations.
            blackenDirtyImageHeapRoots();
            return;
        }

        Timer blackenImageHeapRootsTimer = timers.blackenImageHeapRoots.open();
        try {
            for (ImageHeapInfo info = HeapImpl.getFirstImageHeapInfo(); info != null; info = info.next) {
                blackenImageHeapRoots(info);
            }

            if (AuxiliaryImageHeap.isPresent()) {
                ImageHeapInfo auxImageHeapInfo = AuxiliaryImageHeap.singleton().getImageHeapInfo();
                if (auxImageHeapInfo != null) {
                    blackenImageHeapRoots(auxImageHeapInfo);
                }
            }
        } finally {
            blackenImageHeapRootsTimer.close();
        }
    }

    @Uninterruptible(reason = "Called from uninterruptible code.", mayBeInlined = true)
    private void blackenImageHeapRoots(ImageHeapInfo imageHeapInfo) {
        walkImageHeapRoots(imageHeapInfo, greyToBlackObjectVisitor);
    }

    @AlwaysInline("GC Performance")
    @Uninterruptible(reason = "Called from uninterruptible code.", mayBeInlined = true)
    static void walkImageHeapRoots(ImageHeapInfo imageHeapInfo, ObjectVisitor visitor) {
        ImageHeapWalker.walkPartitionInline(imageHeapInfo.firstWritableRegularObject, imageHeapInfo.lastWritableRegularObject, visitor, true);
        ImageHeapWalker.walkPartitionInline(imageHeapInfo.firstWritableHugeObject, imageHeapInfo.lastWritableHugeObject, visitor, false);
    }

    @Uninterruptible(reason = "Called from uninterruptible code.", mayBeInlined = true)
    private void blackenDirtyCardRoots() {
        Timer blackenDirtyCardRootsTimer = timers.blackenDirtyCardRoots.open();
        try {
            /*
             * Walk To-Space looking for dirty cards, and within those for old-to-young pointers.
             * Promote any referenced young objects.
             */
            Space oldGenSpace = HeapImpl.getHeapImpl().getOldGeneration().getSpace();
            RememberedSet.get().walkDirtyObjects(oldGenSpace, greyToBlackObjectVisitor, true);
        } finally {
            blackenDirtyCardRootsTimer.close();
        }
    }

    @Uninterruptible(reason = "Called from uninterruptible code.", mayBeInlined = true)
    private static void prepareForPromotion(boolean isIncremental) {
        HeapImpl heap = HeapImpl.getHeapImpl();
        heap.getOldGeneration().prepareForPromotion();
        if (isIncremental) {
            heap.getYoungGeneration().prepareForPromotion();
        }
    }

    @Uninterruptible(reason = "Called from uninterruptible code.", mayBeInlined = true)
    private void scanGreyObjects(boolean isIncremental) {
        Timer scanGreyObjectsTimer = timers.scanGreyObjects.open();
        try {
            if (isIncremental) {
                scanGreyObjectsLoop();
            } else {
                while (!markQueue.isEmpty()) {
                    greyToBlackObjectVisitor.visitObjectInline(markQueue.pop());
                }
            }
        } finally {
            scanGreyObjectsTimer.close();
        }
    }

    @Uninterruptible(reason = "Called from uninterruptible code.", mayBeInlined = true)
    private static void scanGreyObjectsLoop() {
        HeapImpl heap = HeapImpl.getHeapImpl();
        YoungGeneration youngGen = heap.getYoungGeneration();
        OldGeneration oldGen = heap.getOldGeneration();
        boolean hasGrey;
        do {
            hasGrey = youngGen.scanGreyObjects();
            hasGrey |= oldGen.scanGreyObjects();
        } while (hasGrey);
    }

    @AlwaysInline("GC performance")
    @Uninterruptible(reason = "Called from uninterruptible code.", mayBeInlined = true)
    @SuppressWarnings("static-method")
    Object promoteObject(Object original, Word header) {
        HeapImpl heap = HeapImpl.getHeapImpl();
        boolean isAligned = ObjectHeaderImpl.isAlignedHeader(header);
        Header<?> originalChunk = getChunk(original, isAligned);
        Space originalSpace = HeapChunk.getSpace(originalChunk);

        if (completeCollection) {
            if (ObjectHeaderImpl.isIdentityHashFieldOptional()
                    && ObjectHeaderImpl.hasIdentityHashFromAddressInline(header)
                    && isAligned && !((AlignedHeader) originalChunk).getShouldSweepInsteadOfCompact()) {
                /*
                 * The object size will increase due to the identity hashcode being persisted as an additional header field.
                 * Thus, we'll forward the object using OldGeneration#promoteAlignedObject and install the forwarding pointer.
                 */
            } else {
                // Mark objects in the old generation and continue traversal
                // as referenced objects aren't colored gray by copying!
                assert originalSpace.isOldSpace();
                ObjectHeaderImpl.setMarkedBit(original);
                ObjectHeaderImpl.setRememberedSetBit(original);
                markQueue.push(original);
                return original; // Objects in the old generation cannot be promoted further.}
            }
        }

        if (!originalSpace.isFromSpace()) {
            return original;
        }

        Object result = null;
        if (!completeCollection && originalSpace.getNextAgeForPromotion() < policy.getTenuringAge()) {
            if (isAligned) {
                result = heap.getYoungGeneration().promoteAlignedObject(original, (AlignedHeader) originalChunk, originalSpace);
            } else {
                result = heap.getYoungGeneration().promoteUnalignedObject(original, (UnalignedHeader) originalChunk, originalSpace);
            }
            if (result == null) {
                accounting.onSurvivorOverflowed();
            }
        }
        if (result == null) { // complete collection, tenuring age reached, or survivor space full
            if (isAligned) {
                result = heap.getOldGeneration().promoteAlignedObject(original, (AlignedHeader) originalChunk, originalSpace);
            } else {
                result = heap.getOldGeneration().promoteUnalignedObject(original, (UnalignedHeader) originalChunk, originalSpace);
            }
            assert result != null : "promotion failure in old generation must have been handled";
        }

        if (completeCollection) {
            ObjectHeaderImpl.setMarkedBit(result);
            markQueue.push(result);
            assert !ObjectHeaderImpl.hasIdentityHashFromAddressInline(ObjectHeaderImpl.readHeaderFromObject(result));
            assert !ObjectHeaderImpl.hasMarkedBit(original);
        }

        return result;
    }

    @Uninterruptible(reason = "Called from uninterruptible code.", mayBeInlined = true)
    private static Header<?> getChunk(Object obj, boolean isAligned) {
        if (isAligned) {
            return AlignedHeapChunk.getEnclosingChunk(obj);
        }
        assert ObjectHeaderImpl.isUnalignedObject(obj);
        return UnalignedHeapChunk.getEnclosingChunk(obj);
    }

    @Uninterruptible(reason = "Called from uninterruptible code.", mayBeInlined = true)
    private void promotePinnedObject(PinnedObjectImpl pinned) {
        HeapImpl heap = HeapImpl.getHeapImpl();
        Object referent = pinned.getObject();
        if (referent != null && !heap.isInImageHeap(referent)) {
            boolean isAligned = ObjectHeaderImpl.isAlignedObject(referent);
            Header<?> originalChunk = getChunk(referent, isAligned);

            if (completeCollection) {
                /*
                 * As we are using the Mark-and-Compact approach for complete collections,
                 * we have to make sure that the contained chunk is swept instead of compacted.
                 */
                heap.getOldGeneration().markPinnedObject(referent, originalChunk, isAligned);
                return;
            }

            Space originalSpace = HeapChunk.getSpace(originalChunk);
            if (originalSpace.isFromSpace() && !originalSpace.isOldSpace()) {
                boolean promoted = false;
                if (originalSpace.getNextAgeForPromotion() < policy.getTenuringAge()) {
                    promoted = heap.getYoungGeneration().promoteChunk(originalChunk, isAligned, originalSpace);
                    if (!promoted) {
                        accounting.onSurvivorOverflowed();
                    }
                }
                if (!promoted) {
                    heap.getOldGeneration().promoteChunk(originalChunk, isAligned, originalSpace);
                }
            }
        }
    }

    private static void swapSpaces() {
        HeapImpl heap = HeapImpl.getHeapImpl();
        heap.getYoungGeneration().swapSpaces();
    }

    private void releaseSpaces() {
        HeapImpl heap = HeapImpl.getHeapImpl();

        heap.getYoungGeneration().releaseSpaces(chunkReleaser);
        if (completeCollection) {
            heap.getOldGeneration().releaseSpaces(chunkReleaser);
        }
    }

    /**
     * Inside a VMOperation, we are not allowed to do certain things, e.g., perform synchronization
     * (because it can deadlock when a lock is held outside the VMOperation). Similar restrictions
     * apply if we are too early in the attach sequence of a thread.
     */
    static void doReferenceHandling() {
        assert !VMOperation.isInProgress() : "could result in deadlocks";
        assert PlatformThreads.isCurrentAssigned() : "thread is not fully initialized yet";
        /* Most of the time, we won't have a pending reference list. So, we do that check first. */
        if (HeapImpl.getHeapImpl().hasReferencePendingListUnsafe()) {
            long startTime = System.nanoTime();
            ReferenceHandler.processPendingReferencesInRegularThread();

            if (SubstrateGCOptions.VerboseGC.getValue() && SerialGCOptions.PrintGCTimes.getValue()) {
                long executionTime = System.nanoTime() - startTime;
                Log.log().string("[GC epilogue reference processing and cleaners: ").signed(executionTime).string("]").newline();
            }
        }
    }

    @Uninterruptible(reason = "Called from uninterruptible code.", mayBeInlined = true)
    public UnsignedWord getCollectionEpoch() {
        return collectionEpoch;
    }

    public long getMillisSinceLastWholeHeapExamined() {
        long startMillis;
        if (lastWholeHeapExaminedTimeMillis < 0) {
            // no full GC has yet been run, use time since the first allocation
            startMillis = Isolates.getCurrentStartTimeMillis();
        } else {
            startMillis = lastWholeHeapExaminedTimeMillis;
        }
        return System.currentTimeMillis() - startMillis;
    }

