     *
     * The elements of the usage list in order are {@link #usage0}, {@link #usage1} and
     * {@link #extraUsages}. The first null entry terminates the list.
     */
    Node usage0;
    Node usage1;
    Node[] extraUsages;
    int extraUsagesCount;

