    public final NodeClass<? extends Node> getNodeClass() {
        return nodeClass;
    }

    public boolean isAllowedUsageType(InputType type) {
        if (type == InputType.Value) {
            return false;
        }
        return getNodeClass().getAllowedUsageTypes().contains(type);
    }

    private boolean checkReplaceWith(Node replacement) {
        if (graph != null && graph.isFrozen()) {
            fail("cannot modify frozen graph");
        }
        if (replacement == this) {
            fail("cannot replace a node with itself");
        }
        if (isDeleted()) {
            fail("cannot replace deleted node");
        }
        if (replacement != null && replacement.isDeleted()) {
            fail("cannot replace with deleted node %s", replacement);
        }
        return true;
    }

    /**
     * For each use of {@code this} in another node, replace it with {@code replacement}.
     *
     * This is shown by the graph transformation below where edges are from usages to inputs (e.g.
     * {@code this} is an input of {@code n0}).
     *
     * Before:
     *
     * <pre>
     *       this
     *         ^
     *         |
     *        /|\
     *       / | \
     *      /  |  \
     *    n0  n1 ..nN
     *
     * </pre>
     *
     * After:
     *
     * <pre>
     *     replacement
     *         ^
     *         |
     *        /|\
     *       / | \
     *      /  |  \
     *    n0  n1 ..nN
     * </pre>
     *
     * If {@code replacement == null}, then the edges are simply removed.
     */
    public final void replaceAtUsages(Node replacement) {
        replaceAtAllUsages(replacement, false);
    }

    /**
     * For each use of {@code this} in another node, {@code n}, replace it with {@code replacement}
     * if {@code filter == null} or {@code filter.test(n) == true}.
     *
     * @see #replaceAtUsages(Node)
     */
    public final void replaceAtUsages(Node replacement, Predicate<Node> filter) {
        replaceAtUsages(replacement, filter, false, true);
    }

    /**
     * For each use of {@code this} in another node, {@code n}, replace it with {@code replacement}
     * if {@code filter == null} or {@code filter.test(n) == true}.
     *
     * @see #replaceAtUsages(Node)
     */
    public final void replaceAtUsages(Node replacement, Predicate<Node> filter, boolean checkInvariants) {
        replaceAtUsages(replacement, filter, false, checkInvariants);
    }

    /**
     * For each use of {@code this} in another node, replace it with {@code replacement} and then
     * {@linkplain #safeDelete() remove} {@code this} from the graph.
     *
     * @see #replaceAtUsages(Node)
     */
    public final void replaceAtUsagesAndDelete(Node replacement) {
        replaceAtUsages(replacement, null, true, true);
        safeDelete();
    }

    /**
     * For each use of {@code this} in another node, {@code n}, replace it with {@code replacement}
     * if {@code filter == null} or {@code filter.test(n) == true}.
     *
     * @param forDeletion specifies if the caller will {@linkplain #safeDelete() remove}
     *            {@code this} from the graph after this method returns
     * @see #replaceAtUsages(Node)
     */
    private void replaceAtUsages(Node replacement, Predicate<Node> filter, boolean forDeletion, boolean checkInvariants) {
        if (filter == null) {
            replaceAtAllUsages(replacement, forDeletion);
        } else {
            replaceAtMatchingUsages(replacement, filter, forDeletion);
        }
        assert !checkInvariants || checkReplaceAtUsagesInvariants(replacement);
    }

    /**
     * Subclasses can override this to check invariants related to replacing uses of {@code this}.
     *
     * @param replacement
     * @return {@code true} if all invariants hold
     */
    protected boolean checkReplaceAtUsagesInvariants(Node replacement) {
        return true;
    }

    /**
     * For each use of {@code this} in another node, replace it with {@code replacement}.
     *
     * @param forDeletion specifies if the caller will {@linkplain #safeDelete() remove}
     *            {@code this} from the graph after this method returns
     */
    public final void replaceAtAllUsages(Node replacement, boolean forDeletion) {
        checkReplaceWith(replacement);
        if (usage0 == null) {
            return;
        }
        replaceAtUsage(replacement, forDeletion, usage0);
        usage0 = null;

        if (usage1 == null) {
            return;
        }
        replaceAtUsage(replacement, forDeletion, usage1);
        usage1 = null;

        if (extraUsagesCount <= 0) {
            return;
        }
        for (int i = 0; i < extraUsagesCount; i++) {
            Node usage = extraUsages[i];
            replaceAtUsage(replacement, forDeletion, usage);
        }
        this.extraUsages = EMPTY_ARRAY;
        this.extraUsagesCount = 0;
    }

    /**
     * For the use of {@code this} in another node represented by {@code usage}, replace it with
     * {@code replacement}.
     *
     * @param forDeletion specifies if the caller will {@linkplain #safeDelete() remove}
     *            {@code this} from the graph after this method returns
     *
     * @see #replaceAtUsages(Node)
     */
    private void replaceAtUsage(Node replacement, boolean forDeletion, Node usage) {
        boolean result = usage.getNodeClass().replaceFirstInput(usage, this, replacement);
        assertTrue(result, "not found in inputs, usage: %s", usage);
        /*
         * Don't notify for nodes which are about to be deleted.
         */
        if (!forDeletion || usage != this) {
            maybeNotifyInputChanged(usage);
        }
        if (replacement != null) {
            replacement.addUsage(usage);
        }
    }

    /**
     * For each use of {@code this} in another node, {@code n}, replace it with {@code replacement}
     * if {@code filter.test(n) == true}.
     *
     * @param forDeletion specifies if the caller will {@linkplain #safeDelete() remove}
     *            {@code this} from the graph after this method returns
     *
     * @see #replaceAtUsages(Node)
     */
    private void replaceAtMatchingUsages(Node replacement, Predicate<Node> filter, boolean forDeletion) {
        Objects.requireNonNull(filter);
        checkReplaceWith(replacement);
        int i = 0;
        int usageCount = this.getUsageCount();
        while (i < usageCount) {
            Node usage = this.getUsageAt(i);
            if (filter.test(usage)) {
                replaceAtUsage(replacement, forDeletion, usage);
                this.movUsageFromEndTo(i);
                usageCount--;
            } else {
                ++i;
            }
        }
    }

    private Node getUsageAt(int index) {
        if (index == 0) {
            return this.usage0;
        } else if (index == 1) {
            return this.usage1;
        } else {
            return this.extraUsages[index - INLINE_USAGE_COUNT];
        }
    }

    public Node singleUsage() {
        assert hasExactlyOneUsage();
        return this.usage0;
    }

    /**
     * For each use of {@code this} in another node, {@code n}, replace it with {@code replacement}
     * if {@code filter.test(n) == true}.
     *
     * @see #replaceAtUsages(Node)
     */
    public void replaceAtMatchingUsages(Node replacement, NodePredicate usagePredicate) {
        checkReplaceWith(replacement);
        replaceAtMatchingUsages(replacement, usagePredicate, false);
    }

    private void replaceAtUsagePos(Node replacement, Node usage, Position pos) {
        pos.initialize(usage, replacement);
        maybeNotifyInputChanged(usage);
        if (replacement != null) {
            replacement.addUsage(usage);
        }
    }

    /**
     * For each use of {@code this} in another node, {@code n}, replace it with {@code replacement}
     * if the type of the use is {@code inputType}.
     *
     * @see #replaceAtUsages(Node)
     */
    public void replaceAtUsages(Node replacement, InputType inputType) {
        checkReplaceWith(replacement);
        int i = 0;
        int usageCount = this.getUsageCount();
        if (usageCount == 0) {
            return;
        }
        usages: while (i < usageCount) {
            Node usage = this.getUsageAt(i);
            for (Position pos : usage.inputPositions()) {
                if (pos.getInputType() == inputType && pos.get(usage) == this) {
                    replaceAtUsagePos(replacement, usage, pos);
                    this.movUsageFromEndTo(i);
                    usageCount--;
                    continue usages;
                }
            }
            i++;
        }
        if (hasNoUsages()) {
            maybeNotifyZeroUsages(this);
        }
    }

    /**
     * For each use of {@code this} in another node, {@code n}, replace it with {@code replacement}
     * if the type of the use is in {@code inputTypes}.
     *
     * @see #replaceAtUsages(Node)
     */
    public void replaceAtUsages(Node replacement, InputType... inputTypes) {
        checkReplaceWith(replacement);
        int i = 0;
        int usageCount = this.getUsageCount();
        if (usageCount == 0) {
            return;
        }
        usages: while (i < usageCount) {
            Node usage = this.getUsageAt(i);
            for (Position pos : usage.inputPositions()) {
                for (InputType type : inputTypes) {
                    if (pos.getInputType() == type && pos.get(usage) == this) {
                        replaceAtUsagePos(replacement, usage, pos);
                        this.movUsageFromEndTo(i);
                        usageCount--;
                        continue usages;
                    }
                }
            }
            i++;
        }
        if (hasNoUsages()) {
            maybeNotifyZeroUsages(this);
        }
    }

    private void maybeNotifyInputChanged(Node node) {
        if (graph != null) {
            assert !graph.isFrozen();
            NodeEventListener listener = graph.nodeEventListener;
            fireNodeEvent(node, listener, Graph.NodeEvent.INPUT_CHANGED);
            graph.edgeModificationCount++;
        }
    }

    /**
     * Iterates over each {@link NodeEventListener} attached to {@code this.graph()} if
     * {@code node.isAlive()} and notifies the listener that {@code node} has had its last usage
     * removed.
     */
    public void maybeNotifyZeroUsages(Node node) {
        if (graph != null && node.isAlive()) {
            assert !graph.isFrozen();
            NodeEventListener listener = graph.nodeEventListener;
            fireNodeEvent(node, listener, Graph.NodeEvent.ZERO_USAGES);
        }
    }

    private void fireNodeEvent(Node node, NodeEventListener listener, Graph.NodeEvent nodeEvent) {
        if (listener != null) {
            listener.event(nodeEvent, node);
        }
    }

    /**
     * Updates the control flow edge, if it exists, from {@link #predecessor()} to {@code this} to
     * have a target of {@code replacement}.
     */
    public void replaceAtPredecessor(Node replacement) {
        checkReplaceWith(replacement);
        if (predecessor != null) {
            if (!predecessor.getNodeClass().replaceFirstSuccessor(predecessor, this, replacement)) {
                fail("not found in successors, predecessor: %s", predecessor);
            }
            predecessor.updatePredecessor(this, replacement);
        }
    }

    /**
     * Replaces {@code this} at its predecessor (if any) and its usages with {@code replacement} and
     * removes it from its graph.
     */
    public void replaceAndDelete(Node replacement) {
        checkReplaceWith(replacement);
        if (replacement == null) {
            fail("cannot replace with null");
        }
        if (this.hasUsages()) {
            replaceAtUsages(replacement);
        }
        replaceAtPredecessor(replacement);
        this.safeDelete();
    }

    /**
     * Finds the first {@link Successor} in {@code this} whose value is {@code oldSuccessor} and
     * replaces it with {@code newSuccessor}. The predecessor fields in {@code oldSuccessor} and
     * {@code newSuccessor} are updated to reflect any change made.
     */
    public void replaceFirstSuccessor(Node oldSuccessor, Node newSuccessor) {
        if (nodeClass.replaceFirstSuccessor(this, oldSuccessor, newSuccessor)) {
            updatePredecessor(oldSuccessor, newSuccessor);
        }
    }

    /**
     * Finds the first {@link Input} or {@link OptionalInput} in {@code this} whose value is
     * {@code oldInput} and replaces it with {@code newInput}. If the input is changed, the usage
     * info for {@code oldInput} and {@code newInput} is updated as well.
     *
     * Before {@code this.replaceFirstInput(n0, n2)}:
     *
     * <pre>
     *       n0  n1  n0
     *        \  |  /
     *         \ | /
     *          \|/
     *           |
     *           V
     *         this
     * </pre>
     *
     * After {@code this.replaceFirstInput(n0, n2)}:
     *
     * <pre>
     *       n2  n1  n0
     *        \  |  /
     *         \ | /
     *          \|/
     *           |
     *           V
     *         this
     * </pre>
     */
    public void replaceFirstInput(Node oldInput, Node newInput) {
        if (nodeClass.replaceFirstInput(this, oldInput, newInput)) {
            updateUsages(oldInput, newInput);
        }
    }

    /**
     * Finds all {@link Input}s and {@link OptionalInput}s in {@code this} whose value is
     * {@code oldInput} and replaces them with {@code newInput}. If any input is changed, the usage
     * info for {@code oldInput} and {@code newInput} is updated as well.
     *
     * Before {@code this.replaceAllInputs(n0, n2)}:
     *
     * <pre>
     *       n0  n1  n0
     *        \  |  /
     *         \ | /
     *          \|/
     *           |
     *           V
     *         this
     * </pre>
     *
     * After {@code this.replaceAllInputs(n0, n2)}:
     *
     * <pre>
     *       n2  n1  n2
     *        \  |  /
     *         \ | /
     *          \|/
     *           |
     *           V
     *         this
     * </pre>
     */
    public void replaceAllInputs(Node oldInput, Node newInput) {
        while (nodeClass.replaceFirstInput(this, oldInput, newInput)) {
            updateUsages(oldInput, newInput);
        }
    }

    public void clearInputs() {
        assertFalse(isDeleted(), "cannot clear inputs of deleted node");
        getNodeClass().unregisterAtInputsAsUsage(this);
    }

    boolean removeThisFromUsages(Node n) {
        return n.removeUsage(this);
    }

    public void clearSuccessors() {
        assertFalse(isDeleted(), "cannot clear successors of deleted node");
        getNodeClass().unregisterAtSuccessorsAsPredecessor(this);
    }

    private boolean checkDeletion() {
        assertTrue(isAlive(), "must be alive");
        assertTrue(hasNoUsages(), "cannot delete node %s because of usages: %s", this, usages());
        assertTrue(predecessor == null, "cannot delete node %s because of predecessor: %s", this, predecessor);
        return true;
    }

    /**
     * Removes {@code this} from {@code this.graph()}. This node must have no
     * {@linkplain Node#usages() usages} and no {@linkplain #predecessor() predecessor}.
     */
    public void safeDelete() {
        assert checkDeletion();
        this.clearInputs();
        this.clearSuccessors();
        markDeleted();
    }

    public void markDeleted() {
        graph.unregister(this);
        id = DELETED_ID_START - id;
        assert isDeleted();
    }

    public final Node copyWithInputs() {
        return copyWithInputs(true);
    }

    public final Node copyWithInputs(boolean insertIntoGraph) {
        Node newNode = clone(insertIntoGraph ? graph : null, WithOnlyInputEdges);
        if (insertIntoGraph) {
            for (Node input : inputs()) {
                input.addUsage(newNode);
            }
        }
        return newNode;
    }

    /**
     * @param newNode the result of cloning {@code this} or {@link Unsafe#allocateInstance(Class)
     *            raw allocating} a copy of {@code this}
     * @param type the type of edges to process
     * @param edgesToCopy if {@code type} is in this set, the edges are copied otherwise they are
     *            cleared
     */
    private void copyOrClearEdgesForClone(Node newNode, Edges.Type type, EnumSet<Edges.Type> edgesToCopy) {
        if (edgesToCopy.contains(type)) {
            getNodeClass().getEdges(type).copy(this, newNode);
        } else {
            // The direct edges are already null
            getNodeClass().getEdges(type).initializeLists(newNode, this);
        }
    }

    public static final EnumSet<Edges.Type> WithAllEdges = EnumSet.allOf(Edges.Type.class);
    public static final EnumSet<Edges.Type> WithOnlyInputEdges = EnumSet.of(Edges.Type.Inputs);

    /**
     * Makes a copy of {@code this} in(to) a given graph.
     *
     * @param into the graph in which the copy will be registered (which may be
     *            {@code this.graph()}) or null if the copy should not be registered in a graph
     * @param edgesToCopy specifies the edges to be copied. The edges not specified in this set are
     *            initialized to their default value (i.e., {@code null} for a direct edge, an empty
     *            list for an edge list)
     * @return the copy of {@code this}
     */
    final Node clone(Graph into, EnumSet<Edges.Type> edgesToCopy) {
        final NodeClass<? extends Node> nodeClassTmp = getNodeClass();
        boolean useIntoLeafNodeCache = false;
        if (into != null) {
            if (nodeClassTmp.valueNumberable() && nodeClassTmp.isLeafNode()) {
                useIntoLeafNodeCache = true;
                Node otherNode = into.findNodeInCache(this);
                if (otherNode != null) {
                    return otherNode;
                }
            }
        }

        Node newNode = null;
        try {
            newNode = (Node) UNSAFE.allocateInstance(getClass());
            newNode.nodeClass = nodeClassTmp;
            nodeClassTmp.getData().copy(this, newNode);
            copyOrClearEdgesForClone(newNode, Type.Inputs, edgesToCopy);
            copyOrClearEdgesForClone(newNode, Type.Successors, edgesToCopy);
        } catch (Exception e) {
            throw new GraalGraphError(e).addContext(this);
        }
        newNode.graph = into;
        newNode.id = INITIAL_ID;
        if (getNodeSourcePosition() != null && (into == null || into.trackNodeSourcePosition())) {
            newNode.setNodeSourcePosition(getNodeSourcePosition());
        }
        if (getInsertionPosition() != null) {
            newNode.setInsertionPosition(getInsertionPosition());
        }
        if (into != null) {
            into.register(newNode);
        }
        newNode.extraUsages = EMPTY_ARRAY;

        if (into != null && useIntoLeafNodeCache) {
            into.putNodeIntoCache(newNode);
        }
        newNode.afterClone(this);
        return newNode;
    }

    protected void afterClone(@SuppressWarnings("unused") Node other) {
    }

    @SuppressWarnings("unchecked")
    protected boolean verifyInputs() {
        InputEdges inputEdges = nodeClass.getInputEdges();

        // Verify properties of direct inputs
        for (int i = 0; i < inputEdges.getDirectCount(); i++) {
            Node input = (Node) inputEdges.get(this, i);
            verifyInput(inputEdges, i, input);
        }

        // Verify properties of input list objects
        for (int i = inputEdges.getDirectCount(); i < inputEdges.getCount(); i++) {
            Object inputList = inputEdges.get(this, i);
            if (inputList == null) {
                assertTrue(inputEdges.isOptional(i), "non-optional input list %s cannot be null in %s (fix nullness or use @OptionalInput)", inputEdges.getName(i), this);
            } else {
                NodeList<Node> nodeList = (NodeList<Node>) inputList;
                for (Node input : nodeList) {
                    verifyInput(inputEdges, i, input);
                }
            }
        }
        return true;
    }

    private void verifyInput(InputEdges inputEdges, int i, Node input) {
        if (input == null) {
            assertTrue(inputEdges.isOptional(i), "non-optional input %s cannot be null in %s (fix nullness or use @OptionalInput)", inputEdges.getName(i), this);
        } else {
            assertFalse(input.isDeleted(), "input was deleted %s", input);
            assertTrue(input.isAlive(), "input is not alive yet, i.e., it was not yet added to the graph");
            InputType inputType = inputEdges.getInputType(i);
            assertTrue(inputType == InputType.Unchecked || input.isAllowedUsageType(inputType), "invalid usage type input:%s inputType:%s inputField:%s", input,
                            inputType, inputEdges.getName(i));
            Class<?> expectedType = i < inputEdges.getDirectCount() ? inputEdges.getType(i) : Node.class;
            assertTrue(expectedType.isAssignableFrom(input.getClass()), "Invalid input type for %s: expected a %s but was a %s", inputEdges.getName(i), expectedType, input.getClass());
        }
    }

    public final boolean verify() {
        return verify(true);
    }

    /**
     * Basic verification of node properties. This method is final so that a node cannot
     * accidentally skip calling super(). Node specific verification should be done in
     * {@link #verifyNode()}.
     */
    public final boolean verify(boolean verifyInputs) {
        assertTrue(isAlive(), "cannot verify inactive node %s", this);
        assertTrue(graph != null, "null graph");
        if (verifyInputs) {
            verifyInputs();
        }
        if (graph.verifyGraphEdges) {
            verifyEdges();
        }
        verifyNode();
        return true;
    }

    /**
     * Verify node properties which are not covered by {@link #verify()}.
     */
    protected boolean verifyNode() {
        return true;
    }

    /**
     * Perform expensive verification of inputs, usages, predecessors and successors.
     *
     * @return true
     */
    public boolean verifyEdges() {
        for (Node input : inputs()) {
            assertTrue(input == null || input.usages().contains(this), "missing usage of %s in input %s", this, input);
        }

        for (Node successor : successors()) {
            assertTrue(successor.predecessor() == this, "missing predecessor in %s (actual: %s)", successor, successor.predecessor());
            assertTrue(successor.graph == graph, "mismatching graph in successor %s", successor);
        }
        for (Node usage : usages()) {
            assertFalse(usage.isDeleted(), "usage %s must never be deleted", usage);
            assertTrue(usage.inputs().contains(this), "missing input in usage %s", usage);
            boolean foundThis = false;
            for (Position pos : usage.inputPositions()) {
                if (pos.get(usage) == this) {
                    foundThis = true;
                    if (pos.getInputType() != InputType.Unchecked) {
                        assertTrue(isAllowedUsageType(pos.getInputType()), "invalid input of type %s from %s to %s (%s)", pos.getInputType(), usage, this, pos.getName());
                    }
                }
            }
            assertTrue(foundThis, "missing input in usage %s", usage);
        }

        if (predecessor != null) {
            assertFalse(predecessor.isDeleted(), "predecessor %s must never be deleted", predecessor);
            assertTrue(predecessor.successors().contains(this), "missing successor in predecessor %s", predecessor);
        }
        return true;
    }

    public boolean assertTrue(boolean condition, String message, Object... args) {
        if (condition) {
            return true;
        } else {
            throw fail(message, args);
        }
    }

    public boolean assertFalse(boolean condition, String message, Object... args) {
        if (condition) {
            throw fail(message, args);
        } else {
            return true;
        }
    }

    protected GraalGraphError fail(String message, Object... args) throws GraalGraphError {
        throw new GraalGraphError(message, args).addContext(this);
    }

    public Iterable<? extends Node> cfgPredecessors() {
        if (predecessor == null) {
            return Collections.emptySet();
        } else {
            return Collections.singleton(predecessor);
        }
    }

    /**
     * Returns an iterator that will provide all control-flow successors of {@code this}. Normally
     * this will be the contents of all fields annotated with {@link Successor}, but some node
     * classes (like EndNode) may return different nodes.
     */
    public Iterable<? extends Node> cfgSuccessors() {
        return successors();
    }

    /**
     * Nodes using their {@link #id} as the hash code. This works very well when nodes of the same
     * graph are stored in sets. It can give bad behavior when storing nodes of different graphs in
     * the same set.
     */
    @Override
    public final int hashCode() {
        assert !this.isUnregistered() : "node not yet constructed";
        if (this.isDeleted()) {
            return -id + DELETED_ID_START;
        }
        return id;
    }

    /*
     * Do not overwrite the equality test of a node in subclasses. Equality tests must rely solely
     * on identity.
     */

    /**
     * Provides a {@link Map} of properties of {@code this} for use in debugging (e.g., to view in
     * the ideal graph visualizer).
     */
    public final Map<Object, Object> getDebugProperties() {
        return getDebugProperties(new HashMap<>());
    }

    /**
     * Fills a {@link Map} with properties of {@code this} for use in debugging (e.g., to view in
     * the ideal graph visualizer). Subclasses overriding this method should also fill the map using
     * their superclass.
     *
     * @param map
     */
    public Map<Object, Object> getDebugProperties(Map<Object, Object> map) {
        Fields properties = getNodeClass().getData();
        for (int i = 0; i < properties.getCount(); i++) {
            Object value = properties.get(this, i);
            if (properties.getType(i) == Character.TYPE) {
                // Convert a char to an int as chars are not guaranteed to printable/viewable
                char ch = (char) value;
                value = Integer.valueOf(ch);
            }
            map.put(properties.getName(i), value);
        }
        NodeSourcePosition pos = getNodeSourcePosition();
        if (pos != null) {
            map.put("nodeSourcePosition", pos);
        }
        NodeCreationStackTrace creation = getCreationPosition();
        if (creation != null) {
            map.put("nodeCreationPosition", creation.getStrackTraceString());
        }
        NodeInsertionStackTrace insertion = getInsertionPosition();
        if (insertion != null) {
            map.put("nodeInsertionPosition", insertion.getStrackTraceString());
        }
        return map;
    }

    /**
     * This method is a shortcut for {@link #toString(Verbosity)} with {@link Verbosity#Short}.
     */
    @Override
    public final String toString() {
        return toString(Verbosity.Short);
    }

    /**
     * Creates a String representation for {@code this} with a given {@link Verbosity}.
     */
    public String toString(Verbosity verbosity) {
        switch (verbosity) {
            case Id:
                return Integer.toString(id);
            case Name:
                return getNodeClass().shortName();
            case Short:
                return toString(Verbosity.Id) + "|" + toString(Verbosity.Name);
            case Long:
                return toString(Verbosity.Short);
            case Debugger:
            case All: {
                StringBuilder str = new StringBuilder();
                str.append(toString(Verbosity.Short)).append(" { ");
                for (Map.Entry<Object, Object> entry : getDebugProperties().entrySet()) {
                    str.append(entry.getKey()).append("=").append(entry.getValue()).append(", ");
                }
                str.append(" }");
                return str.toString();
            }
            default:
                throw new RuntimeException("unknown verbosity: " + verbosity);
        }
    }

    @Deprecated
    public int getId() {
        return id;
    }

    @Deprecated
    public int getIdBeforeDeletion() {
        assert isDeleted();
        return (id - DELETED_ID_START) * -1;
    }

    @Override
    public void formatTo(Formatter formatter, int flags, int width, int precision) {
        if ((flags & FormattableFlags.ALTERNATE) == FormattableFlags.ALTERNATE) {
            formatter.format("%s", toString(Verbosity.Id));
        } else if ((flags & FormattableFlags.UPPERCASE) == FormattableFlags.UPPERCASE) {
            // Use All here since Long is only slightly longer than Short.
            formatter.format("%s", toString(Verbosity.All));
        } else {
            formatter.format("%s", toString(Verbosity.Short));
        }

        boolean neighborsAlternate = ((flags & FormattableFlags.LEFT_JUSTIFY) == FormattableFlags.LEFT_JUSTIFY);
        int neighborsFlags = (neighborsAlternate ? FormattableFlags.ALTERNATE | FormattableFlags.LEFT_JUSTIFY : 0);
        if (width > 0) {
            if (this.predecessor != null) {
                formatter.format(" pred={");
                this.predecessor.formatTo(formatter, neighborsFlags, width - 1, 0);
                formatter.format("}");
            }

            for (Position position : this.inputPositions()) {
                Node input = position.get(this);
                if (input != null) {
                    formatter.format(" ");
                    formatter.format(position.getName());
                    formatter.format("={");
                    input.formatTo(formatter, neighborsFlags, width - 1, 0);
                    formatter.format("}");
                }
            }
        }

        if (precision > 0) {
            if (!hasNoUsages()) {
                formatter.format(" usages={");
                int z = 0;
                for (Node usage : usages()) {
                    if (z != 0) {
                        formatter.format(", ");
                    }
                    usage.formatTo(formatter, neighborsFlags, 0, precision - 1);
                    ++z;
                }
                formatter.format("}");
            }

            for (Position position : this.successorPositions()) {
                Node successor = position.get(this);
                if (successor != null) {
                    formatter.format(" ");
                    formatter.format(position.getName());
                    formatter.format("={");
                    successor.formatTo(formatter, neighborsFlags, 0, precision - 1);
                    formatter.format("}");
                }
            }
        }
    }

    /**
     * Determines if this node's {@link NodeClass#getData() data} fields are equal to the data
     * fields of another node of the same type. Primitive fields are compared by value and
     * non-primitive fields are compared by {@link Objects#equals(Object, Object)}.
     *
     * The result of this method undefined if {@code other.getClass() != this.getClass()}.
     *
     * @param other a node of exactly the same type as {@code this}
     * @return true if the data fields of this object and {@code other} are equal
     */
    public final boolean valueEquals(Node other) {
        return getNodeClass().dataEquals(this, other);
    }

    /**
     * Determines if {@code this} is equal to the other node while ignoring differences in
     * {@linkplain Successor control-flow} edges.
     *
     */
    public final boolean dataFlowEquals(Node other) {
        return this == other || nodeClass == other.getNodeClass() && this.valueEquals(other) && nodeClass.equalInputs(this, other);
    }

    public final void pushInputs(NodeStack stack) {
        getNodeClass().pushInputs(this, stack);
    }

    public final NodeSize estimatedNodeSize() {
        try {
            return dynamicNodeSizeEstimate();
        } catch (Exception e) {
            throw GraalError.shouldNotReachHere(e, "Exception during node cost estimation"); // ExcludeFromJacocoGeneratedReport
        }
    }

    /**
     * Node subclasses should override this method if they need to specify a dynamically calculated
     * {@link NodeSize} value. If the node size is static please use {@link NodeInfo#size()}.
     *
     * NOTE: When overriding this method, make sure that *all* field reads are null checked (even if
     * Java semantics seemingly make the value of the field non-null). This is necessary because
     * node size estimates are needed even during graph decoding which, for some nodes, first
     * reflectively creates a stub and then later, reflectively, populates its fields. This method
     * could be invoked between these two points. For this reason, when overriding this method
     * assume that all fields can and will be null.
     *
     * @return The estimated node size for this node.
     */
    protected NodeSize dynamicNodeSizeEstimate() {
        return nodeClass.size();
    }

    public NodeCycles estimatedNodeCycles() {
        return nodeClass.cycles();
    }

}

public final class ControlFlowGraph implements AbstractControlFlowGraph<HIRBlock> {

    public static class CFGOptions {
        /**
         * Take {@link LoopEndNode} frequencies to calculate the frequency of a loop instead of
         * {@link LoopExitNode} frequency. For this a sum of the {@link LoopEndNode} frequencies is
         * taken. This sum is subtracted from 1 to get the frequency of all paths out of the loop.
         * Note that this ignores the frequency of all paths out of the loop that do not go through
         * a loop exit, i.e. control flow sinks like deopt nodes that do not require explicit loop
         * exit nodes. The formula that must hold here is sumLoopEndFrequency + sumSinkFrequency +
         * sumLoopExitFrequency = 1.
         *
         * This option only exists to debug loop frequency calculation differences when taking exits
         * or ends. A vastly different loop frequency calculated with the {@link LoopEndNode} sum
         * indicates there are many non 0 frequency paths out of a loop.
         */
        //@formatter:off
        @Option(help = "Derive loop frequencies only from backedge frequencies instead of from loop exit frequencies.", type = OptionType.Debug)
        public static final OptionKey<Boolean> UseLoopEndFrequencies = new OptionKey<>(false);
        @Option(help = "Debug flag to dump loop frequency differences computed based on loop end or exit nodes." +
                       "If the frequencies diverge a lot, this may indicate missing profiles on control flow" +
                       "inside the loop body.", type = OptionType.Debug)
        public static final OptionKey<Boolean> DumpEndVersusExitLoopFrequencies = new OptionKey<>(false);
        @Option(help = "Scaling factor of frequency difference computed based on loop ends or exits", type = OptionType.Debug)
        public static final OptionKey<Double> LoopExitVsLoopEndFrequencyDiff = new OptionKey<>(1000D);
        //@formatter:on
    }

    /**
     * Don't allow relative frequency values to be become too small or too high as this makes
     * frequency calculations over- or underflow the range of a double. This commonly happens with
     * infinite loops within infinite loops. The value is chosen a bit lower than half the maximum
     * exponent supported by double. That way we can never overflow to infinity when multiplying two
     * relative frequency values.
     */
    public static final double MIN_RELATIVE_FREQUENCY = 0x1.0p-500;
    public static final double MAX_RELATIVE_FREQUENCY = 1 / MIN_RELATIVE_FREQUENCY;

    public final StructuredGraph graph;
    private BuildConfig buildConfig;

    private NodeMap<HIRBlock> nodeToBlock;
    private HIRBlock[] reversePostOrder;
    private List<Loop<HIRBlock>> loops;
    private int maxDominatorDepth;
    private EconomicMap<LoopBeginNode, LoopFrequencyData> localLoopFrequencyData;

    public interface RecursiveVisitor<V> {
        V enter(HIRBlock b);

        void exit(HIRBlock b, V value);
    }

    private static final MemUseTrackerKey CFG_MEMORY = DebugContext.memUseTracker("CFGComputation");

    public static ControlFlowGraphBuilder newBuilder(StructuredGraph structuredGraph) {
        return new ControlFlowGraphBuilder(structuredGraph);
    }

    public static ControlFlowGraph computeForSchedule(StructuredGraph graph) {
        return compute(graph, true, true, true, true, true, false);
    }

    /**
     * Creates a control flow graph from the nodes in {@code graph}.
     *
     * @param backendBlocks specifies if the blocks can have their edges edited
     * @param connectBlocks
     * @param computeFrequency
     * @param computeLoops
     * @param computeDominators
     * @param computePostdominators
     */
    @SuppressWarnings("try")
    static ControlFlowGraph compute(StructuredGraph graph, boolean backendBlocks, boolean connectBlocks, boolean computeFrequency, boolean computeLoops, boolean computeDominators,
                    boolean computePostdominators) {
        ControlFlowGraph lastCFG = graph.getLastCFG();

        try (DebugCloseable c = CFG_MEMORY.start(graph.getDebug())) {
            ControlFlowGraph cfg;
            if (lastCFG != null && graph.isLastCFGValid() && (lastCFG.buildConfig.backendBlocks == backendBlocks)) {
                if (lastCFG.buildConfig.hasAllParams(backendBlocks, connectBlocks, computeFrequency, computeLoops, computeDominators, computePostdominators)) {
                    return lastCFG;
                }
                cfg = lastCFG;
            } else {
                cfg = new ControlFlowGraph(graph);
            }

            if (cfg != lastCFG) {
                cfg.identifyBlocks(backendBlocks);
            }

            boolean loopInfoComputed = false;
            if (CFGOptions.DumpEndVersusExitLoopFrequencies.getValue(graph.getOptions())) {
                // additional loop info for sink frequencies inside the loop body
                if (!cfg.buildConfig.computeLoops) {
                    cfg.computeLoopInformation();
                }
                if (!cfg.buildConfig.computeDominators) {
                    cfg.computeDominators();
                }
                loopInfoComputed = true;
            }

            if (computeFrequency && !cfg.buildConfig.computeFrequency) {
                cfg.computeFrequencies();
            }

            if (computeLoops && !loopInfoComputed && !cfg.buildConfig.computeLoops) {
                cfg.computeLoopInformation();
            }
            if (computeDominators && !loopInfoComputed && !cfg.buildConfig.computeDominators) {
                cfg.computeDominators();
                assert cfg.verifyRPOInnerLoopsFirst();
            }
            if (computePostdominators && !cfg.buildConfig.computePostdominators) {
                cfg.computePostdominators();
            }

            // there's not much to verify when connectBlocks == false
            assert !(connectBlocks || computeLoops || computeDominators || computePostdominators) || CFGVerifier.verify(cfg);
            cfg.buildConfig.update(backendBlocks, connectBlocks, computeFrequency, computeLoops | loopInfoComputed, computeDominators | loopInfoComputed, computePostdominators);
            graph.setLastCFG(cfg);
            return cfg;
        }
    }

    private boolean notWeakerThan(boolean computeDominators, boolean loopInfoComputed, ControlFlowGraph cfg) {
        return computeDominators && !loopInfoComputed && !cfg.buildConfig.computeDominators;
    }

    private static class BuildConfig {
        private boolean backendBlocks = false;
        private boolean connectBlocks = false;
        private boolean computeFrequency = false;
        private boolean computeLoops = false;
        private boolean computeDominators = false;
        private boolean computePostdominators = false;

        @SuppressWarnings("hiding")
        public void update(boolean backendBlocks, boolean connectBlocks, boolean computeFrequency, boolean computeLoops, boolean computeDominators, boolean computePostdominators) {
            this.backendBlocks |= backendBlocks;
            this.connectBlocks |= connectBlocks;
            this.computeFrequency |= computeFrequency;
            this.computeLoops |= computeLoops;
            this.computeDominators |= computeDominators;
            this.computePostdominators |= computePostdominators;
        }

        /**
         * Checks that this build configuration is not weaker than a build configuration from the
         * provided parameters. That is, if for each parameter p the following holds:
         * {@code (p -> this.p)} which is equivalent to {@code (!p || this.p)}.
         */
        @SuppressWarnings("hiding")
        public boolean hasAllParams(boolean backendBlocks, boolean connectBlocks, boolean computeFrequency, boolean computeLoops, boolean computeDominators, boolean computePostdominators) {
            return (this.backendBlocks || !backendBlocks) && (this.connectBlocks || !connectBlocks) && (this.computeFrequency || !computeFrequency) && (this.computeLoops || !computeLoops) &&
                            (this.computeDominators || !computeDominators) && (this.computePostdominators || !computePostdominators);
        }
    }

    private void identifyBlocks(boolean makeEditable) {
        int numBlocks = 0;
        for (AbstractBeginNode begin : graph.getNodes(AbstractBeginNode.TYPE)) {
            GraalError.guarantee(begin.predecessor() != null || (begin instanceof StartNode || begin instanceof AbstractMergeNode), "Disconnected control flow %s encountered", begin);
            HIRBlock block = makeEditable ? new HIRBlock.ModifiableBlock(begin, this) : new HIRBlock.UnmodifiableBlock(begin, this);
            identifyBlock(block);
            numBlocks++;
            if (numBlocks > AbstractControlFlowGraph.LAST_VALID_BLOCK_INDEX) {
                throw new RetryableBailoutException("Graph too large to safely compile in reasonable time. Graph contains more than %d basic blocks",
                                AbstractControlFlowGraph.LAST_VALID_BLOCK_INDEX);
            }
        }
        reversePostOrder = ReversePostOrder.identifyBlocks(this, numBlocks);
    }

    public double localLoopFrequency(LoopBeginNode lb) {
        return localLoopFrequencyData.get(lb).getLoopFrequency();
    }

    public ProfileSource localLoopFrequencySource(LoopBeginNode lb) {
        return localLoopFrequencyData.get(lb).getProfileSource();
    }

    public EconomicMap<LoopBeginNode, LoopFrequencyData> getLocalLoopFrequencyData() {
        return localLoopFrequencyData;
    }

    /**
     * Update the cached local loop frequency for the given loop. Future queries of
     * {@link #localLoopFrequency(LoopBeginNode)} on <em>this</em> {@link ControlFlowGraph} instance
     * will return the updated value. This is useful for phases to record temporary effects of
     * transformations on loop frequencies, without having to recompute a CFG.
     * </p>
     *
     * The updated frequency is a cached value local to this CFG. It is <em>not</em> persisted in
     * the IR graph. Newly computed {@link ControlFlowGraph} instances will recompute a frequency
     * from loop exit probabilities, they will not see this locally cached value. Persistent changes
     * to loop frequencies must be modeled by changing loop exit probabilities in the graph.
     */
    public void updateCachedLocalLoopFrequency(LoopBeginNode lb, Function<LoopFrequencyData, LoopFrequencyData> updater) {
        localLoopFrequencyData.put(lb, updater.apply(localLoopFrequencyData.get(lb)));
    }

    /**
     * Debug only decorator for {@link RecursiveVisitor} to log all basic blocks how they are
     * visited one by one.
     */
    public static class LoggingCFGDecorator implements ControlFlowGraph.RecursiveVisitor<HIRBlock> {
        private final ControlFlowGraph.RecursiveVisitor<HIRBlock> visitor;
        private String indent = "";

        public LoggingCFGDecorator(ControlFlowGraph.RecursiveVisitor<HIRBlock> visitor, ControlFlowGraph cfg) {
            this.visitor = visitor;
            TTY.printf("DomTree for %s%n", cfg.graph);
            printDomTree(cfg.getStartBlock(), "");
        }

        private static void printDomTree(HIRBlock cur, String indent) {
            TTY.printf("%s%s [dom %s, post dom %s]%n", indent, cur, cur.getDominator(), cur.getPostdominator());
            HIRBlock dominated = cur.getFirstDominated();
            while (dominated != null) {
                printDomTree(dominated, indent + "\t");
                dominated = dominated.getDominatedSibling();
            }
        }

        @Override
        public HIRBlock enter(HIRBlock b) {
            TTY.printf("%sEnter block %s for %s%n", indent, b, visitor);
            indent += "\t";
            return visitor.enter(b);
        }

        @Override
        public void exit(HIRBlock b, HIRBlock value) {
            indent = indent.substring(0, indent.length() - 1);
            TTY.printf("%sExit block %s with value %s for %s%n", indent, b, value, visitor);
            visitor.exit(b, value);
        }
    }

    @SuppressWarnings("unchecked")
    public <V> void visitDominatorTreeDefault(RecursiveVisitor<V> visitor) {

        HIRBlock[] stack = new HIRBlock[maxDominatorDepth + 1];
        HIRBlock current = getStartBlock();
        int tos = 0;
        Object[] values = null;
        int valuesTOS = 0;

        while (tos >= 0) {
            HIRBlock state = stack[tos];
            if (state == null || state.getDominator() == null || state.getDominator().getPostdominator() != state) {
                if (state == null) {
                    // We enter this block for the first time.
                    V value = visitor.enter(current);
                    if (value != null || values != null) {
                        if (values == null) {
                            values = new Object[maxDominatorDepth + 1];
                        }
                        values[valuesTOS++] = value;
                    }

                    HIRBlock dominated = skipPostDom(current.getFirstDominated());
                    if (dominated != null) {
                        // Descend into dominated.
                        stack[tos] = dominated;
                        current = dominated;
                        stack[++tos] = null;
                        continue;
                    }
                } else {
                    HIRBlock next = skipPostDom(state.getDominatedSibling());
                    if (next != null) {
                        // Descend into dominated.
                        stack[tos] = next;
                        current = next;
                        stack[++tos] = null;
                        continue;
                    }
                }

                // Finished processing all normal dominators.
                HIRBlock postDom = current.getPostdominator();
                if (postDom != null && postDom.getDominator() == current) {
                    // Descend into post dominator.
                    stack[tos] = postDom;
                    current = postDom;
                    stack[++tos] = null;
                    continue;
                }
            }

            // Finished processing this node, exit and pop from stack.
            V value = null;
            if (values != null && valuesTOS > 0) {
                value = (V) values[--valuesTOS];
            }
            visitor.exit(current, value);
            current = current.getDominator();
            --tos;
        }
    }

    private static HIRBlock skipPostDom(HIRBlock block) {
        if (block != null && block.getDominator().getPostdominator() == block) {
            // This is an always reached block.
            return block.getDominatedSibling();
        }
        return block;
    }

    public static final class DeferredExit {

        public DeferredExit(HIRBlock block, DeferredExit next) {
            this.block = block;
            this.next = next;
        }

        private final HIRBlock block;
        private final DeferredExit next;
    }

    public static void addDeferredExit(DeferredExit[] deferredExits, HIRBlock b) {
        Loop<HIRBlock> outermostExited = b.getDominator().getLoop();
        Loop<HIRBlock> exitBlockLoop = b.getLoop();
        assert outermostExited != null : "Dominator must be in a loop. Possible cause is a missing loop exit node.";
        while (outermostExited.getParent() != null && outermostExited.getParent() != exitBlockLoop) {
            outermostExited = outermostExited.getParent();
        }
        int loopIndex = outermostExited.getIndex();
        deferredExits[loopIndex] = new DeferredExit(b, deferredExits[loopIndex]);
    }

    @SuppressWarnings({"unchecked"})
    public <V> void visitDominatorTreeDeferLoopExits(RecursiveVisitor<V> visitor) {
        HIRBlock[] stack = new HIRBlock[getBlocks().length];
        int tos = 0;
        BasicBlockSet visited = this.createBasicBlockSet();
        int loopCount = getLoops().size();
        DeferredExit[] deferredExits = new DeferredExit[loopCount];
        Object[] values = null;
        int valuesTOS = 0;
        stack[0] = getStartBlock();
        List<HIRBlock> dominated = new ArrayList<>(3);

        while (tos >= 0) {
            HIRBlock cur = stack[tos];
            if (visited.get(cur)) {
                V value = null;
                if (values != null && valuesTOS > 0) {
                    value = (V) values[--valuesTOS];
                }
                visitor.exit(cur, value);
                --tos;
                if (cur.isLoopHeader()) {
                    int loopIndex = cur.getLoop().getIndex();
                    DeferredExit deferredExit = deferredExits[loopIndex];
                    if (deferredExit != null) {
                        while (deferredExit != null) {
                            stack[++tos] = deferredExit.block;
                            deferredExit = deferredExit.next;
                        }
                        deferredExits[loopIndex] = null;
                    }
                }
            } else {
                visited.set(cur);
                V value = visitor.enter(cur);
                if (value != null || values != null) {
                    if (values == null) {
                        values = new Object[maxDominatorDepth + 1];
                    }
                    values[valuesTOS++] = value;
                }

                HIRBlock alwaysReached = cur.getPostdominator();
                if (alwaysReached != null) {
                    if (alwaysReached.getDominator() != cur) {
                        alwaysReached = null;
                    } else if (isDominatorTreeLoopExit(alwaysReached)) {
                        addDeferredExit(deferredExits, alwaysReached);
                    } else {
                        stack[++tos] = alwaysReached;
                    }
                }

                dominated.clear();

                HIRBlock b = cur.getFirstDominated();
                while (b != null) {
                    dominated.add(b);
                    b = b.getDominatedSibling();
                }

                /*
                 * Push dominated blocks to stack in reverse order, to make sure that branches are
                 * handled before merges. This facilitates phi optimizations.
                 */
                while (!dominated.isEmpty()) {
                    b = dominated.removeLast();
                    if (b != alwaysReached) {
                        if (isDominatorTreeLoopExit(b)) {
                            addDeferredExit(deferredExits, b);
                        } else {
                            stack[++tos] = b;
                        }
                    }
                }
            }
        }
    }

    public <V> void visitDominatorTree(RecursiveVisitor<V> visitor, boolean deferLoopExits) {
        if (deferLoopExits && this.getLoops().size() > 0) {
            visitDominatorTreeDeferLoopExits(visitor);
        } else {
            visitDominatorTreeDefault(visitor);
        }
    }

    public static boolean isDominatorTreeLoopExit(HIRBlock b) {
        return isDominatorTreeLoopExit(b, false);
    }

    public static boolean isDominatorTreeLoopExit(HIRBlock b, boolean considerRealExits) {
        HIRBlock dominator = b.getDominator();
        if (dominator != null && b.getLoop() != dominator.getLoop() && (!b.isLoopHeader() || dominator.getLoopDepth() >= b.getLoopDepth())) {
            return true;
        }
        if (considerRealExits) {
            if (b.getBeginNode() instanceof LoopExitNode) {
                return true;
            }
        }
        return false;
    }

    private ControlFlowGraph(StructuredGraph graph) {
        this.graph = graph;
        this.nodeToBlock = graph.createNodeMap();
        this.buildConfig = new BuildConfig();
    }

    /**
     * Utility class to verify that {@link ReversePostOrder} only produces reverse post order
     * traversals of the graph that contain inner loops before outer ones.
     */
    private static class RPOLoopVerification {
        int endsVisited;
        int exitsVisited;
        LoopBeginNode lb;

        RPOLoopVerification(LoopBeginNode lb) {
            this.lb = lb;
        }

        boolean loopFullyProcessed() {
            return lb.getLoopEndCount() == endsVisited && exitsVisited == lb.loopExits().count();
        }

        boolean allEndsVisited() {
            return lb.getLoopEndCount() == endsVisited;
        }

    }

    /**
     * Verification method to ensure that inner loops are processed before outer ones: see
     * {@link ControlFlowGraph#computeFrequencies()} for details.
     */
    private boolean verifyRPOInnerLoopsFirst() {
        return rpoInnerLoopsFirst(b -> {
        }, b -> {
        });
    }

    /**
     * Special note on loop exit nodes and dominator tree loop exits: Graal has a "closed" loop
     * form, this means every {@link LoopBeginNode} needs explicit {@link LoopEndNode} nodes and (if
     * it is not an endless loop) {@link LoopExitNode}. For every path exiting a loop a
     * {@link LoopExitNode} is required. There is one exception to that rule:
     * {@link DeoptimizeNode}.
     *
     * Graal does not mandate that a {@link DeoptimizeNode} is preceded by a {@link LoopExitNode}.
     * In the following example
     *
     * <pre>
     * for (int i = 0; i < end; i++) {
     *     if (condition) {
     *         deoptimize;
     *     }
     * }
     * </pre>
     *
     * the IR does not have a preceding loop exit node before the deopt node. However, for regular
     * control flow sinks (returns, throws, etc) like in the following example
     *
     * <pre>
     * for (int i = 0; i < end; i++) {
     *     if (condition) {
     *         return;
     *     }
     * }
     * </pre>
     *
     * Graal IR creates a {@link LoopExitNode} before the {@link ReturnNode}.
     *
     * Because of the "imprecision" in the definition a regular basic block exiting a loop and a
     * "dominator tree" loop exit are not necessarily the same. If a path after a control flow split
     * unconditionally flows into a deopt it is a "dominator loop exit" while a regular loop exit
     * block contains a {@linkplain LoopExitNode}.
     */
    private boolean rpoInnerLoopsFirst(Consumer<HIRBlock> perBasicBlockOption, Consumer<LoopBeginNode> loopClosedAction) {
        // worst case all loops in the graph are nested
        RPOLoopVerification[] openLoops = new RPOLoopVerification[graph.getNodes(LoopBeginNode.TYPE).count()];
        int tos = 0;
        for (HIRBlock b : reversePostOrder) {
            // we see a loop end, open a new verification level in the loop stack
            if (b.isLoopHeader()) {
                RPOLoopVerification lv = new RPOLoopVerification((LoopBeginNode) b.getBeginNode());
                openLoops[tos++] = lv;
            }

            // process this basic block
            perBasicBlockOption.accept(b);

            /*
             * General note on the verification of loop exits: A loop exit node and a dominator tree
             * loop exit are not necessarily the same, see javadoc of this method. Ideally, we would
             * like to visit all dominator loop exits during RPO verification, however we do not
             * know how many there are (given the deopt issue above), thus we just determine by the
             * loop exit nodes seen.
             */
            boolean wasExit = predecessorBlockSequentialLoopExit(b);

            FixedNode f = b.getBeginNode();
            while (true) { // TERMINATION ARGUMENT: processing loop exit node predecessors
                CompilationAlarm.checkProgress(graph);
                if (f instanceof LoopExitNode) {
                    LoopBeginNode closedLoop = ((LoopExitNode) f).loopBegin();
                    RPOLoopVerification lv = openLoops[tos - 1];
                    assert lv.lb == closedLoop : "Must close inner loops first before closing other ones stackLoop=" + lv.lb + " exited loop=" + closedLoop + " block=" + b;
                    if (!lv.allEndsVisited()) {
                        throw GraalError.shouldNotReachHere(
                                        "Loop ends should be visited before exits. This is a major error in the reverse post order of the control " +
                                                        "flow graph of this method. This typically means wrongly specified control-split nodes have been processed in ReversePostOrder.java."); // ExcludeFromJacocoGeneratedReport
                    }
                    lv.exitsVisited++;
                    if (lv.loopFullyProcessed()) {
                        loopClosedAction.accept(lv.lb);
                        tos--;
                    }
                    wasExit = true;
                }
                if (f == b.getEndNode()) {
                    break;
                }
                f = ((FixedWithNextNode) f).next();
            }

            if (b.isLoopEnd()) {
                RPOLoopVerification lv = null;
                LoopEndNode len = (LoopEndNode) b.getEndNode();
                int index = tos - 1;
                if (wasExit) {
                    // irregular case a basic block that is a loop exit to an inner loop followed by
                    // a loop end to an outer loop, while the inner loop potentially is not
                    // finished, we still need to allow such cases since the code in the fraction
                    // between loop exit inner and end outer is fine, it does not change the
                    // verification logic since its a single basic block
                    while (openLoops[index].lb != len.loopBegin()) {
                        index--;
                    }
                    lv = openLoops[index];
                } else {
                    // regular case, this block contains a loop end to the inner most loop
                    lv = openLoops[tos - 1];
                }
                LoopBeginNode closedLoop = ((LoopEndNode) b.getEndNode()).loopBegin();
                assert lv.lb == closedLoop : "Must close inner loops first before closing other ones stackLoop=" + lv.lb + " ended loop=" + closedLoop + " block=" + b + "->" + b.getBeginNode();
                lv.endsVisited++;
                if (lv.loopFullyProcessed()) {
                    loopClosedAction.accept(lv.lb);
                    // the current loop was exited but we also end an outer loop, find this one and
                    // remove it from the verification stack since its done
                    if (lv.lb != openLoops[tos - 1].lb) {
                        // we actually finished the outer loop already completely through this
                        // exit-end scenario, remove it from the stack
                        RPOLoopVerification[] tmp = new RPOLoopVerification[openLoops.length];
                        System.arraycopy(openLoops, 0, tmp, 0, index);
                        System.arraycopy(openLoops, index + 1, tmp, index, openLoops.length - (index + 1));
                        openLoops = tmp;
                    }
                    tos--;
                }
            }
        }
        assert tos == 0 : "Unfinished loops on stack " + tos;
        return true;
    }

    /**
     * Determine if sequential predecessor blocks of this block in a not-fully-canonicalized graph
     * exit a loop.
     *
     * Example: Sequential basic block: loop exit -> invoke -> killing begin -> loopend/exit
     *
     * These cases cause problems in the {@link #verifyRPOInnerLoopsFirst()} loop verification of
     * inner loop blocks because the granularity of loop ends and exits are not on block boundaries:
     * a loop exit block can also be a loop end to an outer loop, which makes verification that the
     * inner loop is fully processed before we process the rest of the outer loop tricky (since we
     * already visit a loop end to an outer loop while we should first stricly process all loop
     * ends/exits of inner loops).
     */
    private static boolean predecessorBlockSequentialLoopExit(HIRBlock b) {
        HIRBlock cur = b;
        // while cur has a single predecessor which has a single successor which is cur, i.e., a
        // sequential successor, this typically only happens in not-fully-canonicalized graphs
        while (cur.getPredecessorCount() == 1 && cur.getPredecessorAt(0).getSuccessorCount() == 1) {
            HIRBlock pred = cur.getPredecessorAt(0);
            FixedNode f = pred.getBeginNode();
            while (true) { // TERMINATION ARGUMENT: process loop exit predecessor nodes
                CompilationAlarm.checkProgress(b.getCfg().graph);
                if (f instanceof LoopExitNode) {
                    return true;
                }
                if (f == pred.getEndNode()) {
                    break;
                }
                f = ((FixedWithNextNode) f).next();
            }
            cur = cur.getPredecessorAt(0);
        }
        return false;
    }

    private void computeDominators() {
        assert reversePostOrder[0].getPredecessorCount() == 0 : "start block has no predecessor and therefore no dominator";
        HIRBlock[] blocks = reversePostOrder;
        int curMaxDominatorDepth = 0;
        for (int i = 1; i < blocks.length; i++) {
            HIRBlock block = blocks[i];
            assert NumUtil.assertPositiveInt(block.getPredecessorCount());
            HIRBlock dominator = null;
            for (int j = 0; j < block.getPredecessorCount(); j++) {
                HIRBlock pred = block.getPredecessorAt(j);
                if (!pred.isLoopEnd()) {
                    dominator = ((dominator == null) ? pred : commonDominatorRaw(dominator, pred));
                }
            }
            // Fortify: Suppress Null Dereference false positive (every block apart from the first
            // is guaranteed to have a predecessor)
            assert dominator != null;

            // Set dominator.
            block.setDominator(dominator);

            // Keep dominated linked list sorted by block ID such that predecessor blocks are always
            // before successor blocks.
            HIRBlock currentDominated = dominator.getFirstDominated();
            if (currentDominated != null && currentDominated.getId() < block.getId()) {
                while (currentDominated.getDominatedSibling() != null && currentDominated.getDominatedSibling().getId() < block.getId()) {
                    currentDominated = currentDominated.getDominatedSibling();
                }
                block.setDominatedSibling(currentDominated.getDominatedSibling());
                currentDominated.setDominatedSibling(block);
            } else {
                block.setDominatedSibling(dominator.getFirstDominated());
                dominator.setFirstDominated(block);
            }

            curMaxDominatorDepth = Math.max(curMaxDominatorDepth, block.getDominatorDepth());
        }
        this.maxDominatorDepth = curMaxDominatorDepth;
        calcDominatorRanges(getStartBlock(), reversePostOrder.length);
    }

    private static void calcDominatorRanges(HIRBlock block, int size) {
        HIRBlock[] stack = new HIRBlock[size];
        stack[0] = block;
        int tos = 0;
        int myNumber = 0;

        do {
            HIRBlock cur = stack[tos];
            HIRBlock dominated = cur.getFirstDominated();

            if (cur.getDominatorNumber() == -1) {
                cur.setDominatorNumber(myNumber);
                if (dominated != null) {
                    // Push children onto stack.
                    do {
                        stack[++tos] = dominated;
                        dominated = dominated.getDominatedSibling();
                    } while (dominated != null);
                } else {
                    cur.setMaxChildDomNumber(myNumber);
                    --tos;
                }
                myNumber = myNumber + 1;
            } else {
                cur.setMaxChildDomNumber(dominated.getMaxChildDominatorNumber());
                --tos;
            }
        } while (tos >= 0);
    }

    private static HIRBlock commonDominatorRaw(HIRBlock a, HIRBlock b) {
        int aDomDepth = a.getDominatorDepth();
        int bDomDepth = b.getDominatorDepth();
        if (aDomDepth > bDomDepth) {
            return commonDominatorRawSameDepth(a.getDominator(aDomDepth - bDomDepth), b);
        } else {
            return commonDominatorRawSameDepth(a, b.getDominator(bDomDepth - aDomDepth));
        }
    }

    private static HIRBlock commonDominatorRawSameDepth(HIRBlock a, HIRBlock b) {
        HIRBlock iterA = a;
        HIRBlock iterB = b;
        while (iterA != iterB) {
            iterA = iterA.getDominator();
            iterB = iterB.getDominator();
        }
        return iterA;
    }

