    public HIRBlock commonDominatorFor(NodeIterable<? extends Node> nodes) {
        HIRBlock commonDom = null;
        for (Node n : nodes) {
            HIRBlock b = blockFor(n);
            commonDom = (HIRBlock) AbstractControlFlowGraph.commonDominator(commonDom, b);
        }
        return commonDom;
