     * See {@link JVM#setThreshold}.
     */
    public boolean setThreshold(long eventTypeId, long ticks) {
        eventSettings[NumUtil.safeToInt(eventTypeId)].setThresholdTicks(ticks);
        return true;
    }

    @Uninterruptible(reason = "Called from uninterruptible code.", mayBeInlined = true)
    long getThresholdTicks(JfrEvent event) {
        return eventSettings[(int) event.getId()].getThresholdTicks();
    }

    /**
     * See {@link JVM#setCutoff}.
     */
    public boolean setCutoff(long eventTypeId, long cutoffTicks) {
        eventSettings[NumUtil.safeToInt(eventTypeId)].setCutoffTicks(cutoffTicks);
        return true;
    }

    public boolean setConfiguration(Class<? extends Event> eventClass, Object configuration) {
        DynamicHub.fromClass(eventClass).setJrfEventConfiguration(configuration);
        return true;
    }

    public Object getConfiguration(Class<? extends Event> eventClass) {
        return DynamicHub.fromClass(eventClass).getJfrEventConfiguration();
    }

    private static class JfrBeginRecordingOperation extends JavaVMOperation {
        JfrBeginRecordingOperation() {
            super(VMOperationInfos.get(JfrBeginRecordingOperation.class, "JFR begin recording", SystemEffect.SAFEPOINT));
        }

        @Override
        protected void operate() {
            SubstrateJVM.getOldObjectProfiler().reset();
            JfrAllocationEvents.reset();

            SubstrateJVM.get().recording = true;
            /* Recording is enabled, so JFR events can be triggered at any time. */
            SubstrateJVM.getThreadRepo().registerRunningThreads();

            JfrExecutionSampler.singleton().update();
        }
    }

    public static class JfrEndRecordingOperation extends JavaVMOperation {
        JfrEndRecordingOperation() {
            super(VMOperationInfos.get(JfrEndRecordingOperation.class, "JFR end recording", SystemEffect.SAFEPOINT));
        }

        /**
         * When the safepoint ends, it is guaranteed that all {@link JfrNativeEventWriter}s finished
         * their job and that no further JFR events will be triggered. It is also guaranteed that no
         * thread executes any code related to the execution sampling.
         */
        @Override
        protected void operate() {
            SubstrateJVM.get().recording = false;
            JfrExecutionSampler.singleton().update();

            if (SubstrateSigprofHandler.Options.JfrBasedExecutionSamplerStatistics.getValue()) {
                printSamplerStatistics();
            }

            /* No further JFR events are emitted, so free some JFR-related buffers. */
            for (IsolateThread isolateThread = VMThreads.firstThread(); isolateThread.isNonNull(); isolateThread = VMThreads.nextThread(isolateThread)) {
                JfrThreadLocal.stopRecording(isolateThread, false);
            }

            /* Process any remaining full buffers (if there are any). */
            SamplerBuffersAccess.processFullBuffers(false);

            /*
             * If JFR recording is restarted later on, then it needs to start with a clean state.
             * Therefore, we clear all data that is still pending.
             */
            SubstrateJVM.getThreadLocal().teardown();
            SubstrateJVM.getSamplerBufferPool().teardown();
            SubstrateJVM.getGlobalMemory().clear();
            SubstrateJVM.getOldObjectProfiler().teardown();
        }
    }

    private static void printSamplerStatistics() {
        long missedSamples = SamplerStatistics.singleton().getMissedSamples();
        long unparseableStacks = SamplerStatistics.singleton().getUnparseableSamples();
        for (IsolateThread isolateThread = VMThreads.firstThread(); isolateThread.isNonNull(); isolateThread = VMThreads.nextThread(isolateThread)) {
            missedSamples += JfrThreadLocal.getMissedSamples(isolateThread);
            unparseableStacks += JfrThreadLocal.getUnparseableStacks(isolateThread);
        }

        Log log = Log.log();
        log.string("JFR sampler statistics").indent(true);
        log.string("Missed samples: ").unsigned(missedSamples).newline();
        log.string("Unparseable stacks: ").unsigned(unparseableStacks).indent(false);
    }

    private class JfrTeardownOperation extends JavaVMOperation {
        JfrTeardownOperation() {
            super(VMOperationInfos.get(JfrTeardownOperation.class, "JFR teardown", SystemEffect.SAFEPOINT));
        }

        @Override
        protected void operate() {
            if (!initialized) {
                return;
            }

            globalMemory.teardown();
            symbolRepo.teardown();
            threadRepo.teardown();
            stackTraceRepo.teardown();
            methodRepo.teardown();
            typeRepo.teardown();
            oldObjectRepo.teardown();

            initialized = false;
        }
    }
}

@AutomaticallyRegisteredFeature
public class DashboardDumpFeature implements InternalFeature {

    private static boolean isHeapBreakdownDumped() {
        return DashboardOptions.DashboardAll.getValue() || DashboardOptions.DashboardHeap.getValue();
    }

    private static boolean isPointsToDumped() {
        return DashboardOptions.DashboardAll.getValue() || DashboardOptions.DashboardPointsTo.getValue();
    }

    private static boolean isCodeBreakdownDumped() {
        return DashboardOptions.DashboardAll.getValue() || DashboardOptions.DashboardCode.getValue();
    }

    private static boolean isBgvFormat() {
        return DashboardOptions.DashboardBgv.getValue();
    }

    private static boolean isJsonFormat() {
        return DashboardOptions.DashboardJson.getValue() || isPretty();
    }

    private static boolean isPretty() {
        return DashboardOptions.DashboardPretty.getValue();
    }

    private static Path getFile(String extension) {
        String fileName = DashboardOptions.DashboardDump.getValue();
        if (fileName == null) {
            fileName = SubstrateOptions.Name.getValue(); // Use image name by default.
        }
        return new File(fileName + "." + extension).getAbsoluteFile().toPath();
    }

    private StringWriter jsonOutput = null;
    private JsonWriter jsonWriter = null;
    private JsonBuilder.ObjectBuilder objectBuilder = null;

    public DashboardDumpFeature() {
        if (isSane()) {
            if (isJsonFormat()) {
                jsonOutput = new StringWriter();
                jsonWriter = isPretty() ? new JsonPrettyWriter(jsonOutput) : new JsonWriter(jsonOutput);
                try {
                    objectBuilder = jsonWriter.objectBuilder();
                } catch (IOException ex) {
                    System.getLogger(DashboardDumpFeature.class.getName()).log(Level.ERROR, "IOException during Dashboard json dump header", ex);
                }
                ReportUtils.report("Dashboard JSON dump header", getFile("dump"), false, os -> {
                });
            }
            if (isBgvFormat()) {
                ReportUtils.report("Dashboard BGV dump header", getFile("bgv"), false, os -> {
                    try {
                        GraphOutput.newBuilder(VoidGraphStructure.INSTANCE).build(Channels.newChannel(os)).close();
                    } catch (IOException ex) {
                        System.getLogger(DashboardDumpFeature.class.getName()).log(Level.ERROR, "IOException during Dashboard BGV dump header", ex);
                    }
                });
            }
        }
    }

    @Override
    public boolean isInConfiguration(IsInConfigurationAccess access) {
        return isSane();
    }

    private static boolean isSane() {
        return isHeapBreakdownDumped() || isPointsToDumped() || isCodeBreakdownDumped();
    }

    @Override
    public void onAnalysisExit(OnAnalysisExitAccess access) {
        if (isPointsToDumped()) {
            PointsToBreakdown pointsTo = new PointsToBreakdown(access);
            if (isJsonFormat()) {
                ReportUtils.report(
                                "Dashboard PointsTo analysis JSON dump",
                                getFile("dump"),
                                true,
                                os -> {
                                    try {
                                        try (JsonBuilder.ObjectBuilder builder = objectBuilder.append("points-to").object()) {
                                            pointsTo.toJson(builder);
                                        }
                                    } catch (IOException ex) {
                                        ((AfterCompilationAccessImpl) access).getDebugContext().log("Dump of PointsTo analysis failed with: %s", ex);
                                    }
                                });
            }
            if (isBgvFormat()) {
                ReportUtils.report(
                                "Dashboard PointsTo analysis BGV dump",
                                getFile("bgv"),
                                true,
                                os -> {
                                    try (GraphOutput<?, ?> out = GraphOutput.newBuilder(VoidGraphStructure.INSTANCE).embedded(true).build(Channels.newChannel(os))) {
                                        out.beginGroup(null, "points-to", null, null, 0, Collections.emptyMap());
                                        pointsTo.dump(out);
                                        out.endGroup();
                                    } catch (IOException ex) {
                                        ((OnAnalysisExitAccessImpl) access).getDebugContext().log("Dump of PointsTo analysis failed with: %s", ex);
                                    }
                                });
            }
        }
    }


    @Override
    public void afterCompilation(AfterCompilationAccess access) {
        if (isCodeBreakdownDumped() || isPointsToDumped()) {
            CodeBreakdown dump = new CodeBreakdown(access);
            if (isJsonFormat()) {
                ReportUtils.report(
                                "Dashboard Code-Breakdown JSON dump",
                                getFile("dump"),
                                true,
                                os -> {
                                    try (JsonBuilder.ObjectBuilder builder = objectBuilder.append("code-breakdown").object()) {
                                        dump.build();
                                        try (JsonBuilder.ArrayBuilder array = builder.append("code-size").array()) {
                                            for (Map.Entry<String, Integer> entry : dump.getData().entrySet()) {
                                                try (JsonBuilder.ObjectBuilder object = array.nextEntry().object()) {
                                                    object
                                                            .append("name", entry.getKey())
                                                            .append("size", entry.getValue());
                                                }
                                            }
                                        }
                                    } catch (IOException ex) {
                                        ((AfterCompilationAccessImpl) access).getDebugContext().log("Dump of Code-Breakdown failed with: %s", ex);
                                    }
                                });
            }
            if (isBgvFormat()) {
                ReportUtils.report(
                                "Dashboard Code-Breakdown BGV dump",
                                getFile("bgv"),
                                true,
                                os -> {
                                    try (GraphOutput<?, ?> out = GraphOutput.newBuilder(VoidGraphStructure.INSTANCE).embedded(true).build(Channels.newChannel(os))) {
                                        out.beginGroup(null, "code-breakdown", null, null, 0, dump.getData());
                                        out.endGroup();
                                    } catch (IOException ex) {
                                        ((AfterCompilationAccessImpl) access).getDebugContext().log("Dump of Code-Breakdown failed with: %s", ex);
                                    }
                                });
            }
        }
    }

    private void toJson(CodeBreakdown dump, JsonBuilder.ObjectBuilder builder) throws IOException {
        dump.build();
        try (JsonBuilder.ArrayBuilder array = builder.append("code-size").array()) {
            for (Map.Entry<String, Integer> entry : dump.getData().entrySet()) {
                try (JsonBuilder.ObjectBuilder object = array.nextEntry().object()) {
                    object
                            .append("name", entry.getKey())
                            .append("size", entry.getValue());
                }
            }
        }
    }

    @Override
    public void afterHeapLayout(AfterHeapLayoutAccess access) {
        if (isHeapBreakdownDumped()) {
            HeapBreakdown dump = new HeapBreakdown(access);
            if (isJsonFormat()) {
                ReportUtils.report(
                                "Dashboard Heap-Breakdown JSON dump",
                                getFile("dump"),
                                true,
                                os -> {
                                    try (JsonBuilder.ObjectBuilder builder = objectBuilder.append("heap-breakdown").object()) {
                                        dump.toJson(builder);
                                    } catch (IOException ex) {
                                        ((AfterCompilationAccessImpl) access).getDebugContext().log("Dump of Heap-Breakdown failed with: %s", ex);
                                    }
                                });
            }
            if (isBgvFormat()) {
                ReportUtils.report(
                                "Dashboard Heap-Breakdown BGV dump",
                                getFile("bgv"),
                                true,
                                os -> {
                                    try (GraphOutput<?, ?> out = GraphOutput.newBuilder(VoidGraphStructure.INSTANCE).embedded(true).build(Channels.newChannel(os))) {
                                        out.beginGroup(null, "heap-breakdown", null, null, 0, dump.getData());
                                        out.endGroup();
                                    } catch (IOException ex) {
                                        ((AfterHeapLayoutAccessImpl) access).getDebugContext().log("Dump of Heap-Breakdown failed with: %s", ex);
                                    }
                                });
            }
        }
    }

    @Override
    public void cleanup() {
        if (isJsonFormat()) {
            try {
                if (objectBuilder != null) {
                    objectBuilder.close();
                }
                if (jsonWriter != null) {
                    jsonWriter.close();
                }
            } catch (IOException ex) {
                System.getLogger(DashboardDumpFeature.class.getName()).log(Level.ERROR, "IOException during Dashboard json dump end", ex);
            }

            ReportUtils.report("Dashboard JSON dump end", getFile("dump"), true, os -> {
                try (PrintWriter pw = new PrintWriter(os)) {
                    pw.print(jsonOutput.toString());
                }
            });
        }
        System.out.println("Print of Dashboard dump output ended.");
    }

