        return Collections.unmodifiableMap(methodLookupExceptions);
    }

    @Override
    public Map<Class<?>, Throwable> getConstructorLookupErrors() {
        return Collections.unmodifiableMap(constructorLookupExceptions);
    }

    private static final AnnotationValue[] NO_ANNOTATIONS = new AnnotationValue[0];

    public AnnotationValue[] getAnnotationData(AnnotatedElement element) {
        assert sealed;
        return filteredAnnotations.getOrDefault(element, NO_ANNOTATIONS);
    }

    private static final AnnotationValue[][] NO_PARAMETER_ANNOTATIONS = new AnnotationValue[0][0];

    public AnnotationValue[][] getParameterAnnotationData(AnalysisMethod element) {
        assert sealed;
        return filteredParameterAnnotations.getOrDefault(element, NO_PARAMETER_ANNOTATIONS);
    }

    private static final TypeAnnotationValue[] NO_TYPE_ANNOTATIONS = new TypeAnnotationValue[0];

    public TypeAnnotationValue[] getTypeAnnotationData(AnnotatedElement element) {
        assert sealed;
        return filteredTypeAnnotations.getOrDefault(element, NO_TYPE_ANNOTATIONS);
    }

    public AnnotationMemberValue getAnnotationDefaultData(AnnotatedElement element) {
        return annotationExtractor.getAnnotationDefaultData(element);
    }

    @Override
    public int getReflectionMethodsCount() {
        return registeredMethods.size();
    }

    @Override
    public int getReflectionFieldsCount() {
        return registeredFields.size();
    }

    private static void requireNonNull(Object[] values, String kind) {
        for (Object value : values) {
            Objects.requireNonNull(value, () -> nullErrorMessage(kind));
        }
    }

    private static String nullErrorMessage(String kind) {
        return "Cannot register null value as " + kind + " for reflection. Please ensure that all values you register are not null.";
    }

    public static class TestBackdoor {
        public static void registerField(ReflectionDataBuilder reflectionDataBuilder, boolean queriedOnly, Field field) {
            reflectionDataBuilder.runConditionalInAnalysisTask(ConfigurationCondition.alwaysTrue(), (cnd) -> reflectionDataBuilder.registerField(queriedOnly, field));
        }
    }
}

/**
 * Statically analyses bytecodes to produce a {@link EspressoFrameDescriptor frame description} for
 * the given BCI.
 */
public final class FrameAnalysis {
    private final EspressoLanguage lang;
    private final Method.MethodVersion m;

    private final LivenessAnalysis la;
    private final BytecodeStream bs;
    private final ConstantPool pool;
    private final int targetBci;

    private final Builder[] states;
    private final BitSet branchTargets;
    private final BitSet processStatus;

    private final ArrayDeque<Integer> queue = new ArrayDeque<>(2);

    public static EspressoFrameDescriptor apply(Method.MethodVersion m, int bci) {
        return new FrameAnalysis(bci, m).apply();
    }

    private FrameAnalysis(int targetBci, Method.MethodVersion m) {
        this.lang = m.getMethod().getLanguage();
        this.la = m.getLivenessAnalysis();
        this.bs = new BytecodeStream(m.getOriginalCode());
        this.targetBci = targetBci;
        this.states = new Builder[bs.endBCI()];
        this.pool = m.getDeclaringKlass().getLinkedKlass().getParserKlass().getConstantPool();
        this.m = m;
        this.branchTargets = new BitSet(bs.endBCI());
        this.processStatus = new BitSet(bs.endBCI());
    }

    private static void popSignature(Symbol<Type>[] sig, boolean isStatic, Builder frame) {
        for (int i = 0; i < Signatures.parameterCount(sig); i++) {
            JavaKind k = Signatures.parameterKind(sig, i);

            frame.pop();
            if (k.needsTwoSlots()) {
                assert frame.pop() == JavaKind.Illegal;
            }
        }
        if (!isStatic) {
            frame.pop();
        }
    }

    private int pop(Builder frame, JavaKind k) {
        frame.pop();
        if (k.needsTwoSlots()) {
            assert frame.pop() == JavaKind.Illegal;
        }
        return frame.getTop();
    }

    private EspressoFrameDescriptor apply() {
        markBranchTargets();

        buildInitialFrame();
        int startBci = 0;
        push(startBci);

        while (!queue.isEmpty()) {
            startBci = pop();
            buildStates(startBci);
        }

        Builder state = states[targetBci];
        int opcode = bs.opcode(targetBci);
        // For continuations purposes, we need to mutate the state to having popped arguments, but
        // not having yet pushed a result.
        assert Bytecodes.isInvoke(opcode);
        handleInvoke(state, targetBci, opcode, false);
        return state.build();
    }

    private void buildInitialFrame() {
        Builder frame = new Builder(m.getMaxLocals(), m.getMaxStackSize());
        Symbol<Type>[] sig = m.getMethod().getParsedSignature();
        int receiverShift = 0;
        if (!m.isStatic()) {
            frame.putLocal(0, JavaKind.Object);
            receiverShift = 1;
        }
        int localPos = 0;
        for (int sigPos = 0; sigPos < Signatures.parameterCount(sig); sigPos++) {
            JavaKind k = Signatures.parameterKind(sig, sigPos);
            if (k.isStackInt()) {
                k = JavaKind.Int;
            }
            frame.putLocal(receiverShift + localPos, k);
            if (k.needsTwoSlots()) {
                localPos++;
                frame.putLocal(receiverShift + localPos, JavaKind.Illegal);
            }
            localPos++;
        }
        la.onStart(frame);
        frame.setBci(0);
        assert frame.isRecord();
        states[0] = frame;
    }

    private void markBranchTargets() {
        int bci = 0;
        boolean validTarget = false;
        while (bci < bs.endBCI()) {
            int opcode = bs.opcode(bci);
            if (Bytecodes.isBranch(opcode)) {
                branchTargets.set(bs.readBranchDest(bci));
            } else if (opcode == TABLESWITCH || opcode == LOOKUPSWITCH) {
                BytecodeSwitch helper = BytecodeSwitch.get(opcode);
                for (int i = 0; i < helper.numberOfCases(bs, opcode); i++) {
                    branchTargets.set(helper.targetAt(bs, bci, i));
                }
                branchTargets.set(helper.defaultTarget(bs, bci));
            }
            if (bci == targetBci) {
                validTarget = true;
            }
            bci = bs.nextBCI(bci);
        }

        if (!validTarget) {
            Meta meta = m.getDeclaringKlass().getMeta();
            throw meta.throwExceptionWithMessage(meta.java_lang_IllegalArgumentException, "Target bci is not a valid bytecode.");
        }

        ExceptionHandler[] handlers = m.getExceptionHandlers();
        for (ExceptionHandler handler : handlers) {
            branchTargets.set(handler.getHandlerBCI());
        }
    }

    private void buildStates(int startBci) {
        Builder frame = states[startBci].copy();
        int bci = startBci;
        while (bci < bs.endBCI()) {
            if (branchTargets.get(bci)) {
                Builder registered = states[bci];
                assert (registered == null) || frame.sameTop(registered);
                if (merge(bci, frame) && processStatus.get(bci)) {
                    // If already processed, and merge succeeded, we can stop process for this
                    // block.
                    return;
                }
                // Verification is already run, so we know that processing will succeed.
                processStatus.set(bci);
                // keep going with updated frame, as it is be the most precise.
                frame = registered == null ? frame : states[bci].copy();
            }
            if (bci == targetBci) {
                // At this point, the current working frame can only be more precise.
                registerState(bci, frame);
                if (!la.isEmpty()) {
                    // With LA, merging should always succeed.
                    queue.clear();
                    return;
                }
            }
            assert frame.isWorking();
            int opcode = bs.currentBC(bci);
            switch (opcode) {
                case NOP: // fallthrough
                case IINC: // fallthrough
                case CHECKCAST:
                    break;
                case ACONST_NULL, ALOAD, ALOAD_0, ALOAD_1, ALOAD_2, ALOAD_3, NEW:
                    frame.push(JavaKind.Object);
                    break;
                case ICONST_M1, ICONST_0, ICONST_1, ICONST_2, ICONST_3, ICONST_4, ICONST_5: // fallthrough
                case BIPUSH, SIPUSH: // fallthrough
                case ILOAD, ILOAD_0, ILOAD_1, ILOAD_2, ILOAD_3:
                    frame.push(JavaKind.Int);
                    break;
                case LCONST_0, LCONST_1, LLOAD, LLOAD_0, LLOAD_1, LLOAD_2, LLOAD_3:
                    frame.push(JavaKind.Long);
                    break;
                case FCONST_0, FCONST_1, FCONST_2, FLOAD, FLOAD_0, FLOAD_1, FLOAD_2, FLOAD_3:
                    frame.push(JavaKind.Float);
                    break;
                case DCONST_0, DCONST_1, DLOAD, DLOAD_0, DLOAD_1, DLOAD_2, DLOAD_3:
                    frame.push(JavaKind.Double);
                    break;
                case LDC, LDC_W, LDC2_W: {
                    ldc(bci, frame);
                    break;
                }
                case IALOAD, BALOAD, CALOAD, SALOAD: // fallthrough
                case IADD, ISUB, IMUL, IDIV, IREM, ISHL, ISHR, IUSHR, IAND, IOR, IXOR: // fallthrough
                case FCMPL, FCMPG:
                    frame.pop();
                    frame.pop();
                    frame.push(JavaKind.Int);
                    break;
                case LALOAD:
                    frame.pop();
                    frame.pop();
                    frame.push(JavaKind.Long);
                    break;
                case FALOAD, FADD, FSUB, FMUL, FDIV, FREM:
                    frame.pop();
                    frame.pop();
                    frame.push(JavaKind.Float);
                    break;
                case DALOAD:
                    frame.pop();
                    frame.pop();
                    frame.push(JavaKind.Double);
                    break;
                case AALOAD:
                    frame.pop();
                    frame.pop();
                    frame.push(JavaKind.Object);
                    break;
                case ISTORE:
                    frame.pop();
                    frame.putLocal(bs.readLocalIndex(bci), JavaKind.Int);
                    break;
                case LSTORE:
                    frame.pop2();
                    frame.putLocal(bs.readLocalIndex(bci), JavaKind.Long);
                    break;
                case FSTORE:
                    frame.pop();
                    frame.putLocal(bs.readLocalIndex(bci), JavaKind.Float);
                    break;
                case DSTORE:
                    frame.pop2();
                    frame.putLocal(bs.readLocalIndex(bci), JavaKind.Double);
                    break;
                case ASTORE:
                    frame.pop();
                    frame.putLocal(bs.readLocalIndex(bci), JavaKind.Object);
                    break;
                case ISTORE_0, ISTORE_1, ISTORE_2, ISTORE_3:
                    frame.pop();
                    frame.putLocal(opcode - ISTORE_0, JavaKind.Int);
                    break;
                case LSTORE_0, LSTORE_1, LSTORE_2, LSTORE_3:
                    frame.pop2();
                    frame.putLocal(opcode - LSTORE_0, JavaKind.Long);
                    break;
                case FSTORE_0, FSTORE_1, FSTORE_2, FSTORE_3:
                    frame.pop();
                    frame.putLocal(opcode - FSTORE_0, JavaKind.Float);
                    break;
                case DSTORE_0, DSTORE_1, DSTORE_2, DSTORE_3:
                    frame.pop2();
                    frame.putLocal(opcode - DSTORE_0, JavaKind.Double);
                    break;
                case ASTORE_0, ASTORE_1, ASTORE_2, ASTORE_3:
                    frame.pop();
                    frame.putLocal(opcode - ASTORE_0, JavaKind.Object);
                    break;
                case IASTORE, FASTORE, AASTORE, BASTORE, CASTORE, SASTORE:
                    frame.pop();
                    frame.pop();
                    frame.pop();
                    break;
                case LASTORE, DASTORE:
                    frame.pop2();
                    frame.pop();
                    frame.pop();
                    break;
                case POP, MONITORENTER, MONITOREXIT:
                    frame.pop();
                    break;
                case POP2:
                    frame.pop();
                    frame.pop();
                    break;
                case DUP: {
                    JavaKind k = frame.pop();
                    frame.push(k, false);
                    frame.push(k, false);
                    break;
                }
                case DUP_X1: {
                    JavaKind v1 = frame.pop();
                    JavaKind v2 = frame.pop();
                    frame.push(v1, false);
                    frame.push(v2, false);
                    frame.push(v1, false);
                    break;
                }
                case DUP_X2: {
                    JavaKind v1 = frame.pop();
                    JavaKind v2 = frame.pop();
                    JavaKind v3 = frame.pop();
                    frame.push(v1, false);
                    frame.push(v3, false);
                    frame.push(v2, false);
                    frame.push(v1, false);
                    break;
                }
                case DUP2: {
                    JavaKind v1 = frame.pop();
                    JavaKind v2 = frame.pop();
                    frame.push(v2, false);
                    frame.push(v1, false);
                    frame.push(v2, false);
                    frame.push(v1, false);
                    break;
                }
                case DUP2_X1: {
                    JavaKind v1 = frame.pop();
                    JavaKind v2 = frame.pop();
                    JavaKind v3 = frame.pop();
                    frame.push(v2, false);
                    frame.push(v1, false);
                    frame.push(v3, false);
                    frame.push(v2, false);
                    frame.push(v1, false);
                    break;
                }
                case DUP2_X2: {
                    JavaKind v1 = frame.pop();
                    JavaKind v2 = frame.pop();
                    JavaKind v3 = frame.pop();
                    JavaKind v4 = frame.pop();
                    frame.push(v2, false);
                    frame.push(v1, false);
                    frame.push(v4, false);
                    frame.push(v3, false);
                    frame.push(v2, false);
                    frame.push(v1, false);
                    break;
                }
                case SWAP: {
                    JavaKind k1 = frame.pop();
                    JavaKind k2 = frame.pop();
                    frame.push(k1, false);
                    frame.push(k2, false);
                    break;
                }
                case LADD, LSUB, LMUL, LDIV, LREM, LSHL, LSHR, LUSHR, LAND, LOR, LXOR:
                    frame.pop2();
                    frame.pop2();
                    frame.push(JavaKind.Long);
                    break;
                case DADD, DSUB, DMUL, DDIV, DREM:
                    frame.pop2();
                    frame.pop2();
                    frame.push(JavaKind.Double);
                    break;
                case INEG, F2I, I2B, I2C, I2S: // fallthrough
                case ARRAYLENGTH: // fallthrough
                case INSTANCEOF:
                    frame.pop();
                    frame.push(JavaKind.Int);
                    break;
                case LNEG, D2L:
                    frame.pop2();
                    frame.push(JavaKind.Long);
                    break;
                case FNEG, I2F:
                    frame.pop();
                    frame.push(JavaKind.Float);
                    break;
                case DNEG, L2D:
                    frame.pop2();
                    frame.push(JavaKind.Double);
                    break;
                case I2L, F2L:
                    frame.pop();
                    frame.push(JavaKind.Long);
                    break;
                case I2D, F2D:
                    frame.pop();
                    frame.push(JavaKind.Double);
                    break;
                case L2I, D2I:
                    frame.pop2();
                    frame.push(JavaKind.Int);
                    break;
                case L2F, D2F:
                    frame.pop2();
                    frame.push(JavaKind.Float);
                    break;
                case LCMP, DCMPL, DCMPG:
                    frame.pop2();
                    frame.pop2();
                    frame.push(JavaKind.Int);
                    break;
                case IFEQ, IFNE, IFLT, IFGE, IFGT, IFLE, IFNULL, IFNONNULL:
                    frame.pop();
                    branch(bci, bs.readBranchDest(bci), frame);
                    break;
                case IF_ICMPEQ, IF_ICMPNE, IF_ICMPLT, IF_ICMPGE, IF_ICMPGT, IF_ICMPLE, IF_ACMPEQ, IF_ACMPNE:
                    frame.pop();
                    frame.pop();
                    branch(bci, bs.readBranchDest(bci), frame);
                    break;
                case GOTO, GOTO_W:
                    branch(bci, bs.readBranchDest(bci), frame);
                    return;
                case JSR, JSR_W, RET:
                    throw EspressoError.shouldNotReachHere("Should have prevented jsr/ret");
                case TABLESWITCH, LOOKUPSWITCH: {
                    frame.pop();
                    BytecodeSwitch bytecodeSwitch = BytecodeSwitch.get(bci);
                    for (int i = 0; i <= bytecodeSwitch.numberOfCases(bs, bci); i++) {
                        branch(bci, i, frame);
                    }
                    branch(bci, bytecodeSwitch.defaultTarget(bs, bci), frame);
                    return;
                }
                case IRETURN, FRETURN, ARETURN, ATHROW:
                    frame.pop();
                    return;
                case LRETURN, DRETURN:
                    frame.pop2();
                    return;
                case RETURN:
                    return;
                case GETSTATIC, GETFIELD: {
                    Symbol<Type> type = pool.fieldAt(bs.readCPI(bci)).getType(pool);
                    if (opcode == GETFIELD) {
                        frame.pop();
                    }
                    frame.push(Types.getJavaKind(type));
                    break;
                }
                case PUTSTATIC, PUTFIELD: {
                    Symbol<Type> type = pool.fieldAt(bs.readCPI(bci)).getType(pool);
                    if (Types.getJavaKind(type).needsTwoSlots()) {
                        frame.pop2();
                    } else {
                        frame.pop();
                    }
                    if (opcode == PUTFIELD) {
                        frame.pop();
                    }
                    break;
                }
                case INVOKEVIRTUAL, INVOKESPECIAL, INVOKESTATIC, INVOKEINTERFACE: {
                    handleInvoke(frame, bci, opcode, true);
                    break;
                }
                case NEWARRAY, ANEWARRAY:
                    frame.pop();
                    frame.push(JavaKind.Object);
                    break;
                case MULTIANEWARRAY: {
                    int dim = bs.readUByte(bci + 3);
                    for (int i = 0; i < dim; i++) {
                        frame.pop();
                    }
                    frame.push(JavaKind.Object);
                    break;
                }
                case INVOKEDYNAMIC: {
                    InvokeDynamicConstant indy = pool.indyAt(bs.readCPI(bci));
                    Symbol<Type>[] sig = lang.getSignatures().parsed(indy.getSignature(pool));
                    popSignature(sig, true, frame);
                    frame.push(Signatures.returnKind(sig));
                    break;
                }
                default:
                    throw EspressoError.shouldNotReachHere(Bytecodes.nameOf(opcode));

            }
            la.performPostBCI(frame, bci);
            if (Bytecodes.canTrap(opcode)) {
                ExceptionHandler[] handlers = m.getExceptionHandlers();
                for (ExceptionHandler handler : handlers) {
                    if (handler.covers(bci)) {
                        Builder copy = frame.copy();
                        copy.clearStack();
                        copy.push(JavaKind.Object);
                        branch(bci, handler.getHandlerBCI(), copy);
                    }
                }
            }
            int next = bs.nextBCI(bci);
            la.performOnEdge(frame, bci, next);
            bci = next;
        }
    }

    private void handleInvoke(Builder frame, int bci, int opcode, boolean pushResult) {
        MethodRefConstant ref = pool.methodAt(bs.readCPI(bci));
        Symbol<Type>[] sig = lang.getSignatures().parsed(ref.getSignature(pool));
        popSignature(sig, opcode == INVOKESTATIC, frame);
        if (pushResult) {
            frame.push(Signatures.returnKind(sig));
        }
    }

    private boolean merge(int bci, Builder frame) {
        Builder targetState = states[bci];
        if (targetState == null) {
            registerState(bci, frame.copy());
            return false;
        }
        Builder merged = frame.mergeInto(targetState, bci);
        if (merged == targetState) {
            return true;
        }
        assert la.isEmpty();
        registerState(bci, merged);
        return false;
    }

    private void ldc(int bci, Builder frame) {
        char cpi = bs.readCPI(bci);
        ConstantPool.Tag tag = pool.tagAt(cpi);
        switch (tag) {
            case INTEGER -> frame.push(JavaKind.Int);
            case FLOAT -> frame.push(JavaKind.Float);
            case LONG -> frame.push(JavaKind.Long);
            case DOUBLE -> frame.push(JavaKind.Double);
            case CLASS, STRING, METHODHANDLE, METHODTYPE -> frame.push(JavaKind.Object);
            case DYNAMIC -> frame.push(Types.getJavaKind(((DynamicConstant) pool.at(cpi)).getTypeSymbol(pool)));
            default -> throw EspressoError.shouldNotReachHere(tag.toString());
        }
    }

    private void branch(int from, int target, Builder f) {
        assert f.isWorking();
        Builder targetState = states[target];
        if (targetState == null) {
            Builder newState = f.copy();
            la.performOnEdge(newState, from, target);
            registerState(target, newState);
            push(target);
            return;
        }
        // The state stored in the states has already been applied liveness analysis.
        assert targetState.isRecord();
        Builder merged = f.mergeInto(targetState, target);
        if (merged == targetState) {
            return;
        }
        assert la.isEmpty();
        registerState(target, merged);
        processStatus.clear(target);
        push(target);
    }

    private void registerState(int target, Builder newState) {
        assert newState.isWorking();
        assert (states[target] == null || (newState.sameTop(states[target])));
        Builder copy = newState.copy();
        copy.setBci(target);
        assert copy.isRecord();
        states[target] = copy;
    }

    private void push(int bci) {
        assert states[bci] != null;
        assert states[bci].isRecord();
        queue.push(bci);
    }

    private int pop() {
        int next = queue.pop();
        assert states[next] != null && states[next].isRecord();
        return next;
    }
}

/**
 * This class generates {@link LabeledBlock}s that enable us to do forward jumps and skip over basic
 * blocks.
 *
 * This class iterates over all basic blocks and checks for each forward edge if a
 * {@link LabeledBlock} is needed and generates one if that is the case. We store mappings from
 * {@link HIRBlock} to {@link LabeledBlock} in order to store where a {@link LabeledBlock} starts
 * and ends. {@link StackifierIRWalker} uses these maps to generate the corresponding code before
 * each basic block.
 *
 * See {@link StackifierIRWalker} for some examples.
 *
 */
public class LabeledBlockGeneration {

    public static final String LabeledBlockPrefix = "lb";

    /**
     * The beginnings of the LabeledBlocks need to be sorted such that the outermost block is
     * generated first and the innermost block last, if multiple labeled blocks start at the same
     * basic block.
     */
    protected final EconomicMap<HIRBlock, SortedSet<LabeledBlock>> labeledBlockStarts = EconomicMap.create();
    protected final EconomicMap<HIRBlock, LabeledBlock> labeledBlockEnds = EconomicMap.create();

    protected final LabeledBlockGenerator labeledBlockGenerator = new LabeledBlockGenerator();
    protected final ControlFlowGraph cfg;
    protected final StackifierData stackifierData;

    public LabeledBlockGeneration(StackifierData stackifierData, ControlFlowGraph cfg) {
        this.stackifierData = stackifierData;
        this.cfg = cfg;
    }

    /**
     * Checks whether a LabeledBlock needs to be generated for the edge from block to successor. No
     * LabeledBlock will be generated if the successor is reached via a back edge, i.e. the block is
     * a loop end.
     *
     * Example: Suppose we have the Java program where A, B and C roughly correspond to basic
     * blocks.
     *
     * <pre>
     * if (A()) {
     *     B();
     * }
     * C();
     * </pre>
     *
     * The only valid topological order is A->B->C. The basic blocks will be lowered in that order.
     * The basic block A has two successors, namely B and C. The code for B can be generated
     * directly after A, since B directly follows A. Therefore we do not need a {@link LabeledBlock}
     * in that case. But for the successor C we need a jump that skips B. Therefore for A and C a
     * {@link LabeledBlock} is needed. This will produce the following pseudocode.
     *
     * <pre>
     * block0: {
     *     if (A()) {
     *
     *     } else {
     *         break block0;
     *     }
     *     B();
     * } // block0
     * C();
     * </pre>
     *
     * @param block start of the edge
     * @param successor end of the edge
     * @return true iff a {@link LabeledBlock} is needed
     */
    public boolean isLabeledBlockNeeded(HIRBlock block, HIRBlock successor) {
        if (assertionsEnabled()) {
            boolean found = false;
            for (int i = 0; i < block.getSuccessorCount(); i++) {
                HIRBlock s = block.getSuccessorAt(i);
                found = found || s == successor;
            }
            assert found;
        }
        ScopeContainer scopeContainer = stackifierData.getScopeEntry(block.getEndNode());
        if (block.isLoopEnd()) {
            assert block.getSuccessorCount() == 1 : Assertions.errorMessage(block);
            // loopEndNodes have back edges and therefore do not need a forward jump
            return false;
        }
        if (isNormalLoopExit(block, successor, stackifierData)) {
            return false;
        }

        if (block.getEndNode() instanceof IfNode) {
            if (((IfNode) block.getEndNode()).trueSuccessor() == successor.getBeginNode()) {
                // successor is the true successor
                if (((IfScopeContainer) scopeContainer).getThenScope() != null) {
                    return false;
                }
            } else {
                if (((IfScopeContainer) scopeContainer).getElseScope() != null) {
                    return false;
                }
            }
        } else if (block.getEndNode() instanceof InvokeWithExceptionNode) {
            InvokeWithExceptionNode invokeWithExc = (InvokeWithExceptionNode) block.getEndNode();
            if (invokeWithExc.getPrimarySuccessor() == successor.getBeginNode()) {
                return !isJumpingOverCatchBlock(block, successor, stackifierData);
            } else {
                assert invokeWithExc.exceptionEdge() == successor.getBeginNode() : Assertions.errorMessage(invokeWithExc, successor);
                if (((CatchScopeContainer) scopeContainer).getCatchScope() != null) {
                    return false;
                }
            }
        } else if (block.getEndNode() instanceof IntegerSwitchNode) {
            IntegerSwitchNode switchNode = (IntegerSwitchNode) block.getEndNode();
            Scope[] caseScopes = ((SwitchScopeContainer) stackifierData.getScopeEntry(switchNode)).getCaseScopes();
            for (int i = 0; i < switchNode.getSuccessorCount(); i++) {
                if (switchNode.blockSuccessor(i) == successor.getBeginNode()) {
                    return caseScopes[i] == null;
                }
            }
            GraalError.shouldNotReachHere("successor of switchnode not found in its successor list"); // ExcludeFromJacocoGeneratedReport
        }
        if (isLastBlockInThenBranch(block, stackifierData)) {
            return !isJumpingToAfterElseBranch(block, successor, stackifierData);
        }
        if (isLastBlockInSwitchArm(block, stackifierData)) {
            /*
             * Always generate a labeled block around switch statements as a target for switch arms
             * to jump out of. This can result in less than optimal code if all switch arms jump to
             * the merge block after the switch, but determining that is tricky to do correctly
             * without having knowing the order in which blocks will be lowered.
             */
            return true;
        }
        return successor.getId() != block.getId() + 1;
    }

    /**
     * Checks if the last block in a then branch jumps to after the else scope of an {@link IfNode}.
     *
     * Example:
     *
     * <pre>
     * if (condition) {
     *     A();
     * } else {
     *     B();
     * }
     * C();
     * </pre>
     *
     * In the example above, we have an edge from the basic block {@code A} to {@code C}. We do not
     * need a labeled break for this edge, since we jump to {@code C} automatically from {@code A}.
     *
     * @param block last block in a then-branch of an {@link IfNode}, see
     *            {@link #isLastBlockInThenBranch}
     * @param successor target of the jump
     * @return true iff the edge from {@code block} to {@code successor} jumps over the else scope
     *         of the {@link IfNode}
     */
    private static boolean isJumpingToAfterElseBranch(HIRBlock block, HIRBlock successor, StackifierData stackifierData) {
        Scope scope = stackifierData.getEnclosingScope().get(block);
        HIRBlock startBlock = scope.getStartBlock();
        IfScopeContainer ifScopeContainer = (IfScopeContainer) stackifierData.getScopeEntry(startBlock.getEndNode());
        Scope elseScope = ifScopeContainer.getElseScope();
        if (elseScope == null) {
            return false;
        }
        HIRBlock[] blocks = stackifierData.getBlocks();
        for (int id = block.getId() + 1; id < successor.getId(); id++) {
            if (!elseScope.getBlocks().contains(blocks[id])) {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if the given block is the last block in the then-branch of an {@link IfNode}.
     *
     * Example:
     *
     * <pre>
     * if (condition) {
     *     A();
     *     B();
     * } else {
     *     C();
     * }
     * </pre>
     *
     * For the example above this function returns true for the basic block {@code B} and false
     * otherwise.
     */
    private static boolean isLastBlockInThenBranch(HIRBlock block, StackifierData stackifierData) {
        Scope scope = stackifierData.getEnclosingScope().get(block);
        if (scope != null) {
            HIRBlock startBlock = scope.getStartBlock();
            if (startBlock.getEndNode() instanceof IfNode) {
                IfScopeContainer ifScopeContainer = (IfScopeContainer) stackifierData.getScopeEntry(startBlock.getEndNode());
                return ifScopeContainer.getThenScope() == scope && scope.getLastBlock() == block;
            }
        }
        return false;
    }

    /**
     * Checks if the given block is the last block in one of the arms of an
     * {@link IntegerSwitchNode}.
     *
     * Example:
     *
     * <pre>
     * switch (x) {
     *     case 1:
     *         A();
     *         B();
     *         break;
     * }
     * C();
     * </pre>
     *
     * For the example above this function returns true for the basic block {@code B} and false
     * otherwise.
     */
    private static boolean isLastBlockInSwitchArm(HIRBlock block, StackifierData stackifierData) {
        Scope scope = stackifierData.getEnclosingScope().get(block);
        if (scope != null) {
            HIRBlock startBlock = scope.getStartBlock();
            if (startBlock.getEndNode() instanceof IntegerSwitchNode) {
                return scope.getLastBlock() == block;
            }
        }
        return false;
    }

    /**
     * Checks if the edge from {@code block} to {@code successor} is jumping over all
     * {@link HIRBlock}s in the catch scope.
     * <p>
     * Example:
     *
     * <pre>
     *     try {
     *         A()
     *     } catch (e) {
     *         B(e);
     *     }
     *     C();
     * </pre>
     * <p>
     * In the above example, basic block {@code C} is the primary successor of {@code A}. For this
     * edge we do not need to generate a labeled break because at the end of the {@code try} block,
     * we jump to after the catch block implicitly.
     *
     * @param block block ending with a {@link InvokeWithExceptionNode}
     * @param successor primary successor of the {@link InvokeWithExceptionNode}
     */
    private static boolean isJumpingOverCatchBlock(HIRBlock block, HIRBlock successor, StackifierData stackifierData) {
        assert block.getEndNode() instanceof InvokeWithExceptionNode : Assertions.errorMessage(block, block.getEndNode());
        assert block.getFirstSuccessor() == successor : Assertions.errorMessage(block, successor);
        CatchScopeContainer catchScopeContainer = (CatchScopeContainer) stackifierData.getScopeEntry(block.getEndNode());
        Scope catchScope = catchScopeContainer.getCatchScope();

        if (catchScope == null) {
            return false;
        }

        EconomicSet<HIRBlock> blocksInCatchScope = catchScope.getBlocks();
        HIRBlock[] allBlocks = stackifierData.getBlocks();
        for (int id = block.getId() + 1; id < successor.getId(); id++) {
            if (!blocksInCatchScope.contains(allBlocks[id])) {
                return false;
            }
        }
        return true;
    }

    /**
     * Check if the jump from {@code block} to {@code successor} is a simple break out of a loop. In
     * that case the jump can be simply done with a {@code break looplabel}, without having to
     * generate a {@link LabeledBlock}. Not "normal" loop exits can be caused by loops with multiple
     * exits that go to different basic blocks.
     *
     * Example:
     *
     * <pre>
     * block0: {
     *     while (condition) {
     *         A();
     *         if (condition1) {
     *             break;
     *         }
     *         B();
     *         if (condition2) {
     *             break block0;
     *         }
     *         C();
     *     } // end loop
     *     D();
     * } // block0
     * E();
     * </pre>
     *
     * In the above example, the break in the first if is a "normal" jump out of the loop and
     * therefore does not need a {@link LabeledBlock}. The second break jumps out of the loop and
     * skips some code after the loop. This jump needs a {@link LabeledBlock}.
     *
     * @param block start of the jump
     * @param successor end of the jump
     * @param stackifierData data from cf reconstruction
     * @return true iff the jump from block to successor can be done with a simple break statement,
     *         i.e. jump to the end of the loop.
     */
    public static boolean isNormalLoopExit(HIRBlock block, HIRBlock successor, StackifierData stackifierData) {
        CFGLoop<HIRBlock> l1 = block.getLoop();
        if (l1 != null) {
            HIRBlock lastLoopBlock = ((LoopScopeContainer) stackifierData.getScopeEntry(l1.getHeader().getBeginNode())).getLoopScope().getLastBlock();
            return lastLoopBlock.getId() + 1 == successor.getId();
        }
        return false;
    }

    private boolean areNextInOrder(HIRBlock successor, HIRBlock lastLoopBlock) {
        return lastLoopBlock.getId() + 1 == successor.getId();
    }

    /**
     * Creates a new sortedSet for {@link LabeledBlock}. The {@link LabeledBlock} are sorted such
     * that the block that closes last comes first, i.e. they are sorted by descending block id of
     * their ending basic blocks. This is useful for sorting {@link LabeledBlock} that start at the
     * same basic block such that the outermost {@link LabeledBlock} comes first and the innermost
     * last.
     *
     * @return sorted Set according to the ends of the {@link LabeledBlock}s
     */
    public static SortedSet<LabeledBlock> getSortedSetByLabeledBlockEnd() {
        return new TreeSet<>((b1, b2) -> b2.getEnd().getId() - b1.getEnd().getId());
    }

    private static HIRBlock commonDominatorFor(HIRBlock b, boolean pred) {
        HIRBlock commonDom = null;
        for (int i = 0; i < (pred ? b.getPredecessorCount() : b.getSuccessorCount()); i++) {
            HIRBlock block = pred ? b.getPredecessorAt(i) : b.getSuccessorAt(i);
            commonDom = (HIRBlock) AbstractControlFlowGraph.commonDominator(commonDom, block);
        }
        return commonDom;
    }

    /**
     * Iterates over all basic block and checks for each forward edge if a {@link LabeledBlock} is
     * needed. If a {@link LabeledBlock} already ends at the jump target, no new
     * {@link LabeledBlock} is generated and instead the existing one will be used.
     */
    public void generateLabeledBlocks() {
        stackifierData.setLabeledBlockStarts(labeledBlockStarts);
        stackifierData.setLabeledBlockEnd(labeledBlockEnds);

        for (HIRBlock block : stackifierData.getBlocks()) {
            for (int i = 0; i < block.getSuccessorCount(); i++) {
                HIRBlock successor = block.getSuccessorAt(i);
                if (isLabeledBlockNeeded(block, successor)) {
                    HIRBlock labeledBlockStart = getLabeledBlockStart(block, successor);

                    if (!labeledBlockEndsBeforeBasicBlock(successor)) {
                        LabeledBlock labeledBlock = labeledBlockGenerator.generateLabeledBlock(labeledBlockStart, successor);
                        addToMaps(labeledBlock);
                    }
                }
            }
        }
    }

    /**
     * Get the position where a LabeledBlock can start. Compute common dominator of all predecessors
     * of {@code successor} and then move the start of the LabeledBlock up until all
     * {@link LabeledBlock} that end between {@code predecessor} and {@code successor} are closed.
     *
     * The end of the {@link LabeledBlock} is determined by the jump target, e.g. it has to end
     * before C in the example below. But for the start of the {@link LabeledBlock} we have more
     * freedom. We could place the start at the very beginning of the function (or if we are inside
     * a loop, right after the loop header). This would result in very deeply nested blocks. The
     * later the block start is generated the lower the nesting will be. Therefore, we try to place
     * the start as late as possible.
     *
     * For this 2 things need to be considered. If multiple basic blocks jump to the target, all
     * these basic blocks must be contained within the {@link LabeledBlock}. Secondly, since the
     * {@link LabeledBlock} cannot overlap, we have to put the start before all
     * {@link LabeledBlock}s that end between {@code predecessor} and {@code successor}.
     *
     * Example: Suppose we have the Java program:
     *
     * <pre>
     * if (A()) {
     *     B();
     * } else {
     *     C();
     * }
     * D();
     * </pre>
     *
     * If we have the topological order A->B->C->D we need a {@link LabeledBlock} from B to D in
     * order to jump over C. D has two predecessors, namely B and C, which are dominated by A. Thus
     * the {@link LabeledBlock} has to start at least before A. If there were {@link LabeledBlock}s
     * ending between {@code predecessor} and {@code successor}, we would place the start of the new
     * {@link LabeledBlock} before all of them.
     *
     * @param predecessor basic block from where the jump is done
     * @param successor target of the jump
     * @return basic block where the "blockLabel:{ ..." should be placed
     */
    private HIRBlock getLabeledBlockStart(HIRBlock predecessor, HIRBlock successor) {
        HIRBlock earliestStart = predecessor;
        if (successor.getPredecessorCount() > 1) {
            earliestStart = commonDominatorFor(successor, true);
        }
        Scope startScope = stackifierData.getEnclosingScope().get(earliestStart);
        Scope endScope = stackifierData.getEnclosingScope().get(successor);
        if (successor.isLoopHeader()) {
            /**
             * Special case when successor is a loop header: A loop scope includes the loopHeader
             * (see {@link StackifierScopeComputation#computeLoopScopes()}), whereas other scopes do
             * not include the basic block that creates a scope. For example, a basic block
             * containing an {@link IfNode} does not belong to the respective then-scope a
             * else-scope. Consequently, if successor is a loop Header, {@code endScope} is the
             * loopScope created by {@code successor}. But we want to jump to just before
             * {@code successor}. Therefore, {@code endScope} should be the scope that contains the
             * loop created by {@code successor} which is the parent scope.
             */
            endScope = endScope.getParentScope();
        }
        if (startScope != endScope) {
            while (startScope != null && startScope.getParentScope() != endScope) {
                startScope = startScope.getParentScope();
            }
            if (startScope == null) {
                assert endScope == null : cfg.graph.method().getDeclaringClass().getUnqualifiedName() + "." + cfg.graph.method().getName() + " Cannot jump from start of a method into a scope " +
                                endScope;
                earliestStart = cfg.getStartBlock();
            } else {
                earliestStart = startScope.getStartBlock();
            }
        }
        for (HIRBlock b : labeledBlockEnds.getKeys()) {
            if (predecessor.getId() < b.getId() && b.getId() < successor.getId()) {
                // a LabeledBlock ends between break and ".. }"
                LabeledBlock forwardBlock = labeledBlockEnds.get(b);
                if (forwardBlock.getStart().getId() < earliestStart.getId()) {
                    earliestStart = forwardBlock.getStart();
                }
            }
        }
        return earliestStart;
    }

    /**
     * Checks if a {@link LabeledBlock} ends before the given basic block.
     *
     * @param labeledBlockEnd basic block for which a {@link LabeledBlock} is queried
     * @return true iff a {@link LabeledBlock} ends before {@code labeledBlockEnd}
     */
    private boolean labeledBlockEndsBeforeBasicBlock(HIRBlock labeledBlockEnd) {
        return labeledBlockEnds.get(labeledBlockEnd) != null;
    }

    /**
     * Stores the given {@link LabeledBlock} in maps that map from {@link HIRBlock} to the start and
     * end of the given {@link LabeledBlock}. These maps will be used in the
     * {@link StackifierIRWalker} for generating the corresponding code before or after a basic
     * block.
     *
     * @param labeledBLock block to be stored in the maps
     */
    private void addToMaps(LabeledBlock labeledBLock) {
        if (labeledBlockStarts.get(labeledBLock.getStart()) == null) {
            labeledBlockStarts.put(labeledBLock.getStart(), getSortedSetByLabeledBlockEnd());
        }
        labeledBlockStarts.get(labeledBLock.getStart()).add(labeledBLock);
        HIRBlock endBlock = labeledBLock.getEnd();
        assert !labeledBlockEnds.containsKey(endBlock);
        labeledBlockEnds.put(endBlock, labeledBLock);
    }

    /**
     * Generates {@link LabeledBlock}s with unique labels.
     */
    private static class LabeledBlockGenerator {

        private int currentId = 0;

        public LabeledBlock generateLabeledBlock(HIRBlock start, HIRBlock end) {
            return new LabeledBlock(start, end, currentId++);
        }
    }
}

/**
 * Collects all VM thread local variables during native image generation and assigns them their
 * offset in the {@link IsolateThread} data structure.
 */
@AutomaticallyRegisteredFeature
@Platforms(InternalPlatform.NATIVE_ONLY.class)
public class VMThreadFeature implements InternalFeature {

    private final VMThreadLocalCollector threadLocalCollector = new VMThreadLocalCollector();
    private final VMThreadLocalSupport threadLocalSupport = new VMThreadLocalSupport();

    @Override
    public void duringSetup(DuringSetupAccess config) {
        ImageSingletons.add(VMThreadLocalSupport.class, threadLocalSupport);
        /*
         * While technically threadLocalCollector does not replace an object, it does collect
         * information needed by the invocation plugin used to create VMThreadLocalAccess nodes (and
         * also remove the original FastThreadLocal constant from the graph).
         *
         * It would be possible to create VMThreadLocalAccess nodes via a canonicalization phase
         * after analysis has completed, which would have the potential benefit of reducing the
         * number of thread locals instantiated; however, this requires careful coordination with
         * snippet graphs, especially for runtime compilation, and likely the added complexity would
         * outweigh the benefits.
         */
        config.registerObjectReplacer(threadLocalCollector);
    }

    /**
     * Intrinsify the {@code get()} and {@code set()} methods during bytecode parsing. We know that
     * every subclass of VMThreadLocal has the same methods. Only the signatures differ based on the
     * type of value.
     * <p>
     * When the {@link IsolateThread} is not passed in as a parameter, we use the
     * {@link LoadVMThreadLocalNode current thread}. We do not need read/write barriers since we
     * access memory that we manage ourselfs.
     */
    @Override
    public void registerInvocationPlugins(Providers providers, Plugins plugins, ParsingReason reason) {
        for (Class<? extends FastThreadLocal> threadLocalClass : VMThreadLocalInfo.THREAD_LOCAL_CLASSES) {
            Registration r = new Registration(plugins.getInvocationPlugins(), threadLocalClass);
            Class<?> valueClass = VMThreadLocalInfo.getValueClass(threadLocalClass);
            registerAccessors(r, valueClass, false);
            registerAccessors(r, valueClass, true);

            /* compareAndSet() method without the VMThread parameter. */
            r.register(new RequiredInvocationPlugin("compareAndSet", Receiver.class, valueClass, valueClass) {
                @Override
                public boolean apply(GraphBuilderContext b, ResolvedJavaMethod targetMethod, Receiver receiver, ValueNode expect, ValueNode update) {
                    ValueNode threadNode = currentThread(b);
                    return handleCompareAndSet(b, targetMethod, receiver, threadNode, expect, update);
                }
            });
            /* get() method with the VMThread parameter. */
            r.register(new RequiredInvocationPlugin("compareAndSet", Receiver.class, IsolateThread.class, valueClass, valueClass) {
                @Override
                public boolean apply(GraphBuilderContext b, ResolvedJavaMethod targetMethod, Receiver receiver, ValueNode threadNode, ValueNode expect, ValueNode update) {
                    return handleCompareAndSet(b, targetMethod, receiver, threadNode, expect, update);
                }
            });
        }

        Class<?>[] typesWithGetAddress = new Class<?>[]{FastThreadLocalBytes.class, FastThreadLocalWord.class};
        for (Class<?> type : typesWithGetAddress) {
            Registration r = new Registration(plugins.getInvocationPlugins(), type);
            /* getAddress() method without the VMThread parameter. */
            r.register(new RequiredInvocationPlugin("getAddress", Receiver.class) {
                @Override
                public boolean apply(GraphBuilderContext b, ResolvedJavaMethod targetMethod, Receiver receiver) {
                    ValueNode threadNode = currentThread(b);
                    return handleGetAddress(b, targetMethod, receiver, threadNode);
                }
            });
            /* getAddress() method with the VMThread parameter. */
            r.register(new RequiredInvocationPlugin("getAddress", Receiver.class, IsolateThread.class) {
                @Override
                public boolean apply(GraphBuilderContext b, ResolvedJavaMethod targetMethod, Receiver receiver, ValueNode threadNode) {
                    return handleGetAddress(b, targetMethod, receiver, threadNode);
                }
            });
        }
    }

    private void registerAccessors(Registration r, Class<?> valueClass, boolean isVolatile) {
        String suffix = isVolatile ? "Volatile" : "";

        /* get() method without the VMThread parameter. */
        r.register(new RequiredInvocationPlugin("get" + suffix, Receiver.class) {
            @Override
            public boolean apply(GraphBuilderContext b, ResolvedJavaMethod targetMethod, Receiver receiver) {
                ValueNode threadNode = currentThread(b);
                return handleGet(b, targetMethod, receiver, threadNode, isVolatile);
            }
        });
        /* get() method with the VMThread parameter. */
        r.register(new RequiredInvocationPlugin("get" + suffix, Receiver.class, IsolateThread.class) {
            @Override
            public boolean apply(GraphBuilderContext b, ResolvedJavaMethod targetMethod, Receiver receiver, ValueNode threadNode) {
                return handleGet(b, targetMethod, receiver, threadNode, isVolatile);
            }
        });
        /* set() method without the VMThread parameter. */
        r.register(new RequiredInvocationPlugin("set" + suffix, Receiver.class, valueClass) {
            @Override
            public boolean apply(GraphBuilderContext b, ResolvedJavaMethod targetMethod, Receiver receiver, ValueNode valueNode) {
                ValueNode threadNode = currentThread(b);
                return handleSet(b, receiver, threadNode, valueNode, isVolatile);
            }
        });
        /* set() method with the VMThread parameter. */
        r.register(new RequiredInvocationPlugin("set" + suffix, Receiver.class, IsolateThread.class, valueClass) {
            @Override
            public boolean apply(GraphBuilderContext b, ResolvedJavaMethod targetMethod, Receiver receiver, ValueNode threadNode, ValueNode valueNode) {
                return handleSet(b, receiver, threadNode, valueNode, isVolatile);
            }
        });
    }

    private static ValueNode currentThread(GraphBuilderContext b) {
        return b.add(ReadReservedRegister.createReadIsolateThreadNode(b.getGraph()));
    }

    private boolean handleGet(GraphBuilderContext b, ResolvedJavaMethod targetMethod, Receiver receiver, ValueNode threadNode, boolean isVolatile) {
        VMThreadLocalInfo threadLocalInfo = threadLocalCollector.findInfo(b, receiver.get(true));

        LoadVMThreadLocalNode node = new LoadVMThreadLocalNode(b.getMetaAccess(), threadLocalInfo, threadNode, BarrierType.NONE, isVolatile ? MemoryOrderMode.VOLATILE : MemoryOrderMode.PLAIN);
        b.addPush(targetMethod.getSignature().getReturnKind(), node);

        return true;
    }

    private boolean handleSet(GraphBuilderContext b, Receiver receiver, ValueNode threadNode, ValueNode valueNode, boolean isVolatile) {
        VMThreadLocalInfo threadLocalInfo = threadLocalCollector.findInfo(b, receiver.get(true));

        StoreVMThreadLocalNode store = b.add(new StoreVMThreadLocalNode(threadLocalInfo, threadNode, valueNode, BarrierType.NONE, isVolatile ? MemoryOrderMode.VOLATILE : MemoryOrderMode.PLAIN));
        assert store.stateAfter() != null : store + " has no state after with graph builder context " + b;
        return true;
    }

    private boolean handleCompareAndSet(GraphBuilderContext b, ResolvedJavaMethod targetMethod, Receiver receiver, ValueNode threadNode, ValueNode expect,
                    ValueNode update) {
        VMThreadLocalInfo threadLocalInfo = threadLocalCollector.findInfo(b, receiver.get(true));
        CompareAndSetVMThreadLocalNode cas = new CompareAndSetVMThreadLocalNode(threadLocalInfo, threadNode, expect, update);
        b.addPush(targetMethod.getSignature().getReturnKind(), cas);
        assert cas.stateAfter() != null : cas + " has no state after with graph builder context " + b;
        return true;
    }

    private boolean handleGetAddress(GraphBuilderContext b, ResolvedJavaMethod targetMethod, Receiver receiver, ValueNode threadNode) {
        VMThreadLocalInfo threadLocalInfo = threadLocalCollector.findInfo(b, receiver.get(true));
        b.addPush(targetMethod.getSignature().getReturnKind(), new AddressOfVMThreadLocalNode(threadLocalInfo, threadNode));
        return true;
    }

    @Override
    public void beforeCompilation(BeforeCompilationAccess config) {
        List<VMThreadLocalInfo> sortedThreadLocalInfos = threadLocalCollector.sortThreadLocals();
        SubstrateReferenceMap referenceMap = new SubstrateReferenceMap();
        int nextOffset = 0;
        nextOffset = sortAndAssignOffsets(sortedThreadLocalInfos, nextOffset, referenceMap);

        InstanceReferenceMapEncoder encoder = new InstanceReferenceMapEncoder();
        encoder.add(referenceMap);
        NonmovableArray<Byte> referenceMapEncoding = encoder.encodeAll();
        threadLocalSupport.vmThreadReferenceMapEncoding = NonmovableArrays.getHostedArray(referenceMapEncoding);
        threadLocalSupport.vmThreadReferenceMapIndex = encoder.lookupEncoding(referenceMap);
        threadLocalSupport.vmThreadSize = nextOffset;

        /* Remember the final sorted list. */
        VMThreadLocalInfos.setInfos(sortedThreadLocalInfos);
    }

    private int sortAndAssignOffsets(List<VMThreadLocalInfo> sortedThreadLocalInfos, int nextOffset, SubstrateReferenceMap referenceMap) {
        for (VMThreadLocalInfo info : sortedThreadLocalInfos) {
            int alignment = Math.min(8, info.sizeInBytes);
            nextOffset = NumUtil.roundUp(nextOffset, alignment);

            if (info.isObject) {
                referenceMap.markReferenceAtOffset(nextOffset, true);
            }
            info.offset = nextOffset;
            nextOffset += info.sizeInBytes;

            if (info.offset > info.maxOffset) {
                VMError.shouldNotReachHere("Too many thread local variables with maximum offset " + info.maxOffset + " defined");
            }
        }
        return nextOffset;
    }

    public int offsetOf(FastThreadLocal threadLocal) {
        return threadLocalCollector.getInfo(threadLocal).offset;
    }
}

/**
 * Floating point to integer conversion according to Java semantics. This wraps an AMD64 conversion
 * instruction and adjusts its result as needed. According to Java semantics, NaN inputs should be
 * mapped to 0, and values outside the integer type's range should be mapped to {@code MIN_VALUE} or
 * {@code MAX_VALUE} according to the input's sign. The AMD64 instructions produce {@code MIN_VALUE}
 * for NaNs and all values outside the integer type's range. So we need to fix up the result for
 * NaNs and positive overflowing values. Negative overflowing values keep {@code MIN_VALUE}.
 */
public class AMD64ConvertFloatToIntegerOp extends AMD64LIRInstruction {
    public static final LIRInstructionClass<AMD64ConvertFloatToIntegerOp> TYPE = LIRInstructionClass.create(AMD64ConvertFloatToIntegerOp.class);

    @Def({REG}) protected Value dstValue;
    @Alive({REG}) protected Value srcValue;
    @Temp({REG, ILLEGAL}) protected Value tmpValue;

    private final OpcodeEmitter opcode;
    private final boolean canBeNaN;
    private final boolean canOverflow;

    @FunctionalInterface
    public interface OpcodeEmitter {
        /** Emit the actual conversion instruction. */
        void emit(CompilationResultBuilder crb, AMD64MacroAssembler masm, Register dst, Register src);
    }

    public AMD64ConvertFloatToIntegerOp(LIRGeneratorTool tool, OpcodeEmitter opcode, Value dstValue, Value srcValue, boolean canBeNaN, boolean canOverflow) {
        super(TYPE);
        this.dstValue = dstValue;
        this.srcValue = srcValue;
        this.opcode = opcode;
        this.tmpValue = canOverflow ? tool.newVariable(srcValue.getValueKind()) : Value.ILLEGAL;
        this.canBeNaN = canBeNaN;
        this.canOverflow = canOverflow;

        GraalError.guarantee(srcValue.getPlatformKind() instanceof AMD64Kind kind && kind.getVectorLength() == 1 && kind.isXMM(), "source must be scalar floating-point: %s", srcValue);
        GraalError.guarantee(dstValue.getPlatformKind() instanceof AMD64Kind kind && kind.getVectorLength() == 1 && kind.isInteger(), "destination must be integer: %s", dstValue);
    }

    @Override
    public void emitCode(CompilationResultBuilder crb, AMD64MacroAssembler masm) {
        Register dst = asRegister(dstValue);
        Register src = asRegister(srcValue);
        Label fixupPath = new Label();
        Label done = new Label();

        opcode.emit(crb, masm, dst, src);

        if (!canBeNaN && !canOverflow) {
            /* No fixup needed. */
            return;
        }

        int integerBytes = dstValue.getPlatformKind().getSizeInBytes();
        GraalError.guarantee(integerBytes == 4 || integerBytes == 8, "unexpected target %s", dstValue);
        OperandSize floatSize = switch (srcValue.getPlatformKind().getSizeInBytes()) {
            case 4 -> OperandSize.PS;
            case 8 -> OperandSize.PD;
            default -> throw GraalError.shouldNotReachHere("unexpected input %s".formatted(srcValue));
        };

        /*
         * if (dst == MIN_VALUE) { goto fixupPath; }
         */
        if (integerBytes == 4) {
            masm.cmplAndJcc(dst, Integer.MIN_VALUE, AMD64Assembler.ConditionFlag.Equal, fixupPath, false);
        } else {
            masm.cmpq(dst, (AMD64Address) crb.asLongConstRef(JavaConstant.forLong(Long.MIN_VALUE)));
            masm.jcc(AMD64Assembler.ConditionFlag.Equal, fixupPath);
        }

        crb.getLIR().addSlowPath(this, () -> {
            masm.bind(fixupPath);

            if (canBeNaN) {
                /*
                 * if (isNaN(src)) { result = 0; goto done; }
                 *
                 * The isNaN check is implemented as src != src. C2's fixup stubs check for a NaN
                 * bit pattern directly, using the same number of cycles but using an extra general
                 * purpose register.
                 */
                Label isNotNaN = new Label();
                UCOMIS.emit(masm, floatSize, src, src);
                masm.jcc(AMD64Assembler.ConditionFlag.NoParity, isNotNaN, true);
                moveInt(masm, dst, 0);
                masm.jmp(done);
                masm.bind(isNotNaN);
            }

            if (canOverflow) {
                /*
                 * if (src > 0.0) { result = MAX_VALUE; }
                 *
                 * We use an actual floating point compare, C2's stubs check the sign bit in a GPR.
                 */
                Register zero = asRegister(tmpValue);
                masm.pxor(AVXKind.AVXSize.XMM, zero, zero);
                UCOMIS.emit(masm, floatSize, src, zero);
                masm.jcc(AMD64Assembler.ConditionFlag.BelowEqual, done);
                /*
                 * MAX_VALUE is the bitwise negation of MIN_VALUE, which is already in dst. A
                 * negation takes the same number of cycles as a move, but its encoding is shorter.
                 */
                if (integerBytes == 4) {
                    masm.notl(dst);
                } else {
                    masm.notq(dst);
                }
            }

            /* Return to inline code. */
            masm.jmp(done);
        });

        masm.bind(done);
    }

    private void moveInt(AMD64MacroAssembler masm, Register dst, int imm) {
        if (imm == 0) {
            Register zeroValueRegister = masm.getZeroValueRegister();
            if (!Register.None.equals(zeroValueRegister)) {
                masm.movl(dst, zeroValueRegister);
                return;
            }
        }
        masm.movl(dst, imm);
    }
}

